// Safari・file://環境でも起動できる安全なストレージラッパー
// localStorageが使えないとメモリ保存に落ちるが、**黙って落ちると再読込で全部消えたように見える**ため
// storageIsMemoryOnly を立てて画面上に警告を出す
let storageIsMemoryOnly = false;
const safeStorage = (() => {
  const memory = new Map();
  try {
    const testKey = "__sns_ops_storage_test__";
    window.localStorage.setItem(testKey, "1");
    window.localStorage.removeItem(testKey);
    return window.localStorage;
  } catch (error) {
    console.warn("localStorageを利用できないため、一時メモリ保存で起動します。", error);
    storageIsMemoryOnly = true;
    return {
      getItem(key) { return memory.has(key) ? memory.get(key) : null; },
      setItem(key, value) { memory.set(key, String(value)); },
      removeItem(key) { memory.delete(key); },
      clear() { memory.clear(); }
    };
  }
})();
