/** localStorageの生データを競合投稿スキーマへ正規化（competitorPosts・competitorDraft共通）。 */
function normalizeCompetitorPost(p) {
  p = p || {};
  return {
    id: p.id || "",
    competitorId: p.competitorId || "",
    channels: Array.isArray(p.channels) ? p.channels : (p.channel ? [p.channel] : []),
    channel: p.channel || (Array.isArray(p.channels) ? p.channels[0] : "") || "",
    postDate: p.postDate || "",
    postTime: p.postTime || "",
    url: p.url || "",
    theme: p.theme || "",
    format: p.format || "",
    campaign: p.campaign || "",
    owner: p.owner || "",
    tags: Array.isArray(p.tags) ? p.tags : (p.tags ? [p.tags] : []),
    memo: p.memo || "",
    likes: numberValue(p.likes), comments: numberValue(p.comments), shares: numberValue(p.shares), plays: numberValue(p.plays), followers: numberValue(p.followers),
    purpose: p.purpose || "",
    target: p.target || "", hook: p.hook || "", caption: p.caption || "", ctaText: p.ctaText || "", cta: p.cta || "",
    successFactor: p.successFactor || "", improveIdea: p.improveIdea || "",
    imitatePoint: p.imitatePoint || "", weakness: p.weakness || "", avoidPoint: p.avoidPoint || "", actionMemo: p.actionMemo || "",
    design: p.design || "", copy: p.copy || "",
    rating: numberValue(p.rating),
    screenshots: Array.isArray(p.screenshots) ? p.screenshots : (p.screenshot ? [p.screenshot] : []),
    relatedOwnTheme: p.relatedOwnTheme || "",
    ownInsight: p.ownInsight || "",
    note: p.note || "",
    analyzed: !!p.analyzed,
    analyzedAt: p.analyzedAt || "",
    createdAt: p.createdAt || p.postDate || new Date().toISOString(),
  };
}

