/** 旧データ（自由入力の目標KPI）を goalKpiOptions のいずれかへ寄せる */
function migrateGoalKpi(raw) {
  const value = String(raw || "").trim();
  if (!value) return "";
  if (goalKpiOptions.includes(value)) return value;
  const rules = [
    [/契約|成約/, "契約"],
    [/無料相談|申込|LINE登録|問い合わせ|問合せ/, "無料相談"],
    [/クリック|遷移率|リンク/, "クリック"],
    [/プロフィール|チャンネル遷移/, "プロフィール遷移"],
    [/保存/, "保存"],
    [/返信|いいね|コメント|エンゲージ|視聴維持/, "反応"],
    [/表示|リーチ|インプレッション|閲覧/, "表示"],
  ];
  const hit = rules.find(([re]) => re.test(value));
  return hit ? hit[1] : "";
}

/** 現在時刻を datetime-local 形式（ローカルタイムゾーン）で返す */
function todayKey() {
  return nowDateTimeLocal().slice(0, 10);
}

/** 2026-07-10 → 2026/7/10。テンプレート一覧の日付表記に使う */
function slashDate(dateKey) {
  const match = String(dateKey || "").match(/^(\d{4})-(\d{2})-(\d{2})/);
  return match ? `${match[1]}/${Number(match[2])}/${Number(match[3])}` : (dateKey || "-");
}

/** 日時配列から日付入力用の最小・最大日を作る。空データなら未指定のままにする。 */
function initialDateBounds(rows, getter) {
  const dates = (rows || [])
    .map((row) => String(getter(row) || "").slice(0, 10))
    .filter((value) => /^\d{4}-\d{2}-\d{2}$/.test(value))
    .sort();
  return { from: dates[0] || "", to: dates[dates.length - 1] || "" };
}

/** ISO形式の日付が指定範囲内かを判定する。境界日は含む。 */
function dateWithin(value, from, to) {
  const key = String(value || "").slice(0, 10);
  if (!/^\d{4}-\d{2}-\d{2}$/.test(key)) return !from && !to;
  if (from && key < from) return false;
  if (to && key > to) return false;
  return true;
}

function nowDateTimeLocal() {
  const now = new Date();
  const offset = now.getTimezoneOffset() * 60000;
  return new Date(now.getTime() - offset).toISOString().slice(0, 16);
}

