    palette: `<svg ${common}><path d="M12 3a9 9 0 0 0 0 18h1.2a2 2 0 0 0 1.5-3.3 1.8 1.8 0 0 1 1.3-3h1.2A3.8 3.8 0 0 0 21 10.9 8 8 0 0 0 12 3Z"></path><circle cx="7.5" cy="11" r="1"></circle><circle cx="10" cy="7.5" r="1"></circle><circle cx="14.5" cy="7.5" r="1"></circle></svg>`,
    calendar: `<svg ${common}><rect x="3" y="5" width="18" height="16" rx="3"></rect><path d="M8 3v4"></path><path d="M16 3v4"></path><path d="M3 10h18"></path><path d="M8 15h3"></path><path d="M14 15h2"></path></svg>`,
    message: `<svg ${common}><path d="M21 12a8 8 0 0 1-8 8H6l-3 2 1.2-5A8 8 0 1 1 21 12Z"></path><path d="M8 11h8"></path><path d="M8 15h5"></path></svg>`,
    segments: `<svg ${common}><path d="M4 18v-5"></path><path d="M10 18V6"></path><path d="M16 18v-8"></path><path d="M22 18V3"></path><path d="M2 18h20"></path></svg>`,
    search: `<svg ${common}><circle cx="11" cy="11" r="7"></circle><path d="m20 20-4-4"></path><path d="M8 11h6"></path></svg>`,
