/**
 * ドーナツ用のカテゴリ配色。**順位ではなくカテゴリ名で色を決める**ので、
 * 絞り込みで件数の並びが変わっても同じカテゴリは同じ色のまま。
 * 5色はコントラスト・色覚多様性の検証済み。6つ目以降は「その他」にまとめてグレーにする。
 */
const templateChartColors = ["#0141D4", "#20c997", "#ff8a3d", "#8b5cf6", "#ef4444"];
const templateChartOtherColor = "#94a3b8";

/** 件数の多い順に5カテゴリ＋その他へ畳む。色はカテゴリ名に固定で割り当てる */
function templateBreakdown(field) {
  const counts = {};
  state.templates.forEach((template) => {
    const key = template[field] || "未設定";
    counts[key] = (counts[key] || 0) + 1;
  });
  const total = state.templates.length;
  const sorted = Object.entries(counts).sort(([, a], [, b]) => b - a);
  const top = sorted.slice(0, 5);
  const rest = sorted.slice(5);
  const colorFor = (name) => templateChartColors[top.findIndex(([key]) => key === name)] || templateChartOtherColor;
  const rows = top.map(([name, count]) => ({ name, count, color: colorFor(name) }));
  if (rest.length) {
    rows.push({ name: "その他", count: rest.reduce((sum, [, count]) => sum + count, 0), color: templateChartOtherColor });
  }
  return {
    total,
    rows: rows.map((row) => ({ ...row, pct: total ? Math.round((row.count / total) * 1000) / 10 : 0 })),
  };
}

/** 凡例つきドーナツ。数値を必ず併記するので色だけに情報を持たせていない */
function templateDonut(title, breakdown) {
  return `
    <div class="panel pad summary-card">
      <div class="section-head"><h3>${escapeHtml(title)}</h3></div>
      ${breakdown.total ? `
        <div class="tpl-donut-layout">
          <div class="tpl-donut" style="background:${conicGradient(breakdown.rows.map((row) => ({ pct: row.pct, color: row.color })))}">
            <div><small>合計</small><strong>${breakdown.total}件</strong></div>
          </div>
          <div class="tpl-donut-legend">
            ${breakdown.rows.map((row) => `
              <span><i style="background:${row.color}"></i><b>${escapeHtml(row.name)}</b><em>${row.count} (${row.pct}%)</em></span>
            `).join("")}
          </div>
        </div>
      ` : `<p class="panel-note">テンプレートがまだありません</p>`}
    </div>
  `;
}

function templateStatusTone(status) {
  if (status === "公開中") return "run";
  if (status === "下書き") return "plan";
  return "stop";
}

function designTemplatesSubView() {
  const uniqueValues = (field) => [...new Set(state.templates.map((t) => t[field]).filter(Boolean))];
  const keyword = templateSearch.trim().toLowerCase();
  const visible = state.templates
    .map((template, index) => ({ template, index }))
    .filter(({ template }) => (
      (!keyword || String(template.name || "").toLowerCase().includes(keyword))
      && (!templateChannelFilter || template.channel === templateChannelFilter)
      && (!templateFormatFilter || template.format === templateFormatFilter)
      && (!templatePurposeFilter || template.purpose === templatePurposeFilter)
      && (!templateStatusFilter || template.status === templateStatusFilter)
    ));

  const statusCount = (status) => state.templates.filter((t) => t.status === status).length;
  const ranked = state.templates
    .map((template) => ({ template, stats: templateStats(template.id) }))
    .filter((row) => row.stats.hasData)
    .sort((a, b) => b.stats.avgSaveRate - a.stats.avgSaveRate)
    .slice(0, 5);

  // 「最近使用した」は投稿側の公開日から逆引きする（テンプレート自身は使用日を持たない）
  const recentlyUsed = state.posts
    .filter((post) => post.templateId)
    .map((post) => ({ post, template: state.templates.find((t) => t.id === post.templateId) }))
    .filter((row) => row.template)
    .sort((a, b) => String(publishDateKey(b.post)).localeCompare(String(publishDateKey(a.post))))
    .slice(0, 3);

  const filterSelect = (key, value, label, options) => `
    <select class="tpl-filter" data-template-filter="${key}">
      <option value="">${escapeHtml(label)}</option>
      ${options.map((option) => `<option value="${escapeHtml(option)}" ${option === value ? "selected" : ""}>${escapeHtml(option)}</option>`).join("")}
    </select>
  `;

  return `
    <div class="tpl-toolbar">
      <span class="tpl-search">${icon("search")}<input type="search" placeholder="テンプレート名で検索" value="${escapeHtml(templateSearch)}" data-template-search></span>
      ${filterSelect("channel", templateChannelFilter, "すべてのSNS", uniqueValues("channel"))}
      ${filterSelect("format", templateFormatFilter, "すべての形式", formatOptions)}
      ${filterSelect("purpose", templatePurposeFilter, "すべての目的", uniqueValues("purpose"))}
      ${filterSelect("status", templateStatusFilter, "すべての状態", ["公開中", "下書き", "アーカイブ"])}
      <button class="btn tpl-clear" data-action="clear-template-filters">${icon("filter")}<span>絞り込み解除</span></button>
      <button class="btn primary tpl-add" data-action="add-template">テンプレートを追加</button>
    </div>

    <div class="tpl-layout">
      <div class="panel pad summary-card tpl-table-card">
        <div class="table-wrap">
          <table class="tpl-table">
            <thead>
              <tr>
                <th>テンプレ名</th><th>SNS</th><th>形式</th><th>目的</th><th>構成</th>
                <th>リンク</th><th>使用実績</th><th>平均保存率</th><th>平均CV</th><th>最終更新</th><th>状態</th><th></th>
              </tr>
            </thead>
            <tbody>
              ${visible.map(({ template, index }) => {
                const stats = templateStats(template.id);
                return `
                  <tr>
                    <td>
                      <span class="tpl-name">
                        <label class="tpl-thumb ${template.thumbnail ? "" : "empty"}" title="${template.thumbnail ? "画像を差し替え" : "画像を登録"}">
                          ${template.thumbnail ? `<img src="${escapeHtml(template.thumbnail)}" alt="">` : icon("upload")}
                          <input type="file" accept="image/png,image/jpeg,image/webp" data-template-thumb="${index}" hidden>
                        </label>
                        <strong>${escapeHtml(template.name || "(名称未設定)")}</strong>
                        ${template.recommended ? `<span class="tpl-badge">推奨</span>` : ""}
                      </span>
                    </td>
                    <td><span class="tpl-channel ${socialIcon(template.channel) ? "has-icon" : ""}">${socialIcon(template.channel)
                      ? `<img src="${socialIcon(template.channel)}" alt="${escapeHtml(template.channel)}">`
                      : escapeHtml((template.channel || "?").slice(0, 1))}</span></td>
                    <td>${escapeHtml(template.format || "-")}</td>
                    <td>${escapeHtml(template.purpose || "-")}</td>
                    <td class="channel-text-cell">${escapeHtml(template.structure || "-")}</td>
                    <td>${template.links ? `<a class="tpl-link" href="${escapeHtml(template.links)}" target="_blank" rel="noopener noreferrer">プレビュー${icon("external")}</a>` : "-"}</td>
                    <td>${stats.uses}回</td>
                    <td class="${stats.hasData ? "tpl-rate" : ""}">${stats.hasData ? `${stats.avgSaveRate}%` : "—"}</td>
                    <td>${stats.hasData ? stats.avgConversions : "—"}</td>
                    <td>${escapeHtml(slashDate(template.updatedAt))}</td>
                    <td><span class="campaign-status ${templateStatusTone(template.status)}">${escapeHtml(template.status || "-")}</span></td>
                    <td><button class="btn small" data-edit-template="${index}">${editingTemplateIndex === index ? "閉じる" : "編集"}</button></td>
                  </tr>
                  ${editingTemplateIndex === index ? `<tr class="row-edit"><td colspan="12">${templateCard(template, index)}</td></tr>` : ""}
                `;
              }).join("") || `<tr><td colspan="12">条件に合うテンプレートがありません</td></tr>`}
            </tbody>
          </table>
        </div>
        <span class="panel-note">使用実績・平均保存率・平均CVは、投稿管理で「使用テンプレート」に指定された投稿と、その分析データから自動集計されます。</span>
      </div>

      <aside class="tpl-side">
        <div class="panel pad summary-card">
          <div class="section-head"><h3>テンプレート概要</h3></div>
          <div class="tpl-total"><small>合計テンプレート数</small><strong>${state.templates.length}<span>件</span></strong></div>
          <div class="tpl-status-list">
            <span>${icon("check")}公開中<em>${statusCount("公開中")} 件</em></span>
            <span>${icon("doc")}下書き<em>${statusCount("下書き")} 件</em></span>
            <span>${icon("archive")}アーカイブ<em>${statusCount("アーカイブ")} 件</em></span>
          </div>
          <button class="btn small full-width" data-template-filter-jump="アーカイブ">アーカイブ一覧を見る</button>
        </div>

        <div class="panel pad summary-card">
          <div class="section-head"><h3>人気テンプレート TOP5</h3><span class="panel-note">保存率</span></div>
          ${ranked.length ? `
            <ol class="tpl-rank">
              ${ranked.map((row, i) => `
                <li><span class="tpl-rank-no">${i + 1}</span><b>${escapeHtml(row.template.name || "(名称未設定)")}</b><em>${row.stats.avgSaveRate}%</em></li>
              `).join("")}
            </ol>
          ` : `<p class="panel-note">分析データが登録されるとランキングが表示されます</p>`}
          <button class="btn small full-width" data-jump="analytics">すべての分析を見る</button>
        </div>
      </aside>
    </div>

    <div class="tpl-bottom">
      ${templateDonut("形式別テンプレート数", templateBreakdown("format"))}
      ${templateDonut("目的別テンプレート数", templateBreakdown("purpose"))}

      <div class="panel pad summary-card">
        <div class="section-head"><h3>最近使用したテンプレート</h3></div>
        ${recentlyUsed.length ? `
          <div class="tpl-recent">
            ${recentlyUsed.map(({ post, template }) => `
              <span>
                <i class="tpl-thumb ${template.thumbnail ? "" : "empty"}">${template.thumbnail ? `<img src="${escapeHtml(template.thumbnail)}" alt="">` : icon("palette")}</i>
                <b>${escapeHtml(template.name || "(名称未設定)")}<small>${escapeHtml(template.channel || "-")}・${escapeHtml(template.format || "-")}</small></b>
                <em>${escapeHtml(slashDate(publishDateKey(post)))}</em>
              </span>
            `).join("")}
          </div>
        ` : `<p class="panel-note">投稿にテンプレートを紐づけると、ここに履歴が出ます</p>`}
        <button class="btn small full-width" data-jump="pipeline">すべての履歴を見る</button>
      </div>

      <div class="panel pad summary-card">
        <div class="section-head"><h3>テンプレートの使い方</h3></div>
        <div class="tpl-howto">
          <span>${icon("doc")}テンプレートを選択</span>
          <span>${icon("pencil")}内容をカスタマイズ</span>
          <span>${icon("send")}投稿案に追加して活用！</span>
        </div>
        <button class="btn small full-width" data-jump="ideas">投稿案を開く</button>
      </div>
    </div>
  `;
}

/** カテゴリ名で色を固定する（順位で色を振らないので、絞り込みしても色が入れ替わらない） */
function linkCategoryColor(category, orderedNames) {
  const index = orderedNames.indexOf(category);
  return index >= 0 && index < templateChartColors.length ? templateChartColors[index] : templateChartOtherColor;
}

function designLinksSubView() {
  const allLinks = collectAllLinks();

  const categoryCounts = {};
  allLinks.forEach((row) => { categoryCounts[row.category] = (categoryCounts[row.category] || 0) + 1; });
  const categoryOrder = Object.entries(categoryCounts).sort(([, a], [, b]) => b - a).map(([name]) => name);
  const categoryRows = categoryOrder.map((name) => ({
    name,
    count: categoryCounts[name],
    pct: allLinks.length ? Math.round((categoryCounts[name] / allLinks.length) * 100) : 0,
    color: linkCategoryColor(name, categoryOrder),
  }));

  const keyword = linkSearch.trim().toLowerCase();
  const visible = allLinks.filter((row) => (
    (!keyword || `${row.label} ${row.url} ${row.note}`.toLowerCase().includes(keyword))
    && (!linkCategoryFilter || row.category === linkCategoryFilter)
    && (!linkTypeFilter || row.type === linkTypeFilter)
    && (!linkOwnerFilter || row.owner === linkOwnerFilter)
  ));

  const byDate = [...allLinks].filter((row) => row.addedAt).sort((a, b) => b.addedAt.localeCompare(a.addedAt));
  const recentlyAdded = byDate.slice(0, 3);
  // 「今週」は直近7日。日付を持つリンクだけが対象
  const weekAgo = new Date(Date.now() - 7 * 86400000).toISOString().slice(0, 10);
  const addedThisWeek = byDate.filter((row) => row.addedAt >= weekAgo).length;

  const usedInPosts = allLinks.filter((row) => row.usedIn.has("投稿")).reduce((sum, row) => sum + row.uses, 0);
  const usedInTemplates = allLinks.filter((row) => row.usedIn.has("テンプレート")).reduce((sum, row) => sum + row.uses, 0);
  const topUsed = [...allLinks].sort((a, b) => b.uses - a.uses).slice(0, 3);

  const owners = [...new Set(allLinks.map((row) => row.owner).filter(Boolean))];
  const types = [...new Set(allLinks.map((row) => row.type))];
  const filterSelect = (key, value, label, options) => `
    <select class="tpl-filter" data-link-filter="${key}">
      <option value="">${escapeHtml(label)}</option>
      ${options.map((option) => `<option value="${escapeHtml(option)}" ${option === value ? "selected" : ""}>${escapeHtml(option)}</option>`).join("")}
    </select>
  `;

  return `
    <div class="link-top">
      <div class="panel pad summary-card link-overview">
        <div>
          <div class="section-head"><h3>プロジェクト内の全リンク</h3></div>
          <div class="tpl-total"><strong>${allLinks.length}<span>件</span></strong></div>
          <p class="link-delta">今週の追加 <b>+${addedThisWeek}</b></p>
        </div>
        <div class="link-breakdown">
          <div class="section-head"><h3>カテゴリ別内訳</h3></div>
          ${allLinks.length ? `
            <div class="tpl-donut-layout">
              <div class="tpl-donut" style="background:${conicGradient(categoryRows.map((row) => ({ pct: row.pct, color: row.color })))}">
                <div><small>合計</small><strong>${allLinks.length}件</strong></div>
              </div>
              <div class="tpl-donut-legend">
                ${categoryRows.map((row) => `<span><i style="background:${row.color}"></i><b>${escapeHtml(row.name)}</b><em>${row.count} (${row.pct}%)</em></span>`).join("")}
              </div>
            </div>
          ` : `<p class="panel-note">リンクがまだありません</p>`}
        </div>
      </div>

      <div class="panel pad summary-card">
        <div class="section-head"><h3>最近追加されたリンク</h3></div>
        ${recentlyAdded.length ? `
          <div class="link-recent">
            ${recentlyAdded.map((row) => `
              <a href="${escapeHtml(row.url)}" target="_blank" rel="noopener noreferrer">
                <i>${icon("link")}</i>
                <b>${escapeHtml(row.label)}</b>
                <em>${escapeHtml(slashDate(row.addedAt))}</em>
              </a>
            `).join("")}
          </div>
        ` : `<p class="panel-note">日付が入ったリンクがまだありません</p>`}
      </div>

      <div class="panel pad summary-card">
        <div class="section-head"><h3>リンクの利用状況</h3></div>
        <div class="link-usage">
          <span><i>${icon("send")}</i><small>投稿での使用</small><strong>${usedInPosts}<em>回</em></strong></span>
          <span><i>${icon("palette")}</i><small>テンプレートでの使用</small><strong>${usedInTemplates}<em>回</em></strong></span>
        </div>
        <button class="btn small full-width" data-jump="pipeline">投稿管理を開く</button>
      </div>
    </div>

    <div class="tpl-toolbar">
      <span class="tpl-search">${icon("search")}<input type="search" placeholder="リンク名・URL・説明で検索" value="${escapeHtml(linkSearch)}" data-link-search></span>
      ${filterSelect("category", linkCategoryFilter, "すべてのカテゴリ", categoryOrder)}
      ${filterSelect("type", linkTypeFilter, "すべてのタイプ", types)}
      ${filterSelect("owner", linkOwnerFilter, "追加者すべて", owners)}
      <button class="btn tpl-clear" data-action="clear-link-filters">${icon("filter")}<span>絞り込み解除</span></button>
      <button class="btn primary tpl-add" data-action="add-shared-link">共有リンクを追加</button>
    </div>

    <div class="tpl-layout">
      <div class="panel pad summary-card tpl-table-card">
        <div class="table-wrap">
          <table class="tpl-table link-table">
            <thead>
              <tr><th>リンク名</th><th>カテゴリ</th><th>タイプ</th><th>URL</th><th>説明</th><th>追加者</th><th>追加日</th><th>最終更新日</th><th>使用状況</th><th>状態</th></tr>
            </thead>
            <tbody>
              ${visible.map((row) => `
                <tr>
                  <td>
                    <span class="tpl-name">
                      <span class="link-icon" style="color:${linkCategoryColor(row.category, categoryOrder)}">${icon("link")}</span>
                      <span class="link-name-text"><strong>${escapeHtml(row.label)}</strong><small>${escapeHtml(row.source)}</small></span>
                    </span>
                  </td>
                  <td><span class="link-cat" style="--cat:${linkCategoryColor(row.category, categoryOrder)}">${escapeHtml(row.category)}</span></td>
                  <td>${escapeHtml(row.type)}</td>
                  <td class="link-url" title="${escapeHtml(row.url)}">${escapeHtml(shortUrl(row.url))}</td>
                  <td><span class="link-clamp">${escapeHtml(row.note || "-")}</span></td>
                  <td>${escapeHtml(row.owner || "-")}</td>
                  <td>${escapeHtml(slashDate(row.addedAt))}</td>
                  <td>${escapeHtml(slashDate(row.updatedAt))}</td>
                  <td>${row.uses}回</td>
                  <td>
                    <span class="link-actions">
                      <a class="brand-example-btn" href="${escapeHtml(row.url)}" target="_blank" rel="noopener noreferrer" title="開く">${icon("external")}</a>
                      <button class="brand-example-btn" data-copy-link="${escapeHtml(row.url)}" title="URLをコピー">${icon("copy")}</button>
                    </span>
                  </td>
                </tr>
              `).join("") || `<tr><td colspan="10">条件に合うリンクがありません</td></tr>`}
            </tbody>
          </table>
        </div>
        <span class="panel-note">※ リンクの編集・削除は元の場所（共有リンク集／テンプレート／投稿管理）で行います。同じURLは1行にまとめ、使用状況にその登場回数を表示しています。</span>
      </div>

      <aside class="tpl-side">
        <div class="panel pad summary-card">
          <div class="section-head"><h3>カテゴリ一覧</h3></div>
          <div class="link-cat-list">
            ${categoryRows.map((row) => `
              <button data-link-filter-jump="${escapeHtml(row.name)}">
                <i style="color:${row.color}">${icon("folder")}</i>${escapeHtml(row.name)}<em>${row.count}</em>
              </button>
            `).join("") || `<p class="panel-note">カテゴリがまだありません</p>`}
          </div>
        </div>

        <div class="panel pad summary-card">
          <div class="section-head"><h3>リンクの使い方</h3></div>
          <div class="tpl-howto">
            <span>${icon("check")}共有リンク集に登録するとチーム全員が使えます</span>
            <span>${icon("check")}投稿・テンプレートに貼ったURLも自動でここに集まります</span>
            <span>${icon("check")}使用状況が0回のリンクは定期的に見直しましょう</span>
          </div>
        </div>

        <div class="panel pad summary-card">
          <div class="section-head"><h3>よく使われているリンク</h3></div>
          ${topUsed.length ? `
            <ol class="tpl-rank">
              ${topUsed.map((row, i) => `<li><span class="tpl-rank-no">${i + 1}</span><b>${escapeHtml(row.label)}</b><em>${row.uses}回</em></li>`).join("")}
            </ol>
          ` : `<p class="panel-note">リンクがまだありません</p>`}
        </div>
      </aside>
    </div>

    <div class="panel pad summary-card link-source-card">
      <div class="section-head"><div><h3>共有リンク集（編集はこちら）</h3><span class="pill">${state.sharedLinks.length}件</span></div><button class="btn" data-action="add-shared-link">追加</button></div>
      <p class="panel-note">素材フォルダ、テンプレ資料、参照用の戦略資料など、特定の投稿に紐づかない「共有の置き場所」を登録します。</p>
      <div class="shared-link-grid">
        ${state.sharedLinks.map((row, index) => sharedLinkCard(row, index)).join("") || `<p class="panel-note">共有リンクがまだありません</p>`}
      </div>
    </div>
  `;
}

function designHashtagsSubView() {
  const all = hashtagTagStats();
  const health = hashtagHealthScore(all);
  const withData = all.filter((row) => row.hasData);

  const avgOf = (field) => (withData.length
    ? Math.round((withData.reduce((sum, row) => sum + row[field], 0) / withData.length) * 100) / 100
    : 0);
  const totalPosts = state.posts.filter((post) => post.hashtagSetId).length;
  const totalConversions = withData.reduce((sum, row) => sum + row.conversions, 0);

  const keyword = hashtagSearch.trim().toLowerCase();
  const visible = all.filter((row) => (
    (!keyword || row.tag.toLowerCase().includes(keyword))
    && (!hashtagCategoryFilter || row.category === hashtagCategoryFilter)
    && (!hashtagChannelFilter || row.channels.includes(hashtagChannelFilter))
    && (!hashtagStatusFilter || row.tier.key === hashtagStatusFilter)
  ));

  const categories = [...new Set(all.map((row) => row.category))];
  const channels = [...new Set(all.flatMap((row) => row.channels))];
  const filterSelect = (key, value, label, options) => `
    <select class="tpl-filter" data-hashtag-filter="${key}">
      <option value="">${escapeHtml(label)}</option>
      ${options.map((option) => `<option value="${escapeHtml(option)}" ${option === value ? "selected" : ""}>${escapeHtml(option)}</option>`).join("")}
    </select>
  `;

  // カテゴリ別の平均保存率（横棒）
  const byCategory = {};
  withData.forEach((row) => {
    if (!byCategory[row.category]) byCategory[row.category] = [];
    byCategory[row.category].push(row.saveRate);
  });
  const categoryRows = Object.entries(byCategory)
    .map(([name, values]) => ({ name, value: Math.round((values.reduce((a, b) => a + b, 0) / values.length) * 100) / 100 }))
    .sort((a, b) => b.value - a.value);
  const categoryMax = Math.max(...categoryRows.map((row) => row.value), 1);

  // 保存率の推移：上位3タグを、投稿の公開日を横軸にして重ねる
  const trendTags = withData.filter((row) => row.trend.length >= 2).slice(0, 3);
  const trendLabels = trendTags.length
    ? state.posts
        .filter((post) => post.hashtagSetId && publishDateKey(post) !== "未設定")
        .map((post) => publishDateKey(post))
        .sort()
        .filter((value, i, arr) => arr.indexOf(value) === i)
        .map((key) => slashDate(key).replace(/^\d{4}\//, ""))
    : [];
  const trendSeriesRows = trendTags.map((row, i) => ({
    name: row.tag,
    color: templateChartColors[i],
    values: row.trend,
  }));

  const tierCounts = hashtagTiers.map((tier) => ({
    ...tier,
    count: withData.filter((row) => row.tier.key === tier.key).length,
  }));

  const newest = [...all]
    .filter((row) => row.lastUpdated)
    .sort((a, b) => b.lastUpdated.localeCompare(a.lastUpdated))
    .slice(0, 3);

  const statTile = (iconName, tone, label, value, unit) => `
    <span class="ht-stat">
      <i class="${tone}">${icon(iconName)}</i>
      <small>${escapeHtml(label)}</small>
      <strong>${value}<em>${escapeHtml(unit)}</em></strong>
    </span>
  `;

  return `
    <div class="ht-top">
      <div class="panel pad summary-card">
        <div class="section-head"><h3>ハッシュタグ総合サマリー</h3></div>
        <div class="ht-stat-row">
          ${statTile("hash", "blue", "登録ハッシュタグ総数", all.length, "個")}
          ${statTile("send", "violet", "ハッシュタグ付き投稿", totalPosts, "件")}
          ${statTile("bookmark", "green", "平均保存率", avgOf("saveRate"), "%")}
          ${statTile("target", "orange", "CV合計", totalConversions, "件")}
        </div>
      </div>

      <div class="panel pad summary-card">
        <div class="section-head"><h3>効果指標の平均</h3></div>
        <div class="ht-avg-row">
          <span><small>平均エンゲージメント率</small><strong>${avgOf("engagementRate")}<em>%</em></strong></span>
          <span><small>平均クリック率</small><strong>${avgOf("clickRate")}<em>%</em></strong></span>
          <span><small>平均CVR</small><strong>${avgOf("cvr")}<em>%</em></strong></span>
        </div>
      </div>

      <div class="panel pad summary-card">
        <div class="section-head"><h3>ハッシュタグ健康スコア</h3></div>
        ${health.scored ? `
          <div class="ht-health">
            <div class="ht-gauge" style="--pct:${health.score}">
              <div><strong>${health.score}</strong><small>/100</small></div>
            </div>
            <div class="ht-health-legend">
              ${hashtagTiers.map((tier) => {
                const count = health.counts[tier.key] || 0;
                const pct = health.scored ? Math.round((count / health.scored) * 100) : 0;
                return `<span><i class="tier-${tier.tone}"></i>${escapeHtml(tier.key)}<b>${pct}%</b><em>（${count}件）</em></span>`;
              }).join("")}
            </div>
          </div>
          <p class="ht-health-label">総合評価：<b>${escapeHtml(health.label)}</b>（分析データのある${health.scored}タグで算出）</p>
        ` : `<p class="panel-note">分析データが入るとスコアが表示されます</p>`}
      </div>
    </div>

    <div class="tpl-toolbar">
      <span class="tpl-search">${icon("search")}<input type="search" placeholder="ハッシュタグを検索" value="${escapeHtml(hashtagSearch)}" data-hashtag-search></span>
      ${filterSelect("category", hashtagCategoryFilter, "すべてのカテゴリ", categories)}
      ${filterSelect("channel", hashtagChannelFilter, "すべてのSNS", channels)}
      ${filterSelect("status", hashtagStatusFilter, "ステータス", hashtagTiers.map((tier) => tier.key))}
      <button class="btn tpl-clear" data-action="clear-hashtag-filters">${icon("filter")}<span>絞り込み解除</span></button>
      <button class="btn primary tpl-add" data-action="add-hashtag-set">ハッシュタグセットを追加</button>
    </div>

    <div class="tpl-layout">
      <div class="panel pad summary-card tpl-table-card">
        <div class="section-head"><div><h3>ハッシュタグ一覧</h3><span class="pill">${visible.length} / ${all.length}件</span></div></div>
        <div class="table-wrap">
          <table class="tpl-table ht-table">
            <thead>
              <tr>
                <th>ハッシュタグ</th><th>カテゴリ</th><th>主なSNS</th><th>投稿</th><th>保存率</th>
                <th>エンゲージ率</th><th>クリック率</th><th>CV</th><th>CVR</th>
                <th>トレンド</th><th>ステータス</th><th>最終更新</th><th>所属セット</th>
              </tr>
            </thead>
            <tbody>
              ${visible.map((row) => `
                <tr>
                  <td><strong class="ht-tag">${escapeHtml(row.tag)}</strong></td>
                  <td><span class="link-cat" style="--cat:${linkCategoryColor(row.category, categories)}">${escapeHtml(row.category)}</span></td>
                  <td>
                    <span class="ht-channels">
                      ${row.channels.slice(0, 3).map((channel) => (socialIcon(channel)
                        ? `<i title="${escapeHtml(channel)}"><img src="${socialIcon(channel)}" alt="${escapeHtml(channel)}"></i>`
                        : `<i title="${escapeHtml(channel)}">${escapeHtml((channel || "?").slice(0, 1))}</i>`)).join("")}
                    </span>
                  </td>
                  <td>${row.posts}</td>
                  <td class="${row.hasData ? "tpl-rate" : ""}">${row.hasData ? `${row.saveRate}%` : "—"}</td>
                  <td>${row.hasData ? `${row.engagementRate}%` : "—"}</td>
                  <td>${row.hasData ? `${row.clickRate}%` : "—"}</td>
                  <td>${row.hasData ? row.conversions : "—"}</td>
                  <td>${row.hasData ? `${row.cvr}%` : "—"}</td>
                  <td>${row.trend.length >= 2 ? sparkline(row.trend, tierColor(row.tier.tone)) : `<span class="ht-muted">—</span>`}</td>
                  <td><span class="ht-status tier-${row.tier.tone}">${escapeHtml(row.tier.key)}</span></td>
                  <td>${escapeHtml(slashDate(row.lastUpdated))}</td>
                  <td>
                    <button class="btn small" data-edit-tag-set="${row.setIndexes[0]}" title="このタグが入っているセット「${escapeHtml(row.setNames[0] || "")}」を編集">
                      ${escapeHtml(row.setNames[0] || "-")}${row.setNames.length > 1 ? ` +${row.setNames.length - 1}` : ""}
                    </button>
                  </td>
                </tr>
              `).join("") || `<tr><td colspan="13">条件に合うハッシュタグがありません</td></tr>`}
            </tbody>
          </table>
        </div>
        <span class="panel-note">投稿数・各指標・ステータスは、ハッシュタグセットを使った投稿とその分析データから自動集計されるため、この表は直接編集できません。<strong>タグ名の変更・追加・削除は「所属セット」のボタンから</strong>行ってください。</span>
      </div>

      <aside class="tpl-side">
        <div class="panel pad summary-card">
          <div class="section-head"><h3>人気ハッシュタグ TOP5</h3><span class="panel-note">保存率</span></div>
          ${withData.length ? `
            <ol class="tpl-rank">
              ${withData.slice(0, 5).map((row, i) => `<li><span class="tpl-rank-no">${i + 1}</span><b>${escapeHtml(row.tag)}</b><em>${row.saveRate}%</em></li>`).join("")}
            </ol>
          ` : `<p class="panel-note">分析データが入るとランキングが出ます</p>`}
        </div>

        <div class="panel pad summary-card">
          <div class="section-head"><h3>カテゴリ別パフォーマンス</h3><span class="panel-note">保存率</span></div>
          ${categoryRows.length ? `
            <div class="ht-catbars">
              ${categoryRows.map((row) => `
                <span>
                  <small>${escapeHtml(row.name)}</small>
                  <i><b style="width:${Math.round((row.value / categoryMax) * 100)}%"></b></i>
                  <em>${row.value}%</em>
                </span>
              `).join("")}
            </div>
          ` : `<p class="panel-note">分析データが入ると表示されます</p>`}
        </div>

        <div class="panel pad summary-card">
          <div class="section-head"><h3>ハッシュタグの使い方</h3></div>
          <div class="tpl-howto">
            <span>${icon("check")}効果の高いハッシュタグを見つけて活用しましょう</span>
            <span>${icon("check")}定期的に見直し、非推奨タグを整理しましょう</span>
            <span>${icon("check")}カテゴリやSNSに合わせて使い分けましょう</span>
          </div>
        </div>
      </aside>
    </div>

    <div class="ht-bottom">
      <div class="panel pad summary-card">
        <div class="section-head"><h3>保存率の推移（上位ハッシュタグ）</h3></div>
        ${trendSeriesRows.length ? multiLineChart(trendSeriesRows, trendLabels) : `<p class="panel-note">同じハッシュタグを使った投稿が2件以上になると推移が表示されます</p>`}
      </div>

      <div class="panel pad summary-card">
        <div class="section-head"><h3>ハッシュタグの推奨アクション</h3></div>
        <div class="ht-tiers">
          ${tierCounts.map((tier) => `
            <button data-hashtag-filter-jump="${escapeHtml(tier.key)}">
              <i class="tier-${tier.tone}">${icon(tier.tone === "bad" ? "ban" : "check")}</i>
              <b>${escapeHtml(tier.key)}<small>${escapeHtml(tier.desc)}</small><small>${escapeHtml(tier.note)}</small></b>
              <em>${tier.count}件</em>
            </button>
          `).join("")}
        </div>
      </div>

      <div class="panel pad summary-card">
        <div class="section-head"><h3>新着・注目ハッシュタグ</h3></div>
        ${newest.length ? `
          <div class="ht-new">
            ${newest.map((row) => `
              <span>
                <i>NEW</i>
                <b>${escapeHtml(row.tag)}<small>投稿数：${row.posts}${row.hasData ? ` ／ 保存率：${row.saveRate}%` : ""}</small></b>
                <em>${escapeHtml(slashDate(row.lastUpdated))}</em>
              </span>
            `).join("")}
          </div>
        ` : `<p class="panel-note">投稿にハッシュタグセットを紐づけると表示されます</p>`}
      </div>
    </div>

    <div class="panel pad summary-card link-source-card">
      <div class="section-head"><div><h3>ハッシュタグセット（編集はこちら）</h3><span class="pill">${state.hashtagSets.length}件</span></div><button class="btn" data-action="add-hashtag-set">セットを追加</button></div>
      <p class="panel-note">タグはセット単位で管理します。投稿には「ハッシュタグセット」を選んで紐づけるため、ここでタグを足すと上の一覧にも自動で反映されます。</p>
      <div class="shared-link-grid">
        ${state.hashtagSets.map((set, index) => hashtagSetCard(set, index)).join("") || `<p class="panel-note">ハッシュタグセットがまだありません</p>`}
      </div>
    </div>
  `;
}

/** ステータスの色。スパークラインなど、ピル以外でも同じ色を使うため関数にしている */
function tierColor(tone) {
  return { good: "#0e8f64", ok: "#0141D4", warn: "#d97706", bad: "#dc2626", none: "#94a3b8" }[tone] || "#94a3b8";
}

function designRulesSubView() {
  const rules = state.platformRules;
  const accountFor = (channel) => state.accounts.find((account) => account.channel === channel);
  const configured = rules.filter((rule) => rule.status !== "下書き").length;
  const missing = activeChannelNames().filter((name) => !rules.some((rule) => rule.channel === name));
  const monthKey = todayKey().slice(0, 7);
  const updatedThisMonth = rules.filter((rule) => String(rule.updatedAt || "").startsWith(monthKey)).length;
  const liveAccounts = state.accounts.filter((account) => account.status === "運用中").length;

  const history = [...rules]
    .filter((rule) => rule.updatedAt)
    .sort((a, b) => b.updatedAt.localeCompare(a.updatedAt))
    .slice(0, 4);

  const statTile = (iconName, tone, label, value, unit, sub) => `
    <span class="ht-stat">
      <i class="${tone}">${icon(iconName)}</i>
      <small>${escapeHtml(label)}</small>
      <strong>${value}<em>${escapeHtml(unit)}</em></strong>
      <b class="rule-stat-sub">${escapeHtml(sub)}</b>
    </span>
  `;

  const bullets = (items) => (items || []).length
    ? `<ul class="rule-bullets">${items.map((item) => `<li>${escapeHtml(item)}</li>`).join("")}</ul>`
    : `<span class="ht-muted">-</span>`;

  return `
    <div class="tpl-layout rule-layout">
      <div class="panel pad summary-card tpl-table-card">
        <div class="section-head">
          <div><h3>SNS別ルール一覧</h3><span class="pill">${rules.length}件</span></div>
          <button class="btn primary" data-action="add-platform-rule">SNSルールを追加</button>
        </div>

        <div class="rule-stats">
          ${statTile("dashboard", "violet", "ルール設定済みのSNS", configured, ` / ${channelNames.length}`, missing.length ? `未設定：${missing.join("・")}` : "全チャネル設定済み")}
          ${statTile("users", "blue", "運用中アカウント", liveAccounts, "件", `SNSアカウントタブと連動`)}
          ${statTile("pencil", "green", "今月更新したルール", updatedThisMonth, "件", `${monthKey.replace("-", "/")} 時点`)}
          ${statTile("bell", "orange", "下書きのルール", rules.filter((rule) => rule.status === "下書き").length, "件", "公開前の確認待ち")}
        </div>

        <div class="table-wrap">
          <table class="tpl-table rule-table">
            <thead>
              <tr><th>SNS名</th><th>文字数目安</th><th>推奨頻度</th><th>推奨形式</th><th>画像ルール</th><th>編集ルール</th><th>追加機能・活用</th><th>主要KPI</th><th>状態</th><th></th></tr>
            </thead>
            <tbody>
              ${rules.map((rule, index) => {
                const account = accountFor(rule.channel);
                return `
                  <tr>
                    <td>
                      <span class="rule-channel">
                        <span class="platform-avatar ${socialIcon(rule.channel) ? "has-icon" : ""}">${socialIcon(rule.channel) ? `<img src="${socialIcon(rule.channel)}" alt="${escapeHtml(rule.channel)}">` : escapeHtml((rule.channel || "?").slice(0, 1))}</span>
                        <span><strong>${escapeHtml(rule.channel)}</strong><small>${escapeHtml(account ? account.handle : "アカウント未登録")}</small></span>
                      </span>
                    </td>
                    <td class="rule-pre">${escapeHtml(rule.charLimit || "-")}</td>
                    <td>
                      <span class="rule-freq">${escapeHtml(rule.frequency || "-")}</span>
                      ${rule.bestTime ? `<span class="rule-best">ベスト：${escapeHtml(rule.bestTime)}</span>` : ""}
                    </td>
                    <td>${bullets(rule.formats)}</td>
                    <td>${bullets(rule.imageRules)}</td>
                    <td>${bullets(rule.editRules)}</td>
                    <td>${bullets(rule.features)}</td>
                    <td>
                      <span class="rule-kpis">${(rule.kpis || []).map((kpi) => `<span>${escapeHtml(kpi)}</span>`).join("") || "-"}</span>
                    </td>
                    <td>
                      <span class="campaign-status ${rule.status === "有効" ? "run" : rule.status === "下書き" ? "plan" : "stop"}">${escapeHtml(rule.status || "-")}</span>
                      <span class="rule-updated">最終更新<br>${escapeHtml(slashDate(rule.updatedAt))}</span>
                    </td>
                    <td><button class="btn small" data-edit-platform-rule="${index}">${editingPlatformRuleIndex === index ? "閉じる" : "編集"}</button></td>
                  </tr>
                  ${editingPlatformRuleIndex === index ? `<tr class="row-edit"><td colspan="10">${platformRuleCard(rule, index)}</td></tr>` : ""}
                `;
              }).join("") || `<tr><td colspan="10">SNS別ルールがまだありません</td></tr>`}
            </tbody>
          </table>
        </div>
        <span class="panel-note">※ 各SNSの仕様や推奨事項は変動します。数値は2026年7月時点の各プラットフォーム公表値・公開情報にもとづく目安です。最新情報は公式ヘルプをご確認ください。<br>アカウント名は「SNSアカウント」タブの登録内容を表示しています。</span>
      </div>

      <aside class="tpl-side rule-side">
        <div class="panel pad summary-card rule-card">
          <div class="rule-card-head"><span class="rule-card-icon blue">${icon("link")}</span><h3>クイックリンク</h3></div>
          <div class="rule-quick">
            <button data-design-tab-jump="brand"><i class="blue">${icon("palette")}</i><b>推奨画像サイズ・トーン&マナー<small>ブランドガイド</small></b>${icon("chevron")}</button>
            <button data-design-tab-jump="brand"><i class="red">${icon("ban")}</i><b>NG例ギャラリー<small>Do / Don't</small></b>${icon("chevron")}</button>
            <button data-design-tab-jump="templates"><i class="violet">${icon("doc")}</i><b>編集テンプレート集<small>テンプレート</small></b>${icon("chevron")}</button>
            <button data-design-tab-jump="hashtags"><i class="green">${icon("hash")}</i><b>ハッシュタグ運用ルール<small>ハッシュタグ</small></b>${icon("chevron")}</button>
            <button data-jump="accounts"><i class="orange">${icon("users")}</i><b>SNSアカウント一覧<small>アカウント管理</small></b>${icon("chevron")}</button>
          </div>
          ${(state.brand.ngWords || []).length ? `
            <div class="rule-ng">
              <strong>${icon("ban")}表現禁止ワード<em>${(state.brand.ngWords || []).length}件</em></strong>
              <span>${(state.brand.ngWords || []).map((word) => `<i>${escapeHtml(word)}</i>`).join("")}</span>
            </div>
          ` : ""}
        </div>

        <div class="panel pad summary-card rule-card">
          <div class="rule-card-head"><span class="rule-card-icon green">${icon("spark")}</span><h3>ルール適用のヒント</h3></div>
          <ol class="rule-tips">
            <li><b>各SNSの特性を理解して使い分ける<small>同じ内容の使い回しは伸びにくくなります</small></b></li>
            <li><b>ベストな投稿時間に合わせて予約する<small>各行の「ベスト」バッジが目安です</small></b></li>
            <li><b>データをもとに定期的に見直す<small>四半期に一度の棚卸しを推奨します</small></b></li>
          </ol>
        </div>

        <div class="panel pad summary-card rule-card">
          <div class="rule-card-head"><span class="rule-card-icon violet">${icon("calendar")}</span><h3>最近の更新履歴</h3></div>
          ${history.length ? `
            <ol class="rule-history">
              ${history.map((rule) => `
                <li>
                  <i></i>
                  <b>${escapeHtml(rule.channel)}のルールを更新<small>${escapeHtml(rule.updatedBy || "担当者未設定")}・${escapeHtml(slashDate(rule.updatedAt))}</small></b>
                </li>
              `).join("")}
            </ol>
          ` : `<p class="panel-note">更新履歴がまだありません</p>`}
        </div>

        <div class="panel pad summary-card rule-card rule-caution">
          <div class="rule-card-head"><span class="rule-card-icon amber">${icon("bell")}</span><h3>注意事項</h3></div>
          <p>各プラットフォームの仕様やアルゴリズムは<b>予告なく変更されます</b>。四半期に一度は内容を確認・更新してください。</p>
          <span class="rule-asof">数値は 2026年7月 時点の公開情報にもとづく目安です</span>
        </div>
      </aside>
    </div>
  `;
}

/**
 * 共有リンクの1枚。通常は読みやすいカード表示で、「編集」を押した1枚だけフォームが開く。
 * 常時フォームだと9件並んだときに縦に長大になり、何がどこにあるか分からなくなるため。
 */
function sharedLinkCard(row, index) {
  if (editingSharedLinkIndex === index) {
    return `
      <article class="shared-link-card editing">
        <div class="fields">
          <label>名称 ${input(`sharedLinks.${index}.name`, row.name)}</label>
          <div class="fields two">
            <label>種類 ${input(`sharedLinks.${index}.type`, row.type)}</label>
            <label>担当 ${input(`sharedLinks.${index}.owner`, row.owner)}</label>
          </div>
          <label>URL ${input(`sharedLinks.${index}.url`, row.url, "url")}</label>
          <label>メモ ${textarea(`sharedLinks.${index}.note`, row.note, 2)}</label>
        </div>
        <div class="shared-link-foot">
          <button class="btn primary" data-edit-shared-link="${index}">編集を完了</button>
          <button class="btn danger" data-remove-shared-link="${index}">削除</button>
        </div>
      </article>
    `;
  }
  const type = row.type || "その他";
  return `
    <article class="shared-link-card ${row.url ? "" : "is-empty"}">
      <div class="shared-link-head">
        <span class="shared-link-icon">${icon(row.url ? "link" : "folder")}</span>
        <span class="shared-link-title">
          <strong>${escapeHtml(row.name || "(名称未設定)")}</strong>
          <small>${escapeHtml(type)}${row.owner ? ` ・ ${escapeHtml(row.owner)}` : ""}</small>
        </span>
        <button class="btn small" data-edit-shared-link="${index}">編集</button>
      </div>
      ${row.note ? `<p class="shared-link-note">${escapeHtml(row.note)}</p>` : ""}
      <div class="shared-link-foot">
        ${row.url
          ? `<a class="shared-link-url" href="${escapeHtml(row.url)}" target="_blank" rel="noopener noreferrer" title="${escapeHtml(row.url)}">${icon("external")}${escapeHtml(shortUrl(row.url))}</a>
             <button class="brand-example-btn" data-copy-link="${escapeHtml(row.url)}" title="URLをコピー">${icon("copy")}</button>`
          : `<span class="shared-link-url is-empty">${icon("link")}URL未設定 — 「編集」から登録できます</span>`}
      </div>
    </article>
  `;
}

/** ハッシュタグセットの1枚。共有リンク集と同じで、通常はカード表示、「編集」を押した1枚だけフォームになる */
function hashtagSetCard(set, index) {
  const stats = hashtagStats(set.id);
  if (editingHashtagIndex === index) {
    return `
      <article class="shared-link-card editing ht-set-card">
        <div class="fields two">
          <label>セット名 ${input(`hashtagSets.${index}.name`, set.name)}</label>
          <label>SNS ${select(`hashtagSets.${index}.channel`, set.channel, activeChannelNames())}</label>
          <label>カテゴリ ${input(`hashtagSets.${index}.category`, set.category)}</label>
          <label>用途 ${input(`hashtagSets.${index}.usage`, set.usage)}</label>
          <label class="field-wide">タグ ${listTextarea(`hashtagSets.${index}.tags`, set.tags, 3)}<span class="panel-note">「、」または改行区切り。ここで足したタグが上の一覧に出ます</span></label>
          <label class="field-wide">メモ ${textarea(`hashtagSets.${index}.performance`, set.performance, 2)}</label>
        </div>
        <div class="shared-link-foot">
          <button class="btn primary" data-edit-hashtag="${index}">編集を完了</button>
          <button class="btn danger" data-remove-hashtag-set="${index}">削除</button>
        </div>
      </article>
    `;
  }
  const tags = set.tags || [];
  return `
    <article class="shared-link-card ht-set-card ${tags.length ? "" : "is-empty"}">
      <div class="shared-link-head">
        <span class="shared-link-icon">${socialIcon(set.channel) ? `<img src="${socialIcon(set.channel)}" alt="${escapeHtml(set.channel)}">` : icon("hash")}</span>
        <span class="shared-link-title">
          <strong>${escapeHtml(set.name || "(名称未設定)")}</strong>
          <small>${escapeHtml(set.channel || "SNS未設定")}${set.category ? ` ・ ${escapeHtml(set.category)}` : ""}</small>
        </span>
        <button class="btn small" data-edit-hashtag="${index}">編集</button>
      </div>
      ${set.usage ? `<p class="shared-link-note">${escapeHtml(set.usage)}</p>` : ""}
      <div class="ht-set-tags">
        ${tags.length
          ? tags.slice(0, 8).map((tag) => `<span>${escapeHtml(tag)}</span>`).join("") + (tags.length > 8 ? `<span class="more">＋${tags.length - 8}</span>` : "")
          : `<span class="more">タグ未設定 — 「編集」から追加できます</span>`}
      </div>
      <div class="ht-set-stats">
        <span><small>タグ数</small><strong>${tags.length}</strong></span>
        <span><small>投稿数</small><strong>${stats.posts}</strong></span>
        <span><small>平均保存率</small><strong>${stats.avgSaveRate}%</strong></span>
        <span><small>CV合計</small><strong>${stats.conversions}</strong></span>
      </div>
    </article>
  `;
}

function platformRuleCard(rule, index) {
  return `
    <article class="list-item editable-card">
      <div class="fields two">
        <label>SNS ${select(`platformRules.${index}.channel`, rule.channel, activeChannelNames())}</label>
        <label>状態 ${select(`platformRules.${index}.status`, rule.status, ["有効", "下書き", "停止"])}</label>
        <label>推奨頻度 ${input(`platformRules.${index}.frequency`, rule.frequency)}</label>
        <label>ベストな投稿時間 ${input(`platformRules.${index}.bestTime`, rule.bestTime)}</label>
        <label class="field-wide">文字数目安 ${textarea(`platformRules.${index}.charLimit`, rule.charLimit, 2)}<span class="panel-note">改行で複数行に分けられます</span></label>
        <label class="field-wide">推奨形式 ${listTextarea(`platformRules.${index}.formats`, rule.formats, 2)}<span class="panel-note">「、」または改行区切り</span></label>
        <label class="field-wide">画像ルール ${listTextarea(`platformRules.${index}.imageRules`, rule.imageRules, 3)}</label>
        <label class="field-wide">編集ルール ${listTextarea(`platformRules.${index}.editRules`, rule.editRules, 3)}</label>
        <label class="field-wide">追加機能・活用 ${listTextarea(`platformRules.${index}.features`, rule.features, 2)}</label>
        <label class="field-wide">主要KPI ${listTextarea(`platformRules.${index}.kpis`, rule.kpis, 2)}</label>
        <div class="fields two">
          <label>最終更新日 ${input(`platformRules.${index}.updatedAt`, rule.updatedAt || "", "date")}</label>
          <label>更新者 ${input(`platformRules.${index}.updatedBy`, rule.updatedBy || "")}</label>
        </div>
      </div>
      <div class="shared-link-foot">
        <button class="btn primary" data-edit-platform-rule="${index}">編集を完了</button>
        <button class="btn danger" data-remove-platform-rule="${index}">削除</button>
      </div>
    </article>
  `;
}

function templateCard(template, index) {
  return `
    <article class="list-item editable-card">
      <div class="fields two">
        <label>テンプレ名 ${input(`templates.${index}.name`, template.name)}</label>
        <label>SNS ${select(`templates.${index}.channel`, template.channel, activeChannelNames())}</label>
        <label>形式 ${select(`templates.${index}.format`, template.format || "", formatOptions)}</label>
        <label>目的 ${input(`templates.${index}.purpose`, template.purpose)}</label>
        <label>構成 ${textarea(`templates.${index}.structure`, template.structure, 2)}</label>
        <label>共有リンク ${textarea(`templates.${index}.links`, template.links || "", 2)}${linkPreview(template.links)}</label>
        <label>状態 ${select(`templates.${index}.status`, template.status, ["公開中", "下書き", "アーカイブ"])}</label>
        <label>最終更新 ${input(`templates.${index}.updatedAt`, template.updatedAt || "", "date")}</label>
        <label class="tpl-check"><input type="checkbox" data-template-recommended="${index}" ${template.recommended ? "checked" : ""}> 推奨テンプレートとして表示する</label>
      </div>
      <div class="tpl-thumb-field">
        <span class="tpl-thumb lg ${template.thumbnail ? "" : "empty"}">${template.thumbnail ? `<img src="${escapeHtml(template.thumbnail)}" alt="">` : icon("palette")}</span>
        <label class="btn small">サムネイルを選択<input type="file" accept="image/png,image/jpeg,image/webp" data-template-thumb="${index}" hidden></label>
        ${template.thumbnail ? `<button class="btn small" data-clear-template-thumb="${index}">画像を削除</button>` : ""}
      </div>
      <button class="btn danger" data-remove-template="${index}">削除</button>
    </article>
  `;
}

function campaignStats(campaignId) {
  const posts = state.posts.filter((post) => post.campaignId === campaignId);
  const postIds = new Set(posts.map((post) => post.id));
  const metrics = state.metrics.filter((row) => row.postId && postIds.has(row.postId));
  return {
    posts: posts.length,
    published: posts.filter(postIsPublished).length,
    pendingApproval: posts.filter((post) => postWorkflowStage(post) === "確認").length,
    clicks: metrics.reduce((sum, row) => sum + numberValue(row.clicks), 0),
    conversions: metrics.reduce((sum, row) => sum + numberValue(row.conversions), 0),
  };
}

function hashtagStats(hashtagSetId) {
  const posts = state.posts.filter((post) => post.hashtagSetId === hashtagSetId);
  const postIds = new Set(posts.map((post) => post.id));
  const metrics = state.metrics.filter((row) => row.postId && postIds.has(row.postId));
  const saveRateSum = metrics.reduce((sum, row) => sum + numberValue(row.saveRate), 0);
  return {
    posts: posts.length,
    avgSaveRate: metrics.length ? Math.round((saveRateSum / metrics.length) * 10) / 10 : 0,
    conversions: metrics.reduce((sum, row) => sum + numberValue(row.conversions), 0),
  };
}

/**
 * テンプレートの実績。ハッシュタグセットと同じ考え方で、
 * 「このテンプレートを使った投稿」→「その投稿の分析データ」の順に辿って集計する。
 * 分析データが無いテンプレートは hasData:false（画面上は「—」表示）。
 */
function templateStats(templateId) {
  const posts = state.posts.filter((post) => post.templateId === templateId);
  const postIds = new Set(posts.map((post) => post.id));
  const metrics = state.metrics.filter((row) => row.postId && postIds.has(row.postId));
  const saveRateSum = metrics.reduce((sum, row) => sum + numberValue(row.saveRate), 0);
  const conversions = metrics.reduce((sum, row) => sum + numberValue(row.conversions), 0);
  const lastUsed = posts
    .map((post) => publishDateKey(post))
    .filter((key) => key && key !== "未設定")
    .sort()
    .pop() || "";
  return {
    uses: posts.length,
    hasData: metrics.length > 0,
    avgSaveRate: metrics.length ? Math.round((saveRateSum / metrics.length) * 10) / 10 : 0,
    avgConversions: metrics.length ? Math.round(conversions / metrics.length) : 0,
    lastUsed,
  };
}

/**
 * ハッシュタグの評価しきい値。参考画像の「推奨アクション」パネルの定義そのまま。
 * ステータスはデータとして持たず、平均保存率から毎回導出する（手入力とのズレを作らないため）。
 */
const hashtagTiers = [
  { key: "優秀", min: 2.5, tone: "good", note: "積極的に使用を推奨", desc: "保存率 2.5%以上" },
  { key: "良好", min: 1.5, tone: "ok", note: "継続的に使用・改善", desc: "保存率 1.5% - 2.5%" },
  { key: "要改善", min: 0.8, tone: "warn", note: "見直し・改善が必要", desc: "保存率 0.8% - 1.5%" },
  { key: "非推奨", min: 0, tone: "bad", note: "使用を控えることを推奨", desc: "保存率 0.8%未満" },
];

function hashtagTierOf(saveRate, hasData) {
  if (!hasData) return { key: "未計測", tone: "none", note: "分析データがまだありません", desc: "" };
  return hashtagTiers.find((tier) => saveRate >= tier.min) || hashtagTiers[hashtagTiers.length - 1];
}

/**
 * セットの中のタグを1本ずつにほどいて、タグ単位の実績を作る。
 *
 *   ハッシュタグセット（tags配列） → そのセットを使った投稿 → 投稿の分析データ
 *
 * という既存の連鎖をタグ単位に開いたもの。**タグごとの数値を手入力する場所は作らない**ので、
 * 投稿と分析さえ入っていれば自動で埋まり、二重管理にならない。
 * 同じタグが複数セットに入っている場合は、それらの投稿をすべて合算する。
 */
function hashtagTagStats() {
  const byTag = new Map();
  state.hashtagSets.forEach((set, setIndex) => {
    const posts = state.posts.filter((post) => post.hashtagSetId === set.id);
    (set.tags || []).forEach((tag) => {
      if (!tag) return;
      if (!byTag.has(tag)) {
        byTag.set(tag, { tag, categories: [], channels: new Set(), posts: [], setNames: [], setIndexes: [] });
      }
      const entry = byTag.get(tag);
      if (set.category && !entry.categories.includes(set.category)) entry.categories.push(set.category);
      entry.setNames.push(set.name || "(名称未設定)");
      entry.setIndexes.push(setIndex);
      posts.forEach((post) => {
        entry.posts.push(post);
        if (post.channel) entry.channels.add(post.channel);
      });
      if (set.channel) entry.channels.add(set.channel);
    });
  });

  return [...byTag.values()].map((entry) => {
    const postIds = new Set(entry.posts.map((post) => post.id));
    // 投稿の公開日順に並べると、そのままトレンド（保存率の推移）になる
    const metrics = state.metrics
      .filter((row) => row.postId && postIds.has(row.postId))
      .map((row) => ({ row, dateKey: publishDateKey(state.posts.find((post) => post.id === row.postId) || {}) }))
      .sort((a, b) => String(a.dateKey).localeCompare(String(b.dateKey)))
      .map((item) => item.row);

    const avg = (field) => (metrics.length
      ? Math.round((metrics.reduce((sum, row) => sum + numberValue(row[field]), 0) / metrics.length) * 100) / 100
      : 0);
    const total = (field) => metrics.reduce((sum, row) => sum + numberValue(row[field]), 0);
    const clicks = total("clicks");
    const reach = total("reach");
    const conversions = total("conversions");
    const saveRate = avg("saveRate");
    const lastUpdated = entry.posts
      .map((post) => publishDateKey(post))
      .filter((key) => key && key !== "未設定")
      .sort()
      .pop() || "";

    return {
      tag: entry.tag,
      category: entry.categories[0] || "未分類",
      categories: entry.categories,
      channels: [...entry.channels],
      setNames: [...new Set(entry.setNames)],
      setIndexes: [...new Set(entry.setIndexes)],
      posts: entry.posts.length,
      hasData: metrics.length > 0,
      saveRate,
      engagementRate: avg("engagementRate"),
      clickRate: reach ? Math.round((clicks / reach) * 1000) / 10 : 0,
      conversions,
      cvr: clicks ? Math.round((conversions / clicks) * 1000) / 10 : 0,
      trend: metrics.map((row) => numberValue(row.saveRate)),
      lastUpdated,
      tier: hashtagTierOf(saveRate, metrics.length > 0),
    };
  }).sort((a, b) => b.saveRate - a.saveRate || b.posts - a.posts);
}

/** 分布から100点満点の健康スコアを出す。優秀100 / 良好75 / 要改善40 / 非推奨10 の加重平均 */
function hashtagHealthScore(rows) {
  const scored = rows.filter((row) => row.hasData);
  if (!scored.length) return { score: 0, label: "データなし", counts: {}, scored: 0 };
  const weights = { 優秀: 100, 良好: 75, 要改善: 40, 非推奨: 10 };
  const counts = {};
  let sum = 0;
  scored.forEach((row) => {
    counts[row.tier.key] = (counts[row.tier.key] || 0) + 1;
    sum += weights[row.tier.key] ?? 0;
  });
  const score = Math.round(sum / scored.length);
  const label = score >= 80 ? "優秀" : score >= 60 ? "良好" : score >= 40 ? "要改善" : "要見直し";
  return { score, label, counts, scored: scored.length };
}

