function postMetricsFor(post) {
  const rows = state.metrics.filter((row) => row.postId && row.postId === post.id);
  if (!rows.length) return null;
  return {
    likes: rows.reduce((sum, row) => sum + numberValue(row.likes), 0),
    comments: rows.reduce((sum, row) => sum + numberValue(row.commentsCount), 0),
    saves: rows.reduce((sum, row) => sum + numberValue(row.saves), 0),
  };
}

/** 投稿1件の直近エンゲージメント。分析タブの metrics から postId で紐づけて算出する */
function postEngagement(post) {
  const rows = state.metrics.filter((row) => row.postId && row.postId === post.id);
  if (!rows.length) return null;
  const sum = (field) => rows.reduce((total, row) => total + numberValue(row[field]), 0);
  const impressions = sum("impressions");
  const saveRateSum = rows.reduce((total, row) => total + numberValue(row.saveRate), 0);
  return {
    saveRate: rows.length ? Math.round((saveRateSum / rows.length) * 10) / 10 : 0,
    clickRate: impressions ? Math.round((sum("clicks") / impressions) * 1000) / 10 : 0,
    conversions: sum("conversions"),
  };
}

function listOwnerOptions() {
  return [...new Set(state.posts.map((post) => post.owner).filter(Boolean))];
}

/** 検索・絞り込みを適用した投稿（表示順は最終更新日の新しい順） */
function filteredListPosts(basePosts) {
  const q = listSearch.trim().toLowerCase();
  return basePosts
    .filter((post) => {
      if (listFilters.channel && post.channel !== listFilters.channel) return false;
      if (listFilters.status && postWorkflowStage(post) !== listFilters.status) return false;
      if (listFilters.owner && post.owner !== listFilters.owner) return false;
      if (listFilters.campaignId && post.campaignId !== listFilters.campaignId) return false;
      if (!q) return true;
      const haystack = [post.title, post.hook, post.body, post.theme, post.funnel, hashtagSetLabel(post.hashtagSetId)]
        .filter(Boolean).join(" ").toLowerCase();
      return haystack.includes(q);
    })
    .sort((a, b) => String(b.updatedAt || "").localeCompare(String(a.updatedAt || "")));
}

function shortDate(value) {
  const raw = String(value || "").trim();
  if (!raw) return "-";
  const date = new Date(raw.length <= 10 ? `${raw}T00:00:00` : raw);
  if (Number.isNaN(date.getTime())) return raw;
  return `${date.getFullYear()}/${date.getMonth() + 1}/${date.getDate()}`;
}

/** アーカイブ1件の実績。分析タブの metrics から postId で紐づけて合計する */
function archiveStats(post) {
  const rows = state.metrics.filter((row) => row.postId && row.postId === post.id);
  const sum = (field) => rows.reduce((total, row) => total + numberValue(row[field]), 0);
  const saves = sum("saves");
  const clicks = sum("clicks");
  return {
    hasData: rows.length > 0,
    engagement: sum("likes") + saves + sum("commentsCount") + clicks,
    saves,
    clicks,
    conversions: sum("conversions"),
  };
}

function archivedPosts() {
  return state.posts
    .filter((post) => workflowStageOptions.includes(postWorkflowStage(post)))
    .sort((a, b) => String(b.publishAt || b.updatedAt || b.due || "").localeCompare(String(a.publishAt || a.updatedAt || a.due || "")));
}

function filteredArchivePosts(basePosts) {
  const q = archiveSearch.trim().toLowerCase();
  const now = new Date();
  const periodDays = { "30": 30, "90": 90, "365": 365 }[archiveFilters.period];
  return basePosts.filter((post) => {
    if (archiveFilters.channel && post.channel !== archiveFilters.channel) return false;
    if (archiveFilters.campaignId && post.campaignId !== archiveFilters.campaignId) return false;
    if (periodDays) {
      const key = String(post.publishAt || post.updatedAt || post.due || "").slice(0, 10);
      const date = key && key !== "未設定" ? new Date(`${key}T00:00:00`) : null;
      if (!date || Number.isNaN(date.getTime())) return false;
      if ((now - date) / 86400000 > periodDays) return false;
    }
    if (!q) return true;
    return [post.title, post.hook, post.body, post.theme, hashtagSetLabel(post.hashtagSetId)]
      .filter(Boolean).join(" ").toLowerCase().includes(q);
  });
}

function archiveView_(basePosts) {
  const matched = filteredArchivePosts(basePosts);
  const totalPages = Math.max(1, Math.ceil(matched.length / archivePageSize));
  const page = Math.min(archivePage, totalPages);
  const start = (page - 1) * archivePageSize;
  const pagePosts = matched.slice(start, start + archivePageSize);
  const hasFilter = archiveSearch || archiveFilters.channel || archiveFilters.period || archiveFilters.campaignId;
  // 平均エンゲージメントを基準に、各投稿が平均より上か下かを矢印で示す
  const withData = matched.map((p) => archiveStats(p)).filter((s) => s.hasData);
  const avgEngagement = withData.length ? withData.reduce((t, s) => t + s.engagement, 0) / withData.length : 0;

  return `
  <div class="list-layout">
    <div class="panel pad summary-card list-panel">
      <div class="archive-notice">
        <span class="archive-notice-icon">${icon("check")}</span>
        <div>
          <strong>アーカイブについて</strong>
          <p>企画・制作・確認・公開の投稿がここに残ります。過去の投稿は編集・複製して再利用できます。</p>
        </div>
      </div>

      <div class="list-toolbar">
        <label class="list-search">${icon("search")}
          <input type="search" placeholder="タイトル・本文・タグで検索" value="${escapeHtml(archiveSearch)}" data-archive-search>
        </label>
        <select data-archive-filter="channel">
          <option value="">すべてのSNS</option>
          ${activeChannelNames().map((n) => `<option value="${escapeHtml(n)}" ${archiveFilters.channel === n ? "selected" : ""}>${escapeHtml(n)}</option>`).join("")}
        </select>
        <select data-archive-filter="period">
          <option value="">更新・公開期間</option>
          ${[["30", "直近30日"], ["90", "直近90日"], ["365", "直近1年"]].map(([v, l]) => `<option value="${v}" ${archiveFilters.period === v ? "selected" : ""}>${l}</option>`).join("")}
        </select>
        <select data-archive-filter="campaignId">
          <option value="">すべてのキャンペーン</option>
          ${state.campaigns.map((c) => `<option value="${escapeHtml(c.id)}" ${archiveFilters.campaignId === c.id ? "selected" : ""}>${escapeHtml(c.name || "(名称未設定)")}</option>`).join("")}
        </select>
        ${hasFilter ? `<button class="btn small" data-archive-clear>クリア</button>` : ""}
      </div>

      <div class="archive-viewtoggle">
        <button class="viewtoggle-btn ${archiveView === "list" ? "active" : ""}" data-archive-view="list">${icon("dashboard")}<span>リスト表示</span></button>
        <button class="viewtoggle-btn ${archiveView === "grid" ? "active" : ""}" data-archive-view="grid">${icon("palette")}<span>サムネイル表示</span></button>
      </div>

      ${archiveView === "grid" ? `
        <div class="archive-grid">
          ${pagePosts.map((post) => {
            const index = state.posts.indexOf(post);
            const thumb = thumbnailSrc(post.thumbnail);
            const s = archiveStats(post);
            return `
              <article class="archive-card" data-select-post="${index}">
                <span class="archive-card-thumb ${thumb ? "" : "empty"}">${thumb ? `<img src="${escapeHtml(thumb)}" alt="" onerror="this.closest('.archive-card-thumb').classList.add('empty')">` : icon("palette")}</span>
                <div class="archive-card-body">
                  <strong>${escapeHtml(post.title || "(無題)")}</strong>
                  <small>${escapeHtml(shortDate(publishDateKey(post)))} / ${escapeHtml(post.channel || "-")}</small>
                  <div class="archive-card-stats"><span>${icon("heart")}${s.engagement.toLocaleString()}</span><span>${icon("save")}${s.saves}</span><span>${icon("cursor")}${s.clicks}</span></div>
                </div>
              </article>
            `;
          }).join("") || `<p class="panel-note">${hasFilter ? "条件に一致する投稿がありません" : "アーカイブされた投稿がありません"}</p>`}
        </div>
      ` : `
        <div class="table-wrap compact-table list-table archive-table">
          <table>
            <thead>
              <tr>
                <th>サムネイル</th><th>タイトル / 本文</th><th>SNS</th><th>公開日</th><th>キャンペーン</th>
                <th class="col-eng">エンゲージメント</th><th class="col-eng">保存数</th><th class="col-eng">リンククリック数</th><th class="col-eng">CV数</th><th>操作</th>
              </tr>
            </thead>
            <tbody>
              ${pagePosts.map((post) => {
                const index = state.posts.indexOf(post);
                const thumb = thumbnailSrc(post.thumbnail);
                const s = archiveStats(post);
                const iconUrl = socialIcon(post.channel);
                const trend = !s.hasData || !avgEngagement ? "" : s.engagement >= avgEngagement ? "up" : "down";
                return `
                  <tr data-select-post="${index}" class="${selectedPostIndex === index ? "row-selected" : ""}">
                    <td><span class="list-thumb ${thumb ? "" : "empty"}">${thumb ? `<img src="${escapeHtml(thumb)}" alt="" onerror="this.closest('.list-thumb').classList.add('empty')">` : icon("palette")}</span></td>
                    <td class="list-title-cell archive-title-cell">
                      <strong>${escapeHtml(post.title || "(無題)")}</strong>
                      <span class="status-badge ${statusClass(postWorkflowStage(post))}">${escapeHtml(postWorkflowStage(post))}・${escapeHtml(postDisplayStatus(post))}</span>
                      <span class="archive-excerpt">${escapeHtml(post.hook || post.body || "")}</span>
                      ${post.theme ? `<span class="pill tag">${escapeHtml(themeShortLabels[post.theme] || post.theme)}</span>` : ""}
                    </td>
                    <td><span class="platform-avatar small ${iconUrl ? "has-icon" : ""}">${iconUrl ? `<img src="${iconUrl}" alt="${escapeHtml(post.channel || "")}">` : escapeHtml((post.channel || "?").slice(0, 1))}</span></td>
                    <td>${escapeHtml(publishDateTimeLabel(post))}</td>
                    <td>${escapeHtml(campaignLabel(post.campaignId) || "-")}</td>
                    <td class="col-eng">${s.hasData ? `<span class="archive-eng ${trend}"><strong>${s.engagement.toLocaleString()}</strong>${trend ? (trend === "up" ? "↑" : "↓") : ""}</span>` : "–"}</td>
                    <td class="col-eng">${s.hasData ? s.saves.toLocaleString() : "–"}</td>
                    <td class="col-eng">${s.hasData ? s.clicks.toLocaleString() : "–"}</td>
                    <td class="col-eng">${s.hasData ? s.conversions : "–"}</td>
                    <td>
                      <span class="archive-ops" data-stop-propagation>
                        <button class="stage-add-btn" data-jump="analytics" title="分析を見る">${icon("chart")}</button>
                        <button class="stage-add-btn" data-duplicate-post="${index}" title="複製して再利用">${icon("copy")}</button>
                        <button class="stage-add-btn" data-open-post="${index}" title="編集">${icon("pencil")}</button>
                      </span>
                    </td>
                  </tr>
                `;
              }).join("") || `<tr><td colspan="10">${hasFilter ? "条件に一致する投稿がありません" : "企画・制作・確認・公開の投稿がありません"}</td></tr>`}
            </tbody>
          </table>
        </div>
      `}

      <div class="list-footer">
        <span class="panel-note">${matched.length ? `${start + 1} - ${Math.min(start + archivePageSize, matched.length)} / ${matched.length}件` : "0件"}</span>
        ${totalPages > 1 ? `
          <div class="list-pager">
            <button class="btn small" data-archive-page="${page - 1}" ${page === 1 ? "disabled" : ""}>‹</button>
            ${Array.from({ length: totalPages }, (_, i) => i + 1).map((n) => `<button class="btn small ${n === page ? "primary" : ""}" data-archive-page="${n}">${n}</button>`).join("")}
            <button class="btn small" data-archive-page="${page + 1}" ${page === totalPages ? "disabled" : ""}>›</button>
          </div>
        ` : ""}
        <label class="list-pagesize">表示件数
          <select data-archive-pagesize>
            ${[20, 50, 100].map((n) => `<option value="${n}" ${archivePageSize === n ? "selected" : ""}>${n}件</option>`).join("")}
          </select>
        </label>
      </div>
      <p class="archive-foot-note">※ アーカイブされた投稿は複製して再利用できます。実績データは分析・レポートタブと連動しています。</p>
    </div>
    ${selectedPostIndex !== null && state.posts[selectedPostIndex]
      ? pipelineDetailPanel(state.posts[selectedPostIndex], selectedPostIndex)
      : archiveSidePanel(matched)}
  </div>
  `;
}

/** アーカイブ右側のサイドパネル。サマリー・SNS別パフォーマンス・人気コンテンツTOP5 */
function archiveSidePanel(posts) {
  const stats = posts.map((post) => ({ post, s: archiveStats(post) }));
  const total = (field) => stats.reduce((sum, x) => sum + x.s[field], 0);
  const byChannel = {};
  posts.forEach((post) => {
    const key = post.channel || "未設定";
    byChannel[key] = (byChannel[key] || 0) + 1;
  });
  const channelRows = Object.entries(byChannel)
    .sort(([, a], [, b]) => b - a)
    .map(([name, count], i) => ({
      name, count,
      pct: posts.length ? Math.round((count / posts.length) * 100) : 0,
      color: ["#5168f6", "#111827", "#0a66c2", "#ef4444", "#20c997", "#ff8a3d", "#8b5cf6", "#14b8a6", "#94a3b8"][i % 9],
    }));
  const top5 = [...stats].filter((x) => x.s.hasData).sort((a, b) => b.s.engagement - a.s.engagement).slice(0, 5);

  return `
    <aside class="list-side">
      <div class="panel pad summary-card list-side-card">
        <div class="section-head"><h3>アーカイブサマリー</h3></div>
        <div class="archive-total">
          <span>合計投稿数</span><strong>${posts.length}<em>件</em></strong>
        </div>
        <div class="list-perf-grid">
          <div><span>エンゲージメント合計</span><strong>${total("engagement").toLocaleString()}</strong></div>
          <div><span>保存数合計</span><strong>${total("saves").toLocaleString()}</strong></div>
          <div><span>リンククリック数合計</span><strong>${total("clicks").toLocaleString()}</strong></div>
          <div><span>CV数合計</span><strong>${total("conversions").toLocaleString()}</strong></div>
        </div>
        <button class="btn small full-width" data-jump="analytics">詳細レポートを見る</button>
      </div>

      <div class="panel pad summary-card list-side-card">
        <div class="section-head"><h3>SNS別パフォーマンス</h3></div>
        ${posts.length ? `
          <div class="archive-donut-layout">
            <div class="archive-donut" style="background:${conicGradient(channelRows.map((r) => ({ pct: r.pct, color: r.color })))}">
              <div><small>合計</small><strong>${posts.length}件</strong></div>
            </div>
            <div class="archive-donut-legend">
              ${channelRows.map((r) => `
                <span><i style="background:${r.color}"></i>${escapeHtml(r.name)}<em>${r.count}件（${r.pct}%）</em></span>
              `).join("")}
            </div>
          </div>
          <button class="btn small full-width" data-jump="analytics">詳細を見る</button>
        ` : `<p class="panel-note">公開済みの投稿がまだありません</p>`}
      </div>

      <div class="panel pad summary-card list-side-card">
        <div class="section-head"><h3>人気コンテンツ TOP5</h3><span class="pill">エンゲージメント</span></div>
        ${top5.length ? `
          <ol class="archive-rank">
            ${top5.map((x, i) => `
              <li data-select-post="${state.posts.indexOf(x.post)}">
                <span class="archive-rank-no">${i + 1}</span>
                <span class="archive-rank-title">${escapeHtml(x.post.title || "(無題)")}</span>
                <strong>${x.s.engagement.toLocaleString()}</strong>
              </li>
            `).join("")}
          </ol>
          <button class="btn small full-width" data-jump="analytics">すべてのランキングを見る</button>
        ` : `<p class="panel-note">分析・レポートタブに実績を入力すると、ここにランキングが出ます</p>`}
      </div>
    </aside>
  `;
}

/** 一覧タブ右側のサイドパネル。投稿ステータス・今週のパフォーマンス・クイックアクション・ヒント */
function listSidePanel(basePosts) {
  // 今週（月曜〜日曜）に公開済みになった投稿の実績。分析タブのmetricsから算出する
  const now = new Date();
  const monday = new Date(now);
  monday.setHours(0, 0, 0, 0);
  monday.setDate(now.getDate() - ((now.getDay() + 6) % 7));
  const weekPublished = state.posts.filter((post) => {
    if (!postIsPublished(post)) return false;
    const key = publishDateKey(post);
    if (!key || key === "未設定") return false;
    const date = new Date(`${key}T00:00:00`);
    return !Number.isNaN(date.getTime()) && date >= monday;
  });
  const engagements = weekPublished.map((post) => postEngagement(post)).filter(Boolean);
  const avg = (field) => engagements.length
    ? Math.round((engagements.reduce((sum, e) => sum + e[field], 0) / engagements.length) * 10) / 10
    : 0;
  const totalCv = engagements.reduce((sum, e) => sum + e.conversions, 0);

  return `
    <aside class="list-side">
      <div class="panel pad summary-card list-side-card">
        <div class="section-head"><h3>投稿ステータス</h3><span class="pill">今週</span></div>
        <div class="list-status-list">
          ${statusOptions.map((status) => {
            const count = basePosts.filter((p) => postWorkflowStage(p) === status).length;
            return `
              <button class="list-status-row ${listFilters.status === status ? "active" : ""}" data-list-filter-status="${escapeHtml(status)}">
                <i style="background:${statusColors[status] || "#cbd5e1"}"></i>
                <span>${escapeHtml(status)}</span>
                <strong>${count}</strong><small>件</small>
              </button>
            `;
          }).join("")}
        </div>
        ${listFilters.status ? `<button class="btn small full-width" data-list-clear>すべてのステータスを見る</button>` : ""}
      </div>

      <div class="panel pad summary-card list-side-card">
        <div class="section-head"><h3>今週のパフォーマンス</h3><span class="pill">公開済み</span></div>
        <div class="list-perf-grid">
          <div><span>投稿数</span><strong>${weekPublished.length}<em>件</em></strong></div>
          <div><span>保存率（平均）</span><strong>${avg("saveRate")}<em>%</em></strong></div>
          <div><span>クリック率（平均）</span><strong>${avg("clickRate")}<em>%</em></strong></div>
          <div><span>CV数（合計）</span><strong>${totalCv}<em>件</em></strong></div>
        </div>
        <p class="panel-note">分析・レポートタブに入力した実績から自動集計しています。</p>
        <button class="btn small full-width" data-jump="analytics">詳細レポートを見る</button>
      </div>

      <div class="panel pad summary-card list-side-card">
        <div class="section-head"><h3>クイックアクション</h3></div>
        <p class="panel-note">ネタ出し → 制作 → 承認 → 公開の順に進みます。</p>
        <div class="list-actions">
          <button class="list-action" data-action="add-post">${icon("pencil")}<span><strong>投稿を作成</strong><small>空の投稿を追加して編集を開く</small></span></button>
          <button class="list-action" data-jump="ideas">${icon("lightbulb")}<span><strong>投稿案から作成</strong><small>ネタを「投稿化」して制作に回す</small></span></button>
          <button class="list-action" data-jump="design">${icon("palette")}<span><strong>デザインを準備</strong><small>テンプレート・素材リンクを開く</small></span></button>
          <button class="list-action" data-list-filter-status="確認">${icon("check")}<span><strong>確認中を確認</strong><small>意思決定者の確認が必要な投稿を表示</small></span></button>
        </div>
      </div>

      <div class="panel pad summary-card list-side-card list-hint">
        <div class="section-head"><h3>${icon("info")}使い方のヒント</h3></div>
        <ul>
          <li><strong>内容を確認・編集</strong>するには、操作列の${icon("pencil")}を押すと制作ページ（編集画面）が開きます。</li>
          <li><strong>行をクリック</strong>すると、右側に投稿の詳細プレビューが出ます。</li>
          <li><strong>企画・制作・確認・公開の投稿</strong>は「アーカイブ」タブからも履歴として確認できます。</li>
          <li>保存率・クリック率・CV数は、<strong>分析・レポートタブ</strong>に実績を入力すると自動で入ります。</li>
        </ul>
      </div>
    </aside>
  `;
}

function pipelineListSubView(basePosts, title) {
  const matched = filteredListPosts(basePosts);
  const totalPages = Math.max(1, Math.ceil(matched.length / listPageSize));
  const page = Math.min(listPage, totalPages);
  const start = (page - 1) * listPageSize;
  const pagePosts = matched.slice(start, start + listPageSize);
  const hasFilter = listSearch || listFilters.channel || listFilters.status || listFilters.owner || listFilters.campaignId;

  return `
  <div class="list-layout">
    <div class="panel pad summary-card list-panel">
      <div class="section-head"><div><h3>${escapeHtml(title)}</h3></div><span class="pill">${matched.length}件</span></div>

      <div class="list-toolbar">
        <label class="list-search">${icon("search")}
          <input type="search" placeholder="タイトル・本文・タグで検索" value="${escapeHtml(listSearch)}" data-list-search>
        </label>
        <select data-list-filter="channel">
          <option value="">すべてのSNS</option>
          ${activeChannelNames().map((name) => `<option value="${escapeHtml(name)}" ${listFilters.channel === name ? "selected" : ""}>${escapeHtml(name)}</option>`).join("")}
        </select>
        <select data-list-filter="status">
          <option value="">すべての状態</option>
          ${statusOptions.map((name) => `<option value="${escapeHtml(name)}" ${listFilters.status === name ? "selected" : ""}>${escapeHtml(name)}</option>`).join("")}
        </select>
        <select data-list-filter="owner">
          <option value="">すべての担当者</option>
          ${listOwnerOptions().map((name) => `<option value="${escapeHtml(name)}" ${listFilters.owner === name ? "selected" : ""}>${escapeHtml(name)}</option>`).join("")}
        </select>
        <select data-list-filter="campaignId">
          <option value="">すべてのキャンペーン</option>
          ${state.campaigns.map((c) => `<option value="${escapeHtml(c.id)}" ${listFilters.campaignId === c.id ? "selected" : ""}>${escapeHtml(c.name || "(名称未設定)")}</option>`).join("")}
        </select>
        ${hasFilter ? `<button class="btn small" data-list-clear>クリア</button>` : ""}
      </div>

      <div class="table-wrap compact-table list-table">
        <table>
          <thead>
            <tr>
              <th>サムネイル</th><th>タイトル</th><th>SNS</th><th>状態</th><th>担当者</th><th>キャンペーン</th><th>公開予定日時</th>
              <th class="col-eng">保存率</th><th class="col-eng">クリック率</th><th class="col-eng">CV数</th>
              <th>優先度</th><th>最終更新日</th><th>操作</th>
            </tr>
          </thead>
          <tbody>
            ${pagePosts.map((post) => {
              const index = state.posts.indexOf(post);
              const thumb = thumbnailSrc(post.thumbnail);
              const eng = postEngagement(post);
              const iconUrl = socialIcon(post.channel);
              return `
                <tr data-select-post="${index}" class="${selectedPostIndex === index ? "row-selected" : ""}">
                  <td><span class="list-thumb ${thumb ? "" : "empty"}">${thumb ? `<img src="${escapeHtml(thumb)}" alt="" onerror="this.closest('.list-thumb').classList.add('empty')">` : icon("palette")}</span></td>
                  <td class="list-title-cell">
                    <strong>${escapeHtml(post.title || "(無題)")}</strong>
                    ${post.theme ? `<span class="pill tag">${escapeHtml(themeShortLabels[post.theme] || post.theme)}</span>` : ""}
                  </td>
                  <td><span class="platform-avatar small ${iconUrl ? "has-icon" : ""}">${iconUrl ? `<img src="${iconUrl}" alt="${escapeHtml(post.channel || "")}">` : escapeHtml((post.channel || "?").slice(0, 1))}</span></td>
                  <td><span class="status-badge ${statusClass(postWorkflowStage(post))}">${escapeHtml(postWorkflowStage(post))}</span><small class="workflow-substatus">${escapeHtml(postDisplayStatus(post))}</small></td>
                  <td><span class="list-owner"><span class="avatar-dot small">${escapeHtml((post.owner || "?").slice(0, 1))}</span>${escapeHtml(post.owner || "-")}</span></td>
                  <td>${escapeHtml(campaignLabel(post.campaignId) || "-")}</td>
                  <td>${escapeHtml(publishDateTimeLabel(post))}</td>
                  <td class="col-eng">${eng ? `${eng.saveRate}%` : "–"}</td>
                  <td class="col-eng">${eng ? `${eng.clickRate}%` : "–"}</td>
                  <td class="col-eng">${eng ? eng.conversions : "–"}</td>
                  <td><span class="pill ${post.priority === "高" ? "high" : post.priority === "中" ? "mid" : ""}">${escapeHtml(post.priority || "-")}</span></td>
                  <td>${escapeHtml(shortDate(post.updatedAt))}</td>
                  <td><button class="stage-add-btn" data-open-post="${index}" title="制作ページを開く" data-stop-propagation>${icon("pencil")}</button></td>
                </tr>
              `;
            }).join("") || `<tr><td colspan="13">${hasFilter ? "条件に一致する投稿がありません" : "投稿がありません"}</td></tr>`}
          </tbody>
        </table>
      </div>

      <div class="list-footer">
        <span class="panel-note">${matched.length ? `${start + 1} - ${Math.min(start + listPageSize, matched.length)} / ${matched.length}件` : "0件"}</span>
        ${totalPages > 1 ? `
          <div class="list-pager">
            <button class="btn small" data-list-page="${page - 1}" ${page === 1 ? "disabled" : ""}>‹</button>
            ${Array.from({ length: totalPages }, (_, i) => i + 1).map((n) => `<button class="btn small ${n === page ? "primary" : ""}" data-list-page="${n}">${n}</button>`).join("")}
            <button class="btn small" data-list-page="${page + 1}" ${page === totalPages ? "disabled" : ""}>›</button>
          </div>
        ` : ""}
        <label class="list-pagesize">表示件数
          <select data-list-pagesize>
            ${[10, 25, 50].map((n) => `<option value="${n}" ${listPageSize === n ? "selected" : ""}>${n}件</option>`).join("")}
          </select>
        </label>
      </div>
    </div>
    ${selectedPostIndex !== null && state.posts[selectedPostIndex]
      ? pipelineDetailPanel(state.posts[selectedPostIndex], selectedPostIndex)
      : listSidePanel(basePosts)}
  </div>
  `;
}

function pipelineCard(post, index) {
  const platformIconUrl = socialIcon(post.channel);
  const dateStr = dayLabel(publishDateKey(post));
  const time = publishTime(post);
  const ownerInitial = (post.owner || "?").trim().slice(0, 1).toUpperCase();
  const themeTag = post.theme ? (themeShortLabels[post.theme] || post.theme) : "";
  const showStatus = true;
  const engagement = postIsPublished(post) ? postMetricsFor(post) : null;
  return `
    <article class="pipeline-card ${selectedPostIndex === index ? "selected" : ""}" data-select-post="${index}">
      <div class="pipeline-card-top">
        <span class="platform-avatar small ${platformIconUrl ? "has-icon" : ""}">${platformIconUrl ? `<img src="${platformIconUrl}" alt="${escapeHtml(post.channel || "")}">` : escapeHtml((post.channel || "?").slice(0, 1))}</span>
        <strong class="pipeline-card-title">${escapeHtml(post.title || "(無題)")}</strong>
      </div>
      <div class="pipeline-card-badges">
        <span class="pill soft">${escapeHtml(post.format || "未設定")}</span>
        ${showStatus ? `<span class="status-badge ${statusClass(postWorkflowStage(post))}">${escapeHtml(postDisplayStatus(post))}</span>` : ""}
      </div>
      <div class="pipeline-card-date">${escapeHtml(dateStr)}${showStatus && time ? ` ${escapeHtml(time)}` : ""}</div>
      ${engagement ? `
        <div class="pipeline-card-stats">
          <span title="いいね">${icon("heart")}${engagement.likes.toLocaleString()}</span>
          <span title="コメント">${icon("message")}${engagement.comments.toLocaleString()}</span>
          <span title="保存">${icon("save")}${engagement.saves.toLocaleString()}</span>
        </div>
      ` : ""}
      <div class="pipeline-card-tags">
        ${themeTag ? `<span class="pill tag">${escapeHtml(themeTag)}</span>` : ""}
        ${post.funnel ? `<span class="pill tag">${escapeHtml(post.funnel)}</span>` : ""}
        ${postSourceIdea(post) ? `<button class="pill tag idea-origin" data-jump-idea="${escapeHtml(post.ideaId)}" data-stop-propagation title="元ネタ（投稿案）を開く">${icon("lightbulb")}元ネタ</button>` : ""}
        <span class="avatar-dot small pipeline-card-avatar" title="${escapeHtml(post.owner || "未割当")}">${escapeHtml(ownerInitial || "?")}</span>
      </div>
    </article>
  `;
}

function publishDateTimeLabel(post) {
  const dateKey = publishDateKey(post);
  if (!post.publishAt || dateKey === "未設定") return "未設定";
  const date = new Date(`${dateKey}T00:00:00`);
  const weekday = Number.isNaN(date.getTime()) ? "" : date.toLocaleDateString("ja-JP", { weekday: "short" });
  const time = publishTime(post);
  return `${dateKey.replace(/-/g, "/")}${weekday ? ` (${weekday})` : ""}${time ? ` ${time}` : ""}`;
}

function pipelineDetailPanel(post, index) {
  const thumbSrc = thumbnailSrc(post.thumbnail);
  const stage = postWorkflowStage(post);
  const decisionAllowed = canDecidePost(post);
  const canAdvance = stage !== "公開" && (stage === "制作" ? canEdit("pipeline") : decisionAllowed);
  const actionLabel = { "企画": "企画を承認", "制作": "確認へ提出", "確認": "承認して公開へ" }[stage] || "";
  const decisionMaker = post.approver || "未設定（承認権限者）";
  const latestReturn = Array.isArray(post.returnHistory) ? post.returnHistory[post.returnHistory.length - 1] : null;
  const planningMissing = stage === "企画" ? planningMissingFields(post) : [];
  return `
    <aside class="pipeline-detail-panel">
      <div class="pipeline-detail-head">
        <h3>選択中の投稿</h3>
        <button class="icon-btn" data-action="close-post-detail">${icon("close")}</button>
      </div>
      <div class="pipeline-detail-card">
        <span class="platform-avatar ${socialIcon(post.channel) ? "has-icon" : ""}">${socialIcon(post.channel) ? `<img src="${socialIcon(post.channel)}" alt="">` : escapeHtml((post.channel || "?").slice(0, 1))}</span>
        <div><strong>${escapeHtml(post.title || "(無題)")}</strong><span class="pill">${escapeHtml(post.format || "未設定")}</span></div>
      </div>
      <div class="pipeline-detail-section">
        <h4>基本情報</h4>
        <dl class="pipeline-detail-list">
          <div><dt>工程</dt><dd><span class="status-badge ${statusClass(stage)}">${escapeHtml(stage)}</span></dd></div>
          <div><dt>内部状態</dt><dd>${escapeHtml(postDisplayStatus(post))}</dd></div>
          <div><dt>担当者</dt><dd><span class="avatar-dot small">${escapeHtml((post.owner || "?").slice(0, 1))}</span>${escapeHtml(post.owner || "未割当")}</dd></div>
          <div><dt>意思決定者</dt><dd>${escapeHtml(decisionMaker)}</dd></div>
          <div><dt>公開予定</dt><dd>${escapeHtml(publishDateTimeLabel(post))}</dd></div>
          <div><dt>目的</dt><dd>${escapeHtml(post.purpose || "未設定")}</dd></div>
          <div><dt>伝えたい内容</dt><dd>${escapeHtml(post.keyMessage || post.hook || "未設定")}</dd></div>
          <div><dt>目標KPI</dt><dd>${escapeHtml(post.goalKpi || "未設定")}</dd></div>
          <div><dt>キャンペーン</dt><dd>${escapeHtml(campaignLabel(post.campaignId) || "未設定")}</dd></div>
          <div><dt>ペルソナ</dt><dd>${escapeHtml(personaLabel(post.personaId) || "未設定")}</dd></div>
          ${(() => { const src = postSourceIdea(post); return src ? `<div><dt>元ネタ</dt><dd><button class="link-idea" data-jump-idea="${escapeHtml(src.id)}" title="投稿案タブで開く">${icon("lightbulb")}<span>${escapeHtml(src.title || "投稿案")}</span></button></dd></div>` : ""; })()}
          ${(() => { const cm = commentsForPost(post.id); return cm.count ? `<div><dt>コメント</dt><dd><button class="link-comments" data-jump="comments" title="コメント管理へ">${icon("message")}<span>${cm.count}件${cm.unresolved ? ` ・ 未対応${cm.unresolved}` : ""}</span></button></dd></div>` : ""; })()}
          ${latestReturn ? `<div><dt>最新の差し戻し</dt><dd>${escapeHtml(latestReturn.toStage)}へ・${escapeHtml(latestReturn.reason)}</dd></div>` : ""}
        </dl>
      </div>
      ${planningMissing.length ? `<div class="pipeline-detail-section workflow-warning"><h4>企画承認までに必要</h4><p>${planningMissing.map(escapeHtml).join("、")}</p></div>` : ""}
      <details class="pipeline-detail-section" open>
        <summary>内容サマリー</summary>
        <p>${escapeHtml(post.hook || post.body || "未入力")}</p>
      </details>
      <details class="pipeline-detail-section" open>
        <summary>プレビュー</summary>
        ${thumbSrc
          ? `<div class="pipeline-preview-image" data-open-post="${index}" title="クリックして編集">
               <img src="${escapeHtml(thumbSrc)}" alt="${escapeHtml(post.title || "投稿サムネイル")}" onerror="this.closest('.pipeline-preview-image').classList.add('media-error')">
             </div>
             <div class="pipeline-preview-fallback" aria-hidden="true">
               <span>${escapeHtml(post.hook || "")}</span>
               <strong>${escapeHtml(post.title || "(無題)")}</strong>
             </div>`
          : `<button class="pipeline-preview-empty" data-open-post="${index}">
               ${icon("palette")}
               <strong>プレビュー画像を設定</strong>
               <small>投稿を編集して、サムネイルURLまたはGoogle Drive画像URLを登録すると、ここに表示されます</small>
             </button>`}
      </details>
      <div class="pipeline-detail-section">
        <h4>アクション</h4>
        <div class="pipeline-detail-actions">
          <button class="action-btn edit" data-open-post="${index}">${icon("pencil")}<span>編集する</span></button>
          ${canAdvance ? `<button class="action-btn approve" data-action="approve-post" data-post-index="${index}">${icon("check")}<span>${escapeHtml(actionLabel)}</span></button>` : (stage !== "公開" ? `<button class="action-btn approve" disabled title="意思決定者のみ操作できます">${icon("check")}<span>${escapeHtml(actionLabel)}</span></button>` : "")}
          ${stage === "確認" && decisionAllowed ? `<button class="action-btn reject" data-action="reject-post" data-post-index="${index}">${icon("undo")}<span>差し戻す</span></button>` : ""}
          ${stage === "公開" ? `<button class="action-btn edit" data-action="create-post-revision" data-post-index="${index}">${icon("copy")}<span>修正版を作成</span></button>${postPublicationStatus(post) !== "公開停止" ? `<button class="action-btn reject" data-action="stop-publication" data-post-index="${index}">${icon("ban")}<span>公開停止</span></button>` : `<button class="action-btn reject" data-open-stop-feedback>${icon("message")}<span>停止理由を見る</span></button>`}` : ""}
          <button class="action-btn delete" data-delete-post="${index}">${icon("ban")}<span>投稿を削除</span></button>
        </div>
      </div>
    </aside>
  `;
}

function scheduleView() {
  const scheduledMap = postsByDate();
  const scheduledPosts = state.posts.filter((post) => publishDateKey(post) !== "未設定");
  const readyPosts = state.posts.filter(isPublishReady);
  const unscheduled = state.posts.filter((post) => !String(post.publishAt || "").trim());
  const viewTabs = [["calendar", "カレンダー"], ["date", "日付順"], ["channel", "媒体別"]];

  const main = scheduleMode === "calendar"
    ? calendarGrid(scheduledMap)
    : scheduleListView(scheduledPosts);

  return `
    <section class="section notion-section ${activeTab === "schedule" ? "active" : ""}" data-section="schedule">
      <div class="notion-page-head cal-page-head">
        <div>
          <span class="eyebrow">Publish schedule</span>
          <h2>投稿スケジュール</h2>
          <p class="panel-note">投稿管理のコンテンツを公開日ごとにカレンダーで確認する。カードをクリックすると詳細を編集でき、変更は投稿管理・投稿ボード・分析にも反映されます。</p>
        </div>
        <div class="cal-head-right">
          <div class="notion-tabs">
            ${viewTabs.map(([id, label]) => `<span class="${scheduleMode === id ? "active" : ""}" data-schedule-mode="${id}">${label}</span>`).join("")}
          </div>
          <div class="cal-count-pills">
            <span class="cal-count"><i class="dot gray"></i>未設定 ${unscheduled.length}</span>
            <span class="cal-count"><i class="dot green"></i>公開OK ${readyPosts.length}</span>
          </div>
        </div>
      </div>
      <div class="calendar-layout">
        ${main}
        ${scheduleSidebar(scheduledMap)}
      </div>
    </section>
  `;
}

function calendarGrid(scheduledMap) {
  const base = calendarBaseDate();
  const month = base.getMonth();
  const todayStr = ymdKey(new Date());
  const monthLabel = `${base.getFullYear()}年${month + 1}月`;
  const firstMonday = new Date(base);
  firstMonday.setDate(base.getDate() - ((base.getDay() + 6) % 7));
  const weekdays = ["月", "火", "水", "木", "金", "土", "日"];
  const cells = [];
  for (let i = 0; i < 42; i += 1) {
    const day = new Date(firstMonday);
    day.setDate(firstMonday.getDate() + i);
    cells.push(day);
  }
  // 6週目がまるごと翌月ならその行を省いて5週表示にする
  while (cells.length > 35 && cells[cells.length - 7].getMonth() !== month) {
    cells.splice(cells.length - 7, 7);
  }
  return `
    <div class="calendar-main">
      <div class="cal-toolbar">
        <div class="cal-nav">
          <button class="cal-nav-btn prev" data-cal-nav="prev" aria-label="前の月">${icon("chevron")}</button>
          <button class="cal-today-btn" data-cal-nav="today">今日</button>
          <button class="cal-nav-btn" data-cal-nav="next" aria-label="次の月">${icon("chevron")}</button>
        </div>
        <h3 class="cal-month-label">${monthLabel}</h3>
        <div class="cal-toolbar-spacer"></div>
      </div>
      <div class="cal-grid">
        ${weekdays.map((w, i) => `<div class="cal-weekday ${i >= 5 ? "weekend" : ""}">${w}</div>`).join("")}
        ${cells.map((day) => {
          const key = ymdKey(day);
          const inMonth = day.getMonth() === month;
          const isToday = key === todayStr;
          const weekend = day.getDay() === 0 || day.getDay() === 6;
          const items = scheduledMap[key] || [];
          const shown = items.slice(0, 3);
          const extra = items.length - shown.length;
          return `
            <div class="cal-cell ${inMonth ? "" : "is-out"} ${isToday ? "is-today" : ""} ${weekend ? "is-weekend" : ""}">
              <div class="cal-cell-date">${day.getDate()}</div>
              <div class="cal-cell-events">
                ${shown.map(({ post, index }) => {
                  const st = postScheduleStatus(post);
                  const iconSrc = socialIcon(post.channel);
                  const time = publishTime(post);
                  return `
                    <button class="cal-event tone-${st.tone}" data-open-post="${index}" title="${escapeHtml((time ? time + " " : "") + (post.title || "無題") + " ・ " + st.label)}">
                      <span class="cal-event-ico">${iconSrc ? `<img src="${iconSrc}" alt="${escapeHtml(post.channel || "")}">` : escapeHtml((post.channel || "?").slice(0, 1))}</span>
                      ${time ? `<span class="cal-event-time">${escapeHtml(time)}</span>` : ""}
                      <span class="cal-event-title">${escapeHtml(post.title || "無題")}</span>
                    </button>
                  `;
                }).join("")}
                ${extra > 0 ? `<button class="cal-event-more" data-open-post="${items[3].index}">他${extra}件</button>` : ""}
              </div>
            </div>
          `;
        }).join("")}
      </div>
    </div>
  `;
}

function scheduleListView(scheduledPosts) {
  const isChannel = scheduleMode === "channel";
  const buckets = scheduledPosts.reduce((acc, post) => {
    const key = isChannel ? (post.channel || "未設定") : publishDateKey(post);
    (acc[key] = acc[key] || []).push(post);
    return acc;
  }, {});
  const keys = Object.keys(buckets).sort((a, b) => {
    if (isChannel) return a.localeCompare(b);
    return a === "未設定" ? 1 : b === "未設定" ? -1 : a.localeCompare(b);
  });
  return `
    <div class="calendar-main sched-list-main">
      ${keys.length ? keys.map((key) => {
        const items = buckets[key].sort((a, b) => String(a.publishAt || "").localeCompare(String(b.publishAt || "")));
        const iconSrc = isChannel ? socialIcon(key) : "";
        const label = isChannel ? key : dayLabel(key);
        return `
          <section class="sched-group">
            <div class="sched-group-head">
              ${isChannel
                ? `<span class="sched-group-ico ${iconSrc ? "has-icon" : ""}">${iconSrc ? `<img src="${iconSrc}" alt="${escapeHtml(key)}">` : escapeHtml(key.slice(0, 1))}</span>`
                : `<span class="sched-group-datechip">${icon("calendar")}</span>`}
              <h3>${escapeHtml(label)}</h3>
              <span class="sched-group-count">${items.length}件</span>
            </div>
            <div class="sched-group-grid">
              ${items.map((post) => scheduleCard(post, state.posts.indexOf(post))).join("")}
            </div>
          </section>
        `;
      }).join("") : `
        <div class="empty-state">
          <h3>公開日時が設定された投稿がまだありません</h3>
          <p>投稿管理で投稿の「公開日時」を設定すると、こことカレンダーに表示されます。</p>
        </div>
      `}
    </div>
  `;
}

function scheduleCard(post, index) {
  const alert = postAlert(post);
  const st = postScheduleStatus(post);
  const iconSrc = socialIcon(post.channel);
  const time = publishTime(post);
  const dateKey = publishDateKey(post);
  const when = dateKey === "未設定" ? "日時未設定" : `${dayLabel(dateKey)}${time ? ` ${time}` : ""}`;
  return `
    <article class="sched-card tone-${st.tone}" data-open-post="${index}">
      <div class="sched-card-head">
        <span class="sched-card-ico ${iconSrc ? "has-icon" : ""}">${iconSrc ? `<img src="${iconSrc}" alt="${escapeHtml(post.channel || "")}">` : escapeHtml((post.channel || "?").slice(0, 1))}</span>
        <div class="sched-card-when">
          <span class="sched-card-time">${escapeHtml(when)}</span>
          <span class="sched-card-channel">${escapeHtml(post.channel || "-")}</span>
        </div>
        <span class="cal-status-pill tone-${st.tone}">${st.label}</span>
      </div>
      <h4 class="sched-card-title">${escapeHtml(post.title || "無題")}</h4>
      ${post.hook || post.body ? `<p class="sched-card-hook">${escapeHtml(post.hook || post.body)}</p>` : ""}
      <div class="sched-card-chips">
        <span class="sched-chip">${icon("users")}${escapeHtml(post.owner || "担当未定")}</span>
        ${post.theme ? `<span class="sched-chip"><i class="sched-chip-dot" style="background:${(typeof themeColors !== "undefined" && themeColors[post.theme]) || "#cbd5e1"}"></i>${escapeHtml(post.theme)}</span>` : ""}
        ${alert ? `<span class="sched-chip is-alert">${icon("info")}${escapeHtml(alert)}</span>` : ""}
      </div>
      <div class="sched-card-foot">
        <span class="sched-card-status">工程 <strong>${escapeHtml(postWorkflowStage(post))}</strong>・${escapeHtml(postDisplayStatus(post))}</span>
        <span class="sched-card-open">${icon("pencil")}編集</span>
      </div>
    </article>
  `;
}

function scheduleSidebar(scheduledMap) {
  const today0 = new Date();
  today0.setHours(0, 0, 0, 0);
  const days = [];
  for (let i = 0; i < 7; i += 1) {
    const date = new Date(today0);
    date.setDate(today0.getDate() + i);
    const key = ymdKey(date);
    days.push({ date, key, items: scheduledMap[key] || [] });
  }
  const firstWithPosts = days.find((day) => day.items.length > 0);
  const legend = [
    ["green", "公開OK", "公開準備完了"],
    ["orange", "確認中", "確認作業中"],
    ["blue", "制作中", "制作中"],
    ["gray", "日時未設定", "公開日時が未設定"],
  ];
  return `
    <aside class="calendar-sidebar">
      <div class="cal-panel">
        <div class="cal-panel-head"><h3>スケジュール一覧</h3></div>
        ${days.map((day) => {
          const label = day.date.toLocaleDateString("ja-JP", { year: "numeric", month: "long", day: "numeric", weekday: "short" });
          const isLead = firstWithPosts && day.key === firstWithPosts.key;
          if (isLead) {
            return `
              <div class="side-sched-group">
                <div class="side-sched-daterow is-lead"><span>${escapeHtml(label)}</span><span class="side-sched-count">${day.items.length}件</span></div>
                <div class="side-sched-list">
                  ${day.items.map(({ post, index }) => {
                    const st = postScheduleStatus(post);
                    const iconSrc = socialIcon(post.channel);
                    return `
                      <button class="side-sched-item" data-open-post="${index}">
                        <span class="side-sched-ico">${iconSrc ? `<img src="${iconSrc}" alt="${escapeHtml(post.channel || "")}">` : escapeHtml((post.channel || "?").slice(0, 1))}</span>
                        <span class="side-sched-body">
                          <span class="side-sched-time">${escapeHtml(publishTime(post) || "時間未設定")}</span>
                          <span class="side-sched-title">${escapeHtml(post.title || "無題")}</span>
                          ${post.format ? `<span class="side-sched-format">${escapeHtml(post.format)}</span>` : ""}
                        </span>
                        <span class="cal-status-pill tone-${st.tone}">${st.label}</span>
                      </button>
                    `;
                  }).join("")}
                </div>
              </div>
            `;
          }
          return `<button class="side-sched-daterow" data-cal-goto="${day.key}"><span>${escapeHtml(label)}</span><span class="side-sched-count ${day.items.length ? "" : "zero"}">${day.items.length}件</span></button>`;
        }).join("")}
        <button class="side-sched-all" data-schedule-mode="date">すべてのスケジュールを見る ${icon("chevron")}</button>
      </div>
      <div class="cal-panel">
        <div class="cal-panel-head"><h3>ステータスの凡例</h3></div>
        <div class="cal-legend">
          ${legend.map(([tone, label, desc]) => `<div class="cal-legend-row"><i class="dot ${tone}"></i><strong>${label}</strong><small>${desc}</small></div>`).join("")}
        </div>
      </div>
      <div class="cal-panel cal-hint-panel">
        <div class="cal-hint-head">${icon("info")}<strong>使い方のヒント</strong></div>
        <p>公開日時が設定された投稿を、ステータス別に表示します。カードをクリックすると詳細を開いて編集でき、変更は投稿管理・投稿ボードにも即反映されます。</p>
      </div>
    </aside>
  `;
}

function compactPostCard(post, index) {
  const alert = postAlert(post);
  return `
    <article class="post-card-compact" data-open-post="${index}">
      <div class="post-compact-top">
        <span class="pill ${post.priority === "高" ? "high" : post.priority === "中" ? "mid" : ""}">${escapeHtml(post.priority)}</span>
        ${alert ? `<span class="pill high">${escapeHtml(alert)}</span>` : ""}
        <span class="pill">${escapeHtml(post.channel || "-")}</span>
      </div>
      <strong class="post-compact-title">${escapeHtml(post.title || "(無題)")}</strong>
      <div class="post-compact-meta">
        <span>${escapeHtml(post.due ? `期限 ${post.due}` : "期限未設定")}</span>
      </div>
      <div class="post-compact-bottom" data-stop-propagation>
        <span class="status-badge ${statusClass(postWorkflowStage(post))}">${escapeHtml(postWorkflowStage(post))}・${escapeHtml(postDisplayStatus(post))}</span>
        <button class="btn small" data-open-post="${index}">詳細</button>
      </div>
    </article>
  `;
}

function postModal() {
  if (openPostIndex === null || openPostIndex === undefined) return "";
  const index = openPostIndex;
  const post = state.posts[index];
  if (!post) return "";
  const charCount = String(post.body || "").length;
  const alert = postAlert(post);
  const thumbSrc = thumbnailSrc(post.thumbnail);
  const isCreating = creatingPostId === post.id;
  return `
    <div class="modal-backdrop" data-action="close-post-modal">
      <div class="modal-panel" data-stop-propagation>
        <div class="modal-head">
          <div class="status-cluster">
            <span class="pill ${post.priority === "高" ? "high" : post.priority === "中" ? "mid" : ""}">${escapeHtml(post.priority)}</span>
            ${alert ? `<span class="pill high">${escapeHtml(alert)}</span>` : ""}
            <span class="pill">${charCount}字</span>
          </div>
          <button class="btn icon-btn" data-action="close-post-modal">${icon("reset")}<span>閉じる</span></button>
        </div>
        <label>投稿名 ${input(`posts.${index}.title`, post.title)}</label>
        <div class="fields two">
          ${isCreating ? `<label>工程 <select data-new-post-stage>${workflowStageOptions.map((stage) => `<option value="${stage}" ${postWorkflowStage(post) === stage ? "selected" : ""}>${stage}</option>`).join("")}</select></label>` : `<div class="field-group"><span class="field-group-label">工程</span><strong>${escapeHtml(postWorkflowStage(post))}</strong><span class="panel-note">工程移動は投稿ボードの操作から行います</span></div>`}
          ${!isCreating && postWorkflowStage(post) === "公開" ? `<label>公開状態 ${select(`posts.${index}.publicationStatus`, postPublicationStatus(post), publicationStatusOptions)}</label>` : ""}
          <label>優先度 ${select(`posts.${index}.priority`, post.priority, priorityOptions)}</label>
          <label>キャンペーン ${select(`posts.${index}.campaignId`, post.campaignId || "", campaignOptionsWithNew())}</label>
          <label>SNSアカウント ${accountSelect(`posts.${index}.accountId`, post.accountId, post.channel)}</label>
          <label>形式 ${select(`posts.${index}.format`, post.format || "", formatOptions)}</label>
          <label>担当 ${memberSelect(`posts.${index}.owner`, post.owner)}</label>
          <div class="field-group">
            <span class="field-group-label">意思決定者・確認者</span>
            <div class="field-group-inputs">
              <label class="field-sub">意思決定者 ${memberSelect(`posts.${index}.approver`, post.approver || "")}</label>
              <label class="field-sub">確認者 ${input(`posts.${index}.checker`, post.checker || "")}</label>
            </div>
          </div>
          ${!isCreating ? `<label>承認状態 ${select(`posts.${index}.approval`, post.approval || "未申請", ["未申請", "承認待ち", "承認済み", "差戻し"])}</label>` : ""}
          <label>期限 ${input(`posts.${index}.due`, post.due, "date")}</label>
          <label>公開日時 ${input(`posts.${index}.publishAt`, post.publishAt, "datetime-local")}</label>
          <label>ターゲットペルソナ ${select(`posts.${index}.personaId`, post.personaId || "", personaOptions())}</label>
          ${(() => { const src = postSourceIdea(post); return src ? `<div class="field-group"><span class="field-group-label">元ネタ（投稿案）</span><button type="button" class="link-idea" data-jump-idea="${escapeHtml(src.id)}" title="投稿案タブで開く">${icon("lightbulb")}<span>${escapeHtml(src.title || "投稿案")}</span>${icon("external")}</button></div>` : ""; })()}
          <label>カテゴリー ${select(`posts.${index}.funnel`, post.funnel || "認知", ["認知", "興味", "比較検討", "CV", "継続"])}</label>
          <label>テーマ ${select(`posts.${index}.theme`, post.theme || "", themeOptions)}</label>
          <label>投稿の目的 ${input(`posts.${index}.purpose`, post.purpose || "")}<span class="panel-note">企画承認に必要です</span></label>
          <label>伝えたい内容 ${input(`posts.${index}.keyMessage`, post.keyMessage || "")}<span class="panel-note">企画承認に必要です</span></label>
          <label>目標KPI ${select(`posts.${index}.goalKpi`, post.goalKpi || "", [{ value: "", label: "未設定" }, ...goalKpiOptions.map((v) => ({ value: v, label: v }))])}<span class="panel-note">投稿戦略のKPIファネル・サマリーに集計されます</span></label>
          <label>最終更新日 ${input(`posts.${index}.updatedAt`, post.updatedAt || "", "datetime-local")}<span class="panel-note">未入力でも編集時に自動記録されます</span></label>
        </div>
        <label>内容サマリー ${textarea(`posts.${index}.hook`, post.hook, 2)}<span class="panel-note">投稿ボードの右パネル「内容サマリー」に表示されます</span></label>
        <label>投稿文 ${textarea(`posts.${index}.body`, post.body || "", 3)}</label>
        <div class="fields two">
          <label>使用テンプレート ${select(`posts.${index}.templateId`, post.templateId || "", templateOptions())}<span class="panel-note">デザイン管理のテンプレート実績（使用回数・平均保存率・平均CV）に集計されます</span></label>
          <label>ハッシュタグセット ${select(`posts.${index}.hashtagSetId`, post.hashtagSetId || "", hashtagOptions())}</label>
          <label>CTA ${input(`posts.${index}.cta`, post.cta)}</label>
          <label>素材 ${input(`posts.${index}.asset`, post.asset)}</label>
          <label>サムネイルURL / Google Drive画像URL ${input(`posts.${index}.thumbnail`, post.thumbnail || "")}</label>
          <label>承認メモ ${textarea(`posts.${index}.approvalMemo`, post.approvalMemo || "", 2)}</label>
        </div>
        <div class="thumbnail-field">
          <div class="thumbnail-field-head">
            <span class="panel-note">プレビュー（投稿ボードの右パネル・サマリーの「次に出す投稿」にも反映されます）</span>
            <div class="thumbnail-actions">
              <label class="btn small thumbnail-upload">
                ${icon("upload")}<span>画像ファイルを選ぶ</span>
                <input type="file" accept="image/png,image/jpeg,image/gif,image/webp" data-thumbnail-file="${index}" hidden>
              </label>
              ${post.thumbnail ? `<button class="btn small danger" data-clear-thumbnail="${index}">クリア</button>` : ""}
            </div>
          </div>
          ${thumbSrc
            ? `<div class="thumbnail-preview"><img src="${escapeHtml(thumbSrc)}" alt="投稿サムネイル" onerror="this.closest('.thumbnail-preview').classList.add('media-error')"></div>`
            : `<p class="thumbnail-empty">PNG/JPEGなどの画像ファイルを選ぶか、上の「サムネイルURL」に画像URL・Google Drive画像URLを入力すると、ここにプレビューが表示されます</p>`}
        </div>
        <label>共有リンク ${textarea(`posts.${index}.links`, post.links || "", 2)}${linkPreview(post.links)}</label>
        ${Array.isArray(post.returnHistory) && post.returnHistory.length ? `
          <details class="workflow-history">
            <summary>承認・差し戻し履歴（${post.returnHistory.length}件）</summary>
            ${post.returnHistory.slice().reverse().map((entry) => `<div><strong>${escapeHtml(entry.fromStage)} → ${escapeHtml(entry.toStage)}</strong><span>${escapeHtml(entry.returnedAt || "")} / ${escapeHtml(entry.decisionMakerName || "意思決定者")}</span><p>${escapeHtml(entry.reason || "")}</p><small>修正担当: ${escapeHtml(entry.revisionOwner || "未設定")} / 再提出: ${escapeHtml(entry.resubmittedAt || "未提出")}</small></div>`).join("")}
          </details>` : ""}
        <div class="card-actions">
          <button class="btn primary" data-mark-ready="${index}">保存して閉じる</button>
        </div>
      </div>
    </div>
  `;
}

function returnPostModal() {
  if (returnPostIndex === null || returnPostIndex === undefined) return "";
  const post = state.posts[returnPostIndex];
  if (!post) return "";
  const owners = [...new Set([post.owner, ...memberNames()].filter(Boolean))];
  return `
    <div class="modal-backdrop" data-action="close-return-modal">
      <div class="modal-panel workflow-return-modal" data-stop-propagation>
        <div class="modal-head"><div><span class="eyebrow">Decision maker</span><h3>確認中の投稿を差し戻す</h3></div><button class="btn icon-btn" data-action="close-return-modal">${icon("close")}<span>閉じる</span></button></div>
        <p class="panel-note">「${escapeHtml(post.title || "無題の投稿")}」の戻し先を、修正内容に合わせて選択してください。差し戻しは履歴に保存されます。</p>
        <div class="workflow-return-guides">
          <label><input type="radio" name="return-target" value="制作" checked><span><strong>制作へ戻す</strong><small>文章・デザイン・画像／動画・CTA・タグ・リンクなど制作物の修正</small></span></label>
          <label><input type="radio" name="return-target" value="企画"><span><strong>企画へ戻す</strong><small>目的・ターゲット・テーマ・KPI・方向性・実施判断の見直し</small></span></label>
        </div>
        <label>差し戻し理由（必須）<textarea id="returnReason" rows="4" placeholder="修正が必要な内容と判断理由を入力してください"></textarea></label>
        <label>修正担当者<select id="returnOwner">${owners.map((name) => `<option value="${escapeHtml(name)}" ${name === post.owner ? "selected" : ""}>${escapeHtml(name)}</option>`).join("")}</select></label>
        <div class="card-actions"><button class="btn" data-action="close-return-modal">キャンセル</button><button class="btn primary" data-action="confirm-return-post" data-post-index="${returnPostIndex}">${icon("undo")}<span>差し戻しを確定</span></button></div>
      </div>
    </div>`;
}

function stopPostModal() {
  if (stopPostIndex === null || stopPostIndex === undefined) return "";
  const post = state.posts[stopPostIndex];
  if (!post) return "";
  return `
    <div class="modal-backdrop" data-action="close-stop-modal">
      <div class="modal-panel workflow-return-modal" data-stop-propagation>
        <div class="modal-head"><div><span class="eyebrow">Feedback</span><h3>公開を停止する</h3></div><button class="btn icon-btn" data-action="close-stop-modal">${icon("close")}<span>閉じる</span></button></div>
        <p class="panel-note">「${escapeHtml(post.title || "無題の投稿")}」の公開を停止します。理由はフィードバックタブに記録されます。</p>
        <label>公開停止の理由（必須）<textarea id="stopReason" rows="4" placeholder="停止の理由と必要な修正を入力してください"></textarea></label>
        <div class="card-actions"><button class="btn" data-action="close-stop-modal">キャンセル</button><button class="btn primary" data-action="confirm-stop-publication" data-post-index="${stopPostIndex}">公開停止を確定</button></div>
      </div>
    </div>`;
}

/** 日時（ISO/日時ローカル）を「2026/07/14 14:32」表記へ。 */
function fmtCommentDateTime(value) {
  if (!value) return "-";
  const d = new Date(value);
  if (Number.isNaN(d.getTime())) return escapeHtml(String(value));
  const p = (n) => String(n).padStart(2, "0");
  return `${d.getFullYear()}/${p(d.getMonth() + 1)}/${p(d.getDate())} ${p(d.getHours())}:${p(d.getMinutes())}`;
}
/** 担当者の頭文字アバター。担当者マスター（members）と連携。未割り当ては薄色。 */
function ownerAvatar(name, extraClass = "") {
  const label = (name || "").trim();
  const initial = label ? label.replace(/\s/g, "").slice(0, 1) : "?";
  return `<span class="cmt-owner-avatar ${label ? "" : "is-empty"} ${extraClass}" title="${escapeHtml(label || "未割り当て")}">${escapeHtml(initial)}</span>`;
}

function commentsView() {
  const all = state.comments.filter((c) => dateWithin(c.receivedAt, commentDateFrom, commentDateTo));
  const active = all.filter((c) => !c.archived);
  const pending = active.filter((c) => commentStage(c) === "未対応").length;
  const doing = active.filter((c) => commentStage(c) === "対応中").length;
  const done = active.filter((c) => commentStage(c) === "対応済み").length;
  const dmCount = active.filter((c) => c.kind === "dm").length;
  const archivedCount = all.filter((c) => c.archived).length;

  // サブタブ（受信BOX / 対応中 / 対応済み / DM / アーカイブ）
  const subTabs = [
    { key: "inbox", label: "受信BOX", badge: active.filter((c) => c.kind !== "dm" && commentStage(c) === "未対応").length },
    { key: "doing", label: "対応中", badge: doing },
    { key: "done", label: "対応済み", badge: done },
    { key: "dm", label: "DM", badge: dmCount },
    { key: "archive", label: "アーカイブ", badge: archivedCount },
  ];

  // ビュー母集合
  const inView = all.filter((c) => {
    if (commentTabView === "archive") return c.archived;
    if (c.archived) return false;
    if (commentTabView === "dm") return c.kind === "dm";
    if (commentTabView === "doing") return c.kind !== "dm" && commentStage(c) === "対応中";
    if (commentTabView === "done") return c.kind !== "dm" && commentStage(c) === "対応済み";
    return c.kind !== "dm"; // inbox
  });

  // フィルタ
  const kw = commentSearch.trim().toLowerCase();
  let filtered = inView.filter((c) => {
    if (commentChannelFilter && c.channel !== commentChannelFilter) return false;
    if (commentStatusFilter && commentStage(c) !== commentStatusFilter) return false;
    if (commentOwnerFilter === "__none__") { if (c.owner) return false; }
    else if (commentOwnerFilter && c.owner !== commentOwnerFilter) return false;
    if (commentCampaignFilter && c.campaignId !== commentCampaignFilter) return false;
    if (kw && !`${c.user || ""} ${c.comment || ""} ${c.owner || ""}`.toLowerCase().includes(kw)) return false;
    return true;
  });

  // 並び替え
  const ts = (c) => new Date(c.receivedAt || 0).getTime() || 0;
  const prioRank = { 高: 3, 中: 2, 低: 1 };
  filtered = filtered.slice().sort((a, b) => {
    if (commentSort === "old") return ts(a) - ts(b);
    if (commentSort === "priority") return (prioRank[b.priority] || 0) - (prioRank[a.priority] || 0) || ts(b) - ts(a);
    return ts(b) - ts(a);
  });

  // ページング
  const perPage = 7;
  const totalPages = Math.max(1, Math.ceil(filtered.length / perPage));
  if (commentPage > totalPages) commentPage = totalPages;
  if (commentPage < 1) commentPage = 1;
  const startIdx = (commentPage - 1) * perPage;
  const pageItems = filtered.slice(startIdx, startIdx + perPage);

  // 右詳細パネルの選択（フィルタで消えたら先頭にフォールバック）
  let selected = selectedCommentId ? all.find((c) => c.id === selectedCommentId) : null;
  if (selected && selected.archived && commentTabView !== "archive") selected = null;

  const sortLabels = { new: "新しい順", old: "古い順", priority: "優先度順" };

  return `
    <section class="section ${activeTab === "comments" ? "active" : ""}" data-section="comments">
      <div class="cmt2-head">
        <div>
          <h2>コメント管理</h2>
          <p class="panel-note">コメントやDMを一元管理し、対応状況を可視化します。</p>
        </div>
        <div class="cmt2-head-actions">
          <label class="cmt2-period date-range-editor">${icon("calendar")}<span>期間：</span><input type="date" data-comment-date="from" value="${escapeHtml(commentDateFrom)}"><i>〜</i><input type="date" data-comment-date="to" value="${escapeHtml(commentDateTo)}"></label>
          <button class="btn cmt2-ghost" data-action="export-comments">${icon("download")}<span>エクスポート</span></button>
          <button class="btn primary" data-action="comments-report">${icon("spark")}<span>レポートを作成</span></button>
        </div>
      </div>

      <div class="cmt2-subtabs">
        ${subTabs.map((t) => `<button class="cmt2-subtab ${commentTabView === t.key ? "is-on" : ""}" data-comment-view="${t.key}">${escapeHtml(t.label)}${t.badge ? `<span class="cmt2-subtab-badge">${t.badge}</span>` : ""}</button>`).join("")}
      </div>

      <div class="cmt2-toolbar">
        <label class="cmt2-select">${select2(`__snsFilter`, commentChannelFilter, [{ value: "", label: "すべてのSNS" }, ...commentChannelOrder.map((n) => ({ value: n, label: n }))], "data-comment-channel")}</label>
        <label class="cmt2-select">${select2(`__statusFilter`, commentStatusFilter, [{ value: "", label: "すべてのステータス" }, ...commentStatusOptions.map((s) => ({ value: s, label: s }))], "data-comment-status-filter")}</label>
        <label class="cmt2-select">${select2(`__ownerFilter`, commentOwnerFilter, [{ value: "", label: "すべての担当者" }, ...memberNames().map((n) => ({ value: n, label: n })), { value: "__none__", label: "未割り当て" }], "data-comment-owner-filter")}</label>
        <label class="cmt2-select">${select2(`__campaignFilter`, commentCampaignFilter, [{ value: "", label: "すべてのキャンペーン" }, ...(state.campaigns || []).map((c) => ({ value: c.id, label: c.name }))], "data-comment-campaign-filter")}</label>
        <button class="cmt2-tool-btn" data-action="add-comment" title="コメントを追加">${icon("plus")}<span>追加</span></button>
        <div class="cmt2-toolbar-right">
          <label class="cmt2-search">${icon("search")}<input type="search" placeholder="コメント内容を検索" value="${escapeHtml(commentSearch)}" data-comment-search></label>
          <label class="cmt2-select cmt2-sort">${select2(`__sort`, commentSort, Object.entries(sortLabels).map(([v, l]) => ({ value: v, label: l })), "data-comment-sort")}</label>
          <div class="cmt2-layout-toggle">
            <button class="${commentLayout === "list" ? "is-on" : ""}" data-comment-layout="list" title="リスト表示">${icon("segments")}</button>
            <button class="${commentLayout === "grid" ? "is-on" : ""}" data-comment-layout="grid" title="カード表示">${icon("dashboard")}</button>
          </div>
        </div>
      </div>

      <div class="cmt2-grid ${selected ? "has-detail" : ""}">
        ${commentSummaryAside(active, { pending, doing, done, dmCount })}
        <div class="cmt2-center">
          ${filtered.length === 0
            ? `<div class="cmt2-empty">${icon("inbox")}<p>該当するコメントがありません。</p></div>`
            : commentLayout === "grid"
              ? `<div class="cmt2-cardgrid">${pageItems.map((c) => commentGridCard(c, selected)).join("")}</div>`
              : commentListTable(pageItems, selected)}
          ${filtered.length ? commentPagination(filtered.length, startIdx, pageItems.length, totalPages) : ""}
        </div>
        ${selected ? commentDetailPanel(selected) : ""}
      </div>
    </section>
  `;
}

/** ツールバー用の素のselect（data-path非依存。ラベルを付けたいときに使う） */
function select2(name, value, options, attrs = "") {
  return `<select ${attrs}>${options.map((o) => `<option value="${escapeHtml(o.value)}" ${o.value === value ? "selected" : ""}>${escapeHtml(o.label)}</option>`).join("")}</select>`;
}

/** 左「受信サマリー」。SNS別/ステータス別/担当者別を実データから集計（相互性の可視化）。 */
function commentSummaryAside(active, agg) {
  const bySns = commentChannelOrder.map((name) => ({ name, count: active.filter((c) => c.channel === name).length }));
  const byStatus = [
    { label: "未対応", tone: "red", count: agg.pending },
    { label: "対応中", tone: "orange", count: agg.doing },
    { label: "対応済み", tone: "green", count: agg.done },
  ];
  const ownerMap = new Map();
  active.forEach((c) => { const k = c.owner || "__none__"; ownerMap.set(k, (ownerMap.get(k) || 0) + 1); });
  const byOwner = [...ownerMap.entries()]
    .sort((a, b) => (a[0] === "__none__" ? 1 : b[0] === "__none__" ? -1 : b[1] - a[1]))
    .map(([name, count]) => ({ name: name === "__none__" ? "未割り当て" : name, count, empty: name === "__none__" }));
  return `
    <aside class="cmt2-aside">
      <div class="cmt2-aside-card">
        <h4>受信サマリー（今週）</h4>
        <div class="cmt2-summary-stats">
          <div><strong class="tone-red">${agg.pending}</strong><small>未対応</small></div>
          <div><strong class="tone-orange">${agg.doing}</strong><small>対応中</small></div>
          <div><strong class="tone-blue">${agg.dmCount}</strong><small>DM</small></div>
        </div>
        <div class="cmt2-summary-done">対応済み <b>${agg.done}</b> 件</div>
      </div>
      <div class="cmt2-aside-card">
        <h5>SNS別内訳</h5>
        <ul class="cmt2-breakdown">
          ${bySns.map((s) => { const src = socialIcon(s.name); return `<li><span class="cmt2-bd-label">${src ? `<img src="${src}" alt="">` : icon("message")}${escapeHtml(s.name)}</span><b>${s.count}</b></li>`; }).join("")}
        </ul>
      </div>
      <div class="cmt2-aside-card">
        <h5>ステータス別</h5>
        <ul class="cmt2-breakdown">
          ${byStatus.map((s) => `<li><span class="cmt2-bd-label"><i class="cmt2-dot tone-${s.tone}"></i>${escapeHtml(s.label)}</span><b>${s.count}</b></li>`).join("")}
        </ul>
      </div>
      <div class="cmt2-aside-card">
        <h5>担当者別</h5>
        <ul class="cmt2-breakdown">
          ${byOwner.map((o) => `<li><span class="cmt2-bd-label">${ownerAvatar(o.empty ? "" : o.name)}${escapeHtml(o.name)}</span><b>${o.count}</b></li>`).join("")}
        </ul>
      </div>
    </aside>
  `;
}

/** 中央リスト（テーブル型）。参考UIの3列（コメント / 投稿・受信日時 / ステータス・担当者）。 */
function commentListTable(items, selected) {
  return `
    <div class="cmt2-list">
      <div class="cmt2-list-head">
        <span class="cmt2-col-check"><input type="checkbox" disabled></span>
        <span class="cmt2-col-main">コメント</span>
        <span class="cmt2-col-date">投稿・受信日時</span>
        <span class="cmt2-col-status">ステータス / 担当者</span>
      </div>
      ${items.map((c) => commentRow(c, selected && selected.id === c.id)).join("")}
    </div>
  `;
}

function commentRow(comment, isActive) {
  const iconSrc = socialIcon(comment.channel);
  const stage = commentStage(comment);
  const stTone = commentStatusTone(comment.status);
  const post = comment.postId ? state.posts.find((p) => p.id === comment.postId) : null;
  return `
    <div class="cmt2-row ${isActive ? "is-active" : ""}" data-select-comment="${escapeHtml(comment.id)}">
      <span class="cmt2-col-check"><input type="checkbox" data-stop-propagation></span>
      <div class="cmt2-col-main">
        <span class="cmt2-avatar">${iconSrc ? `<img src="${iconSrc}" alt="${escapeHtml(comment.channel || "")}">` : escapeHtml((comment.user || "?").slice(0, 1))}</span>
        <div class="cmt2-main-body">
          <div class="cmt2-user-line"><strong>${escapeHtml(comment.user || "(匿名)")}</strong>${comment.isFollower ? `<span class="cmt2-follower">フォロワー</span>` : ""}${comment.sentiment === "商談可能性" ? `<span class="cmt2-deal">商談</span>` : ""}</div>
          <p class="cmt2-text">${escapeHtml(comment.comment || "")}</p>
          ${post ? `<span class="cmt2-post-ref">投稿：${escapeHtml(post.title || "(無題)")}</span>` : `<span class="cmt2-post-ref muted">投稿に未ひも付け</span>`}
        </div>
      </div>
      <div class="cmt2-col-date">${fmtCommentDateTime(comment.receivedAt)}</div>
      <div class="cmt2-col-status">
        <span class="cmt2-status-pill tone-${stTone}">${escapeHtml(stage)}</span>
        <span class="cmt2-row-owner">${ownerAvatar(comment.owner)}</span>
        <button class="cmt2-row-menu" data-comment-menu="${escapeHtml(comment.id)}" data-stop-propagation title="操作">⋯</button>
        ${openCommentMenuId === comment.id ? commentRowMenu(comment) : ""}
      </div>
    </div>
  `;
}

function commentRowMenu(comment) {
  return `
    <div class="cmt2-menu" data-stop-propagation>
      <button data-comment-to-idea-id="${escapeHtml(comment.id)}">${icon("lightbulb")}投稿案化</button>
      <button data-comment-archive="${escapeHtml(comment.id)}">${icon("archive")}${comment.archived ? "受信BOXへ戻す" : "アーカイブ"}</button>
      <button class="danger" data-comment-remove-id="${escapeHtml(comment.id)}">${icon("ban")}削除</button>
    </div>
  `;
}

/** カード表示（レイアウト切替のグリッド） */
function commentGridCard(comment, selected) {
  const iconSrc = socialIcon(comment.channel);
  const stage = commentStage(comment);
  const stTone = commentStatusTone(comment.status);
  const post = comment.postId ? state.posts.find((p) => p.id === comment.postId) : null;
  return `
    <article class="cmt2-card ${selected && selected.id === comment.id ? "is-active" : ""}" data-select-comment="${escapeHtml(comment.id)}">
      <div class="cmt2-card-head">
        <span class="cmt2-avatar">${iconSrc ? `<img src="${iconSrc}" alt="">` : escapeHtml((comment.user || "?").slice(0, 1))}</span>
        <div class="cmt2-user-line"><strong>${escapeHtml(comment.user || "(匿名)")}</strong>${comment.isFollower ? `<span class="cmt2-follower">フォロワー</span>` : ""}</div>
        <span class="cmt2-status-pill tone-${stTone}">${escapeHtml(stage)}</span>
      </div>
      <p class="cmt2-text">${escapeHtml(comment.comment || "")}</p>
      <div class="cmt2-card-foot">
        ${post ? `<span class="cmt2-post-ref">投稿：${escapeHtml(post.title || "(無題)")}</span>` : `<span class="cmt2-post-ref muted">未ひも付け</span>`}
        <span class="cmt2-card-meta">${ownerAvatar(comment.owner)}<small>${fmtCommentDateTime(comment.receivedAt)}</small></span>
      </div>
    </article>
  `;
}

function commentPagination(total, startIdx, shown, totalPages) {
  const from = total === 0 ? 0 : startIdx + 1;
  const to = startIdx + shown;
  const pages = [];
  for (let i = 1; i <= totalPages; i++) pages.push(i);
  return `
    <div class="cmt2-pagination">
      <span class="cmt2-page-count">${from}-${to} / ${total}件</span>
      <div class="cmt2-page-nav">
        <button class="cmt2-page-btn" data-comment-page="${commentPage - 1}" ${commentPage <= 1 ? "disabled" : ""}>${icon("chevron")}</button>
        ${pages.map((p) => `<button class="cmt2-page-btn ${p === commentPage ? "is-on" : ""}" data-comment-page="${p}">${p}</button>`).join("")}
        <button class="cmt2-page-btn cmt2-page-next" data-comment-page="${commentPage + 1}" ${commentPage >= totalPages ? "disabled" : ""}>${icon("chevron")}</button>
      </div>
    </div>
  `;
}

