/** 今日の日付ラベル（YYYY/MM/DD (曜)）。競合投稿入力の「入力日」表示に使う。 */
function cmpTodayLabel() {
  const d = new Date();
  const wd = ["日", "月", "火", "水", "木", "金", "土"];
  return `${d.getFullYear()}/${String(d.getMonth() + 1).padStart(2, "0")}/${String(d.getDate()).padStart(2, "0")} (${wd[d.getDay()]})`;
}

/** 競合企業管理の期間プリセット→日付レンジ。「今週追加企業」KPIと期間表示に使う。 */
function cmpPeriodRange(preset = cmpPeriod) {
  const now = new Date();
  const startOf = (d) => { const x = new Date(d); x.setHours(0, 0, 0, 0); return x; };
  const endOf = (d) => { const x = new Date(d); x.setHours(23, 59, 59, 999); return x; };
  let start; let end; let addedLabel;
  if (preset === "先週") {
    const mon = startOf(now); mon.setDate(mon.getDate() - ((mon.getDay() + 6) % 7) - 7);
    start = mon; end = endOf(new Date(mon.getFullYear(), mon.getMonth(), mon.getDate() + 6)); addedLabel = "先週追加企業";
  } else if (preset === "今月") {
    start = startOf(new Date(now.getFullYear(), now.getMonth(), 1));
    end = endOf(new Date(now.getFullYear(), now.getMonth() + 1, 0)); addedLabel = "今月追加企業";
  } else if (preset === "過去30日") {
    start = startOf(new Date(now.getFullYear(), now.getMonth(), now.getDate() - 29));
    end = endOf(now); addedLabel = "30日間の追加";
  } else {
    const mon = startOf(now); mon.setDate(mon.getDate() - ((mon.getDay() + 6) % 7));
    start = mon; end = endOf(new Date(mon.getFullYear(), mon.getMonth(), mon.getDate() + 6)); addedLabel = "今週追加企業";
  }
  const wd = ["日", "月", "火", "水", "木", "金", "土"];
  const fmt = (d) => `${d.getFullYear()}/${String(d.getMonth() + 1).padStart(2, "0")}/${String(d.getDate()).padStart(2, "0")} (${wd[d.getDay()]})`;
  return { label: `${fmt(start)} 〜 ${fmt(end)}`, start, end, addedLabel };
}

/** items のうち tsKey（ISO日時）が [start,end] に入る件数。 */
function cmpAddedInRange(items, tsKey, start, end) {
  const s = start.getTime(); const e = end.getTime();
  return items.filter((x) => { const t = Date.parse(x[tsKey]); return !Number.isNaN(t) && t >= s && t <= e; }).length;
}

/** 競合企業管理サブタブ：フィルタ + KPI + 企業テーブル + 使い方/データ連携フッター。 */
function competitorCompaniesSubView() {
  const all = state.competitors;
  const range = cmpPeriodRange();
  const industries = [...new Set(all.map((c) => c.industry).filter(Boolean))];
  const kw = cmpSearch.trim().toLowerCase();
  const filtered = all.map((c, index) => ({ c, index })).filter(({ c }) => (
    (!kw || (c.name || "").toLowerCase().includes(kw))
    && (!cmpIndustryFilter || c.industry === cmpIndustryFilter)
    && (!cmpPriorityFilter || c.priority === cmpPriorityFilter)
    && (!cmpMonitorFilter || (cmpMonitorFilter === "on" ? c.monitoring : !c.monitoring))
    && (() => { const t = Date.parse(c.createdAt); return !Number.isNaN(t) && t >= range.start.getTime() && t <= range.end.getTime(); })()
  ));
  const total = filtered.length;
  const totalPages = Math.max(1, Math.ceil(total / cmpPageSize));
  const page = Math.min(Math.max(1, cmpPage), totalPages);
  const start = (page - 1) * cmpPageSize;
  const pageRows = filtered.slice(start, start + cmpPageSize);

  const snsCount = (c) => CMP_SNS.reduce((n, s) => n + (c.sns && c.sns[s.key] ? 1 : 0), 0);
  const avgSns = all.length ? Math.round(all.reduce((n, c) => n + snsCount(c), 0) / all.length * 10) / 10 : 0;
  const addedInPeriod = cmpAddedInRange(all, "createdAt", range.start, range.end);
  const kpis = [
    { icon: "building", tone: "blue", value: all.length, unit: "社", label: "管理競合企業" },
    { icon: "eye", tone: "green", value: all.filter((c) => c.monitoring).length, unit: "社", label: "監視中の企業" },
    { icon: "flag", tone: "red", value: all.filter((c) => c.priority === "P1").length, unit: "社", label: "高優先度企業（P1）" },
    { icon: "pie", tone: "violet", value: avgSns.toFixed(1), unit: "チャネル", label: "平均監視SNS数" },
    { icon: "spark", tone: "green", value: addedInPeriod, unit: "社", label: range.addedLabel, badge: "NEW" },
    { icon: "target", tone: "violet", value: all.filter((c) => c.benchmark).length, unit: "社", label: "ベンチマーク企業" },
  ];
  const kpiCards = kpis.map((k) => `
    <article class="cmp-kpi cmp-kpi--plain">
      <div class="cmp-kpi-top">
        <span class="cmp-kpi-ico ${k.tone}">${k.badge ? `<b class="cmp-kpi-badge">${k.badge}</b>` : icon(k.icon)}</span>
        <span class="cmp-kpi-label">${escapeHtml(k.label)}</span>
      </div>
      <div class="cmp-kpi-value"><strong>${k.value}</strong><small>${escapeHtml(k.unit)}</small></div>
    </article>
  `).join("");

  const prioBadge = (p) => `<span class="cmp-prio p-${p}">${escapeHtml(p)}</span>`;
  const snsHead = CMP_SNS.map((s) => `<th class="cmp-sns-col" title="${escapeHtml(s.label)}">${socialIconData[s.key] ? `<img src="${socialIconData[s.key]}" alt="${escapeHtml(s.label)}">` : escapeHtml(s.label)}</th>`).join("");

  const rows = pageRows.map(({ c, index }) => `
    <tr>
      <td class="cmp-td-name">${escapeHtml(c.name)}</td>
      <td class="cmp-td-logo">${companyLogo(c)}</td>
      <td class="cmp-td-industry">${escapeHtml(c.industry || "-")}</td>
      <td class="cmp-td-url">${c.url ? `<a href="${escapeHtml(c.url)}" target="_blank" rel="noopener">${escapeHtml(c.url)}</a>` : "-"}</td>
      ${CMP_SNS.map((s) => `<td class="cmp-sns-cell">${c.sns && c.sns[s.key] ? `<span class="cmp-sns-on">${icon("check")}</span>` : `<span class="cmp-sns-off">—</span>`}</td>`).join("")}
      <td class="cmp-td-prio">${prioBadge(c.priority)}</td>
      <td class="cmp-td-owner">${escapeHtml(c.owner || "-")}</td>
      <td class="cmp-td-monitor"><button class="cmp-switch ${c.monitoring ? "on" : ""}" data-cmp-toggle-monitor="${index}" role="switch" aria-checked="${c.monitoring}"><span></span></button></td>
      <td class="cmp-td-memo">${escapeHtml(c.memo || "-")}</td>
      <td class="cmp-td-ops">
        <button class="cmp-row-btn" data-cmp-edit="${index}" aria-label="編集">${icon("pencil")}</button>
        <button class="cmp-row-btn danger" data-cmp-delete="${index}" aria-label="削除">${icon("archive")}</button>
      </td>
    </tr>`).join("");

  const pager = totalPages > 1 ? `
    <div class="cmp-pager">
      <button class="cmp-pg-btn" data-cmp-page="${page - 1}" ${page === 1 ? "disabled" : ""}>${icon("chevron")}</button>
      ${Array.from({ length: totalPages }, (_, i) => i + 1).map((n) => `<button class="cmp-pg-btn ${n === page ? "active" : ""}" data-cmp-page="${n}">${n}</button>`).join("")}
      <button class="cmp-pg-btn" data-cmp-page="${page + 1}" ${page === totalPages ? "disabled" : ""}>${icon("chevron")}</button>
    </div>` : "";

  return `
    <div class="cmp-companies">
      <div class="cmp-filters">
        <label class="cmp-search">${icon("search")}<input type="search" placeholder="企業名で検索" value="${escapeHtml(cmpSearch)}" data-cmp-search></label>
        <label class="cmp-filter"><span>業界：</span><select data-cmp-filter="industry"><option value="">すべて</option>${industries.map((v) => `<option value="${escapeHtml(v)}" ${cmpIndustryFilter === v ? "selected" : ""}>${escapeHtml(v)}</option>`).join("")}</select></label>
        <label class="cmp-filter"><span>優先度：</span><select data-cmp-filter="priority"><option value="">すべて</option>${["P1", "P2", "P3"].map((v) => `<option value="${v}" ${cmpPriorityFilter === v ? "selected" : ""}>${v}</option>`).join("")}</select></label>
        <label class="cmp-filter"><span>監視ステータス：</span><select data-cmp-filter="monitor"><option value="">すべて</option><option value="on" ${cmpMonitorFilter === "on" ? "selected" : ""}>監視中</option><option value="off" ${cmpMonitorFilter === "off" ? "selected" : ""}>停止中</option></select></label>
        <div class="cmp-filters-right">
          <label class="cmp-filter"><span>表示件数：</span><select data-cmp-pagesize>${[10, 20, 50].map((n) => `<option value="${n}" ${cmpPageSize === n ? "selected" : ""}>${n}件</option>`).join("")}</select></label>
          <div class="cmp-viewtoggle">
            <button class="${cmpView === "grid" ? "active" : ""}" data-cmp-view="grid" aria-label="グリッド表示">${icon("dashboard")}</button>
            <button class="${cmpView === "table" ? "active" : ""}" data-cmp-view="table" aria-label="テーブル表示">${icon("segments")}</button>
          </div>
        </div>
      </div>

      <div class="cmp-kpi-row cmp-kpi-row--companies">${kpiCards}</div>

      <div class="cmp-table-wrap">
        <table class="cmp-table">
          <thead>
            <tr class="cmp-thead-group">
              <th rowspan="2">企業名</th><th rowspan="2">ロゴ</th><th rowspan="2">業界</th><th rowspan="2">公式サイトURL</th>
              <th colspan="${CMP_SNS.length}" class="cmp-sns-group">監視対象SNS</th>
              <th rowspan="2">優先度</th><th rowspan="2">担当者</th><th rowspan="2">監視ステータス</th><th rowspan="2">メモ</th><th rowspan="2">操作</th>
            </tr>
            <tr class="cmp-thead-sns">${snsHead}</tr>
          </thead>
          <tbody>${rows || `<tr><td colspan="${9 + CMP_SNS.length}" class="cmp-empty">条件に一致する企業がありません</td></tr>`}</tbody>
        </table>
      </div>

      <div class="cmp-table-foot">
        <span class="cmp-count">${total ? `${start + 1}-${Math.min(start + cmpPageSize, total)} / ${total}件` : "0件"}</span>
        ${pager}
      </div>

      <div class="cmp-guide">
        <div class="cmp-guide-col">
          <h4>${icon("info")}競合企業管理の使い方</h4>
          <ul>
            <li>${icon("check")}ここに登録した企業は「競合投稿入力」で選択できます。</li>
            <li>${icon("check")}監視対象SNSをオンにすると、そのチャネルの競合投稿を収集・分析しやすくなります。</li>
            <li>${icon("check")}優先度（P1〜P3）を設定すると、ダッシュボードやベンチマークで上位表示されます。</li>
            <li>${icon("check")}メモはチーム内で共有されます。定期的に見直しましょう。</li>
          </ul>
        </div>
        <div class="cmp-guide-col">
          <h4>データ連携</h4>
          <div class="cmp-flow">
            <span class="cmp-flow-node blue">${icon("building")}競合企業管理</span>${icon("chevron")}
            <span class="cmp-flow-node green">${icon("doc")}競合投稿入力</span>${icon("chevron")}
            <span class="cmp-flow-node violet">${icon("segments")}競合分析</span>${icon("chevron")}
            <span class="cmp-flow-node amber">${icon("compare")}ベンチマーク</span>${icon("chevron")}
            <span class="cmp-flow-node red">${icon("lightbulb")}改善管理へ</span>
          </div>
          <p class="cmp-flow-note">※ 編集内容はリアルタイムで全タブに反映されます</p>
        </div>
      </div>
    </div>
  `;
}

/** 企業ロゴ：logo（data URI/URL）があれば画像、無ければ頭文字プレースホルダ。 */
function companyLogo(c) {
  if (c.logo) return `<span class="cmp-logo"><img src="${escapeHtml(c.logo)}" alt="${escapeHtml(c.name)}"></span>`;
  const ch = (c.name || "?").trim().charAt(0);
  return `<span class="cmp-logo cmp-logo--ph">${escapeHtml(ch)}</span>`;
}

/** 企業の追加・編集モーダル。 */
function competitorEditModal() {
  const i = cmpEditIndex;
  const c = state.competitors[i];
  if (!c) return "";
  const isNew = !c.name;
  return `
    <div class="modal-backdrop" data-cmp-modal-close>
      <div class="modal-panel cmp-modal" data-stop-propagation>
        <div class="modal-head">
          <h3>${isNew ? "競合企業を追加" : "競合企業を編集"}</h3>
          <button class="btn icon-btn" data-cmp-modal-close>${icon("close")}<span>閉じる</span></button>
        </div>
        <div class="fields two">
          <label>企業名 ${input(`competitors.${i}.name`, c.name)}</label>
          <label>業界 ${input(`competitors.${i}.industry`, c.industry)}</label>
        </div>
        <div class="fields two">
          <label>公式サイトURL ${input(`competitors.${i}.url`, c.url)}</label>
          <label>担当者 ${input(`competitors.${i}.owner`, c.owner)}</label>
        </div>
        <div class="fields two">
          <label>優先度 ${select(`competitors.${i}.priority`, c.priority, ["P1", "P2", "P3"])}</label>
          <div class="cmp-logo-field">
            <span class="cmp-field-label">ロゴ画像（PNG / JPG / スクリーンショット）</span>
            <div class="cmp-logo-row">
              <label class="cmp-logo-drop ${c.logo ? "" : "empty"}" title="${c.logo ? "画像を変更" : "画像をアップロード"}">
                ${c.logo ? `<img src="${escapeHtml(c.logo)}" alt="${escapeHtml(c.name || "")}">` : icon("upload")}
                <input type="file" accept="image/png,image/jpeg,image/webp" data-cmp-logo-file="${i}" hidden>
              </label>
              <div class="cmp-logo-help">
                <p>${c.logo ? "クリックで画像を差し替え" : "クリックしてロゴ画像を選択"}</p>
                ${c.logo
                  ? `<button type="button" class="btn small" data-cmp-logo-clear="${i}">${icon("close")}<span>削除</span></button>`
                  : `<span class="panel-note">スクショやPNGをそのまま登録できます</span>`}
              </div>
            </div>
          </div>
        </div>
        <label class="cmp-modal-sns-label">監視対象SNS</label>
        <div class="cmp-modal-sns">
          ${CMP_SNS.map((s) => `<button type="button" class="cmp-sns-chip ${c.sns && c.sns[s.key] ? "on" : ""}" data-cmp-sns-toggle="${i}:${s.key}">${socialIconData[s.key] ? `<img src="${socialIconData[s.key]}" alt="">` : ""}${escapeHtml(s.label)}</button>`).join("")}
        </div>
        <div class="fields two cmp-modal-toggles">
          <label class="cmp-modal-toggle"><span>監視ステータス</span><button type="button" class="cmp-switch ${c.monitoring ? "on" : ""}" data-cmp-modal-monitor="${i}" role="switch" aria-checked="${c.monitoring}"><span></span></button></label>
          <label class="cmp-modal-toggle"><span>ベンチマーク対象</span><button type="button" class="cmp-switch ${c.benchmark ? "on" : ""}" data-cmp-modal-bench="${i}" role="switch" aria-checked="${c.benchmark}"><span></span></button></label>
        </div>
        <label>メモ ${textarea(`competitors.${i}.memo`, c.memo, 2)}</label>
        <div class="cmp-modal-foot">
          ${isNew ? "" : `<button class="btn danger" data-cmp-delete="${i}">${icon("archive")}<span>削除</span></button>`}
          <button class="btn primary" data-cmp-modal-close>${icon("check")}<span>保存して閉じる</span></button>
        </div>
      </div>
    </div>
  `;
}

/** 競合投稿入力サブタブ。state.competitorDraft をdata-path方式で編集（自動保存）。保存で competitorPosts へ確定。 */
function competitorInputSubView() {
  const d = state.competitorDraft || (state.competitorDraft = blankCompetitorPost());
  const badge = (n) => `<span class="cpi-badge">${n}</span>`;
  const num = (path, val) => `<input type="number" class="cpi-num" data-path="${path}" value="${val ? escapeHtml(val) : ""}" placeholder="0">`;
  const countArea = (path, val, rows, ph) => `
    <div class="cpi-ta-wrap">
      <textarea data-path="${path}" maxlength="300" rows="${rows}" placeholder="${escapeHtml(ph)}">${escapeHtml(val || "")}</textarea>
      <span class="cpi-count">${(val || "").length} / 300</span>
    </div>`;

  const inputChannels = [
    { key: "instagram", label: "Instagram" }, { key: "x", label: "X (Twitter)" }, { key: "tiktok", label: "TikTok" },
    { key: "youtube", label: "YouTube" }, { key: "facebook", label: "Facebook" }, { key: "linkedin", label: "LinkedIn" },
    { key: "threads", label: "Threads" }, { key: "note", label: "note" }, { key: "other", label: "その他" },
  ];
  const selectedCompany = state.competitors.find((c) => c.id === d.competitorId);
  const companyOpts = [{ value: "", label: "競合企業を選択" }, ...state.competitors.map((c) => ({ value: c.id, label: c.name }))];
  const themeChip = (v, opts, path, ph) => select(path, v, [{ value: "", label: ph }, ...opts.map((o) => ({ value: o, label: o }))]);

  const stars = Array.from({ length: 5 }, (_, i) => `<button type="button" class="cpi-star ${i < d.rating ? "on" : ""}" data-cpi-rating="${i + 1}">${icon("star")}</button>`).join("");

  return `
    <div class="cpi">
      <div class="cpi-grid">
        <!-- 左カラム -->
        <div class="cpi-col">
          <!-- ① 基本情報 -->
          <section class="cpi-panel">
            <div class="cpi-panel-head">${badge(1)}<h3>基本情報</h3></div>
            <div class="cpi-field">
              <div class="cpi-label-row"><label>競合企業 <em>*</em></label><button type="button" class="cpi-link" data-action="cpi-new-company">新しい企業追加</button></div>
              <div class="cpi-company">${companyLogo(selectedCompany || { name: "" })}${select("competitorDraft.competitorId", d.competitorId, companyOpts)}</div>
            </div>
            <div class="cpi-field">
              <label>SNSチャンネル <em>*</em> <span class="cpi-hint">（複数選択可）</span></label>
              <div class="cpi-channels">
                ${inputChannels.map((ch) => `
                  <button type="button" class="cpi-chan ${d.channels.includes(ch.key) ? "on" : ""}" data-cpi-channel="${ch.key}">
                    <span class="cpi-chan-ico">${socialIconData[ch.key] ? `<img src="${socialIconData[ch.key]}" alt="">` : "···"}</span>
                    <span class="cpi-chan-label">${escapeHtml(ch.label)}</span>
                  </button>`).join("")}
              </div>
            </div>
            <div class="cpi-row3">
              <div class="cpi-field"><label>投稿日 <em>*</em></label>${input("competitorDraft.postDate", d.postDate, "date")}</div>
              <div class="cpi-field"><label>投稿時間</label>${input("competitorDraft.postTime", d.postTime, "time")}</div>
              <div class="cpi-field"><label>投稿URL <em>*</em></label><div class="cpi-url">${icon("link")}<input type="url" data-path="competitorDraft.url" value="${escapeHtml(d.url)}" placeholder="https://..."></div></div>
            </div>
            <div class="cpi-row3">
              <div class="cpi-field"><label>テーマ <em>*</em></label>${themeChip(d.theme, competitorThemeOptions, "competitorDraft.theme", "選択")}</div>
              <div class="cpi-field"><label>形式 <em>*</em></label>${themeChip(d.format, competitorFormatOptions, "competitorDraft.format", "選択")}</div>
              <div class="cpi-field"><label>キャンペーン <span class="cpi-hint">（任意）</span></label><input type="text" data-path="competitorDraft.campaign" value="${escapeHtml(d.campaign)}" placeholder="キャンペーン名"></div>
            </div>
            <div class="cpi-row2">
              <div class="cpi-field"><label>担当者 <span class="cpi-hint">（任意）</span></label><input type="text" data-path="competitorDraft.owner" value="${escapeHtml(d.owner)}" placeholder="管理者"></div>
              <div class="cpi-field"><label>タグ <span class="cpi-hint">（任意）</span></label>
                <div class="cpi-tags">
                  ${d.tags.map((t, ti) => `<span class="cpi-tag">#${escapeHtml(t)}<button type="button" data-cpi-tag-remove="${ti}">${icon("close")}</button></span>`).join("")}
                  <input type="text" class="cpi-tag-input" placeholder="＋ タグを追加" data-cpi-tag-input>
                </div>
              </div>
            </div>
            <div class="cpi-field"><label>メモ <span class="cpi-hint">（任意）</span></label>${countArea("competitorDraft.memo", d.memo, 2, "投稿の補足メモ")}</div>
          </section>

          <!-- ④ 投稿スクリーンショット -->
          <section class="cpi-panel">
            <div class="cpi-panel-head">${badge(4)}<h3>投稿スクリーンショット <em>*</em></h3></div>
            <div class="cpi-shots">
              ${d.screenshots.map((src, si) => `
                <div class="cpi-shot">
                  <img src="${escapeHtml(src)}" alt="">
                  <button type="button" class="cpi-shot-del" data-cpi-shot-remove="${si}">${icon("close")}</button>
                  <span class="cpi-shot-no">${si + 1}</span>
                </div>`).join("")}
              ${d.screenshots.length < 10 ? `
                <label class="cpi-shot-add">${icon("plus")}<span>画像を追加</span><small>（最大10枚まで）</small>
                  <input type="file" accept="image/png,image/jpeg,image/webp" data-cpi-shot-file hidden>
                </label>` : ""}
            </div>
            <div class="cpi-shot-foot">
              <span class="cpi-shot-name">ファイル名：${d.screenshots.length ? `${d.screenshots.length}枚の画像` : "未登録"}</span>
              <label class="cmp-btn-ghost cpi-shot-change">${icon("upload")}<span>ファイルを変更</span><input type="file" accept="image/png,image/jpeg,image/webp" data-cpi-shot-file hidden></label>
            </div>
          </section>
        </div>

        <!-- 右カラム -->
        <div class="cpi-col">
          <!-- ② 公開されている数値 -->
          <section class="cpi-panel">
            <div class="cpi-panel-head">${badge(2)}<h3>公開されている数値 <span class="cpi-sub">（取得できる数値のみ）</span></h3></div>
            <div class="cpi-metrics">
              <div class="cpi-metric-group">
                <h4 class="cpi-group-title">エンゲージメント</h4>
                <div class="cpi-metric-row"><label>いいね数 <em>*</em></label>${num("competitorDraft.likes", d.likes)}<span class="cpi-unit">件</span></div>
                <div class="cpi-metric-row"><label>コメント数 <em>*</em></label>${num("competitorDraft.comments", d.comments)}<span class="cpi-unit">件</span></div>
                <div class="cpi-metric-row"><label>シェア数／リポスト数 <em>*</em></label>${num("competitorDraft.shares", d.shares)}<span class="cpi-unit">件</span></div>
                <div class="cpi-metric-row disabled"><label>保存数</label><div class="cpi-num-off">—</div><span class="cpi-unit">件（取得不可）</span></div>
                <div class="cpi-metric-row disabled"><label>インプレッション数</label><div class="cpi-num-off">—</div><span class="cpi-unit">（取得不可）</span></div>
                <div class="cpi-metric-row disabled"><label>リーチ数</label><div class="cpi-num-off">—</div><span class="cpi-unit">（取得不可）</span></div>
              </div>
              <div class="cpi-metric-group">
                <h4 class="cpi-group-title">再生・フォロワー</h4>
                <div class="cpi-metric-row"><label>再生数／表示数 <em>*</em></label>${num("competitorDraft.plays", d.plays)}<span class="cpi-unit">回</span></div>
                <div class="cpi-metric-row"><label>フォロワー数 <span class="cpi-hint">（任意）</span></label>${num("competitorDraft.followers", d.followers)}<span class="cpi-unit">人</span></div>
                <div class="cpi-note-box">${icon("info")}<p>保存数、CTR、CV、リーチ、インプレッションなどは競合では取得できないため、入力不要です。</p></div>
              </div>
            </div>
          </section>

          <div class="cpi-lower">
            <!-- ③ コンテンツ分析 -->
            <section class="cpi-panel">
              <div class="cpi-panel-head">${badge(3)}<h3>コンテンツ分析 <span class="cpi-sub">（主観的な分析を記録）</span></h3></div>
              <div class="cpi-field"><label>投稿の目的 <em>*</em></label>${themeChip(d.purpose, competitorPurposeOptions, "competitorDraft.purpose", "選択")}</div>
              <div class="cpi-field"><label>ターゲット層（推定）</label><input type="text" data-path="competitorDraft.target" value="${escapeHtml(d.target)}" placeholder="例：20〜30代のキャリア形成中の人"></div>
              <div class="cpi-field"><label>フック（最初の一文）</label><input type="text" data-path="competitorDraft.hook" value="${escapeHtml(d.hook)}" placeholder="投稿の書き出し"></div>
              <div class="cpi-field"><label>CTA（行動喚起）</label><input type="text" data-path="competitorDraft.ctaText" value="${escapeHtml(d.ctaText)}" placeholder="例：プロフィールのリンクから"></div>
              <div class="cpi-field"><label>成功要因（なぜ伸びたと考えるか）</label>${countArea("competitorDraft.successFactor", d.successFactor, 2, "伸びた理由の仮説")}</div>
              <div class="cpi-field"><label>改善アイデア（自社に活かせること）</label>${countArea("competitorDraft.improveIdea", d.improveIdea, 2, "自社に転用できる打ち手")}</div>
              <div class="cpi-field cpi-rating-field">
                <label>評価（主観）</label>
                <div class="cpi-stars">${stars}<span class="cpi-rating-num">${d.rating || 0}/5</span></div>
              </div>
            </section>

            <!-- ⑤ その他の情報 -->
            <section class="cpi-panel">
              <div class="cpi-panel-head">${badge(5)}<h3>その他の情報 <span class="cpi-sub">（任意）</span></h3></div>
              <div class="cpi-field"><label>関連する自社テーマ</label>${select("competitorDraft.relatedOwnTheme", d.relatedOwnTheme, [{ value: "", label: "選択" }, ...themeOptions.map((t) => ({ value: t, label: t }))])}</div>
              <div class="cpi-field"><label>自社への示唆</label>${countArea("competitorDraft.ownInsight", d.ownInsight, 3, "自社の投稿にどう活かすか")}</div>
              <div class="cpi-field"><label>備考</label>${countArea("competitorDraft.note", d.note, 3, "その他メモ")}</div>
            </section>
          </div>
        </div>
      </div>

      <div class="cpi-footbar">
        <button class="cmp-btn-ghost" data-action="cpi-cancel">キャンセル</button>
        <button class="cmp-btn-ghost" data-action="cpi-save-draft">${icon("bookmark")}<span>下書きとして保存</span></button>
        <button class="cmp-btn-primary" data-action="cpi-save-analyze">${icon("plus")}<span>保存して分析に追加</span></button>
      </div>
    </div>
  `;
}

/** 競合投稿入力の下書きを competitorPosts へ確定。analyzed=true で「分析に追加」（ダッシュボード等に集計反映）。 */
function commitCompetitorDraft(analyzed) {
  collectFormValues();
  const d = state.competitorDraft || blankCompetitorPost();
  if (!d.competitorId) { showSaved("競合企業を選択してください"); return; }
  const keyLabel = { instagram: "Instagram", x: "X", tiktok: "TikTok", youtube: "YouTube Shorts", facebook: "Facebook", linkedin: "LinkedIn", threads: "Threads", note: "Note", other: "その他" };
  const post = normalizeCompetitorPost(d);
  post.id = generateId("cp");
  post.channel = post.channels[0] ? (keyLabel[post.channels[0]] || post.channels[0]) : "";
  if (post.postDate) post.postDate = `${post.postDate}T${post.postTime || "00:00"}`;
  post.cta = classifyCta(post.ctaText);
  post.analyzed = analyzed;
  const nowIso = new Date().toISOString();
  post.createdAt = nowIso;
  post.analyzedAt = analyzed ? nowIso : "";
  state.competitorPosts.push(post);
  state.competitorDraft = blankCompetitorPost();
  persist();
  showSaved(analyzed ? "競合投稿を分析に追加しました" : "下書きとして保存しました");
  render();
}

// 投稿分析の補助
const CA_THEME_TONE = { "成功事例・実績": "orange", "FAQ・ノウハウ": "green", "教育・学習コンテンツ": "green", "イベント・キャンペーン": "violet", "採用・カルチャー": "gray", "キャリア・転職": "blue", "お知らせ・その他": "gray" };
const CA_FORMAT_DESC = { "カルーセル": "複数の画像をスライド形式で表示する投稿", "リール": "縦型のショート動画", "画像": "1枚画像の投稿", "動画": "通常尺の動画投稿", "Shorts": "縦型ショート動画", "テキスト": "テキスト中心の投稿", "ライブ": "ライブ配信", "ストーリーズ": "24時間で消える投稿" };
function caSnsIcon(ch) {
  const m = { Instagram: "instagram", X: "x", "X (Twitter)": "x", TikTok: "tiktok", YouTube: "youtube", "YouTube Shorts": "youtube", Facebook: "facebook", LinkedIn: "linkedin", Threads: "threads", Note: "note", note: "note", LINE: "line" };
  return socialIconData[m[ch]] || "";
}
function caKfmt(n) { n = numberValue(n); return n >= 10000 ? `${(n / 1000).toFixed(1)}K` : n.toLocaleString(); }
function caFmtDateTime(iso) {
  const t = Date.parse(iso); if (Number.isNaN(t)) return "-";
  const d = new Date(t);
  return `${d.getFullYear()}/${String(d.getMonth() + 1).padStart(2, "0")}/${String(d.getDate()).padStart(2, "0")} ${String(d.getHours()).padStart(2, "0")}:${String(d.getMinutes()).padStart(2, "0")}`;
}
function caFilteredPosts() {
  const kw = caSearch.trim().toLowerCase();
  const range = cmpPeriodRange();
  let list = state.competitorPosts.filter((p) => {
    const postedAt = Date.parse(p.postDate);
    if (Number.isNaN(postedAt) || postedAt < range.start.getTime() || postedAt > range.end.getTime()) return false;
    if (caCompanyFilter && p.competitorId !== caCompanyFilter) return false;
    if (caSnsFilter && p.channel !== caSnsFilter) return false;
    if (caThemeFilter && p.theme !== caThemeFilter) return false;
    if (kw) {
      const hay = `${p.hook} ${p.caption} ${p.ctaText} ${(p.tags || []).join(" ")}`.toLowerCase();
      if (!hay.includes(kw)) return false;
    }
    return true;
  });
  if (caSort === "old") list = list.slice().sort((a, b) => Date.parse(a.postDate) - Date.parse(b.postDate));
  else if (caSort === "likes") list = list.slice().sort((a, b) => b.likes - a.likes);
  else list = list.slice().sort((a, b) => Date.parse(b.postDate) - Date.parse(a.postDate));
  return list;
}

function competitorAnalysisSubView() {
  const filtered = caFilteredPosts();
  const total = filtered.length;
  const pageSize = 10;
  const totalPages = Math.max(1, Math.ceil(total / pageSize));
  const page = Math.min(Math.max(1, caPage), totalPages);
  const pagePosts = filtered.slice((page - 1) * pageSize, (page - 1) * pageSize + pageSize);
  // 選択中投稿の解決
  let selected = filtered.find((p) => p.id === caSelectedId);
  if (!selected) { selected = filtered[0] || null; caSelectedId = selected ? selected.id : null; }

  const companyOpts = [{ value: "", label: "すべての企業" }, ...state.competitors.map((c) => ({ value: c.id, label: c.name }))];
  const snsList = [...new Set(state.competitorPosts.map((p) => p.channel).filter(Boolean))];
  const themeList = [...new Set(state.competitorPosts.map((p) => p.theme).filter(Boolean))];

  const themeChip = (t) => t ? `<span class="ca-theme-chip ${CA_THEME_TONE[t] || "gray"}">${escapeHtml(t)}</span>` : "";
  const card = (p) => {
    const comp = findById(state.competitors, p.competitorId);
    const ic = caSnsIcon(p.channel);
    const shot = (p.screenshots && p.screenshots[0]) || "";
    return `
      <button class="ca-card ${p.id === caSelectedId ? "on" : ""}" data-ca-select="${escapeHtml(p.id)}">
        <div class="ca-card-head">
          <span class="ca-card-logo">${companyLogo(comp || { name: "?" })}</span>
          <span class="ca-card-co">${escapeHtml(comp ? comp.name : "—")}</span>
          ${ic ? `<img class="ca-card-sns" src="${ic}" alt="">` : ""}
          <span class="ca-card-date">${caFmtDateTime(p.postDate).slice(0, 16)}</span>
        </div>
        <div class="ca-card-body">
          <div class="ca-card-thumb">${shot ? `<img src="${escapeHtml(shot)}" alt="">` : `<span class="ca-thumb-ph">${icon("palette")}</span>`}</div>
          <div class="ca-card-main">
            <p class="ca-card-title">${escapeHtml(p.hook || "（無題の投稿）")}</p>
            ${themeChip(p.theme)}
          </div>
        </div>
        <div class="ca-card-metrics">
          <span>${icon("heart")}${caKfmt(p.likes)}</span>
          <span>${icon("message")}${caKfmt(p.comments)}</span>
          <span>${icon("send")}${caKfmt(p.shares)}</span>
          <span>${icon("eye")}${caKfmt(p.plays)}</span>
        </div>
      </button>`;
  };

  // 全件一覧モード（全幅テーブル）。フィルタ/検索/並替/ページャは分析ビューと同じ data 属性を流用。
  if (caListMode) {
    const stars = (r) => `<span class="ca-lm-stars">${"★".repeat(r)}${"☆".repeat(Math.max(0, 5 - r))}</span>`;
    const rows = pagePosts.map((p) => {
      const comp = findById(state.competitors, p.competitorId);
      const ic = caSnsIcon(p.channel);
      const shot = (p.screenshots && p.screenshots[0]) || "";
      return `
        <tr>
          <td class="ca-lm-post">
            <span class="ca-lm-thumb">${shot ? `<img src="${escapeHtml(shot)}" alt="">` : `<span class="ca-thumb-ph">${icon("palette")}</span>`}</span>
            <span class="ca-lm-title">${escapeHtml(p.hook || "（無題の投稿）")}</span>
          </td>
          <td class="ca-lm-co"><span class="ca-card-logo">${companyLogo(comp || { name: "?" })}</span>${escapeHtml(comp ? comp.name : "—")}</td>
          <td class="ca-lm-sns">${ic ? `<img src="${ic}" alt="${escapeHtml(p.channel)}">` : escapeHtml(p.channel || "-")}</td>
          <td>${p.theme ? themeChip(p.theme) : "-"}</td>
          <td class="ca-lm-num">${numberValue(p.likes).toLocaleString()}</td>
          <td class="ca-lm-num">${numberValue(p.comments).toLocaleString()}</td>
          <td class="ca-lm-num">${numberValue(p.shares).toLocaleString()}</td>
          <td class="ca-lm-num">${numberValue(p.plays).toLocaleString()}</td>
          <td class="ca-lm-date">${caFmtDateTime(p.postDate).slice(0, 10)}</td>
          <td>${p.analyzed ? stars(p.rating) : '<span class="muted">未分析</span>'}</td>
          <td><button class="cmp-btn-ghost ca-lm-open" data-ca-open-analysis="${escapeHtml(p.id)}">${icon("chart")}<span>分析</span></button></td>
        </tr>`;
    }).join("");
    return `
      <div class="ca-listmode">
        <div class="ca-lm-bar">
          <div class="ca-lm-headline">投稿一覧 <span class="cpi-sub">（${total}件）</span></div>
          <div class="ca-lm-filters">
            <select data-ca-filter="company">${companyOpts.map((o) => `<option value="${escapeHtml(o.value)}" ${caCompanyFilter === o.value ? "selected" : ""}>${escapeHtml(o.label)}</option>`).join("")}</select>
            <select data-ca-filter="sns"><option value="">すべてのSNS</option>${snsList.map((s) => `<option value="${escapeHtml(s)}" ${caSnsFilter === s ? "selected" : ""}>${escapeHtml(s)}</option>`).join("")}</select>
            <select data-ca-filter="theme"><option value="">すべてのテーマ</option>${themeList.map((t) => `<option value="${escapeHtml(t)}" ${caThemeFilter === t ? "selected" : ""}>${escapeHtml(t)}</option>`).join("")}</select>
            <label class="ca-search"><input type="search" placeholder="投稿を検索（キーワード、CTAなど）" value="${escapeHtml(caSearch)}" data-ca-search></label>
            <select data-ca-sort><option value="new" ${caSort === "new" ? "selected" : ""}>新しい順</option><option value="old" ${caSort === "old" ? "selected" : ""}>古い順</option><option value="likes" ${caSort === "likes" ? "selected" : ""}>いいね順</option></select>
            <button class="cmp-btn-primary ca-lm-toggle" data-ca-listmode="0">${icon("dashboard")}<span>分析ビュー</span></button>
          </div>
        </div>
        <div class="cmp-table-wrap">
          <table class="cmp-table ca-lm-table">
            <thead><tr><th>投稿</th><th>企業</th><th>SNS</th><th>テーマ</th><th>いいね</th><th>コメント</th><th>シェア</th><th>再生</th><th>投稿日</th><th>評価</th><th></th></tr></thead>
            <tbody>${rows || `<tr><td colspan="11" class="cmp-empty">該当する投稿がありません</td></tr>`}</tbody>
          </table>
        </div>
        <div class="cmp-table-foot">
          <span class="cmp-count">${total ? `${(page - 1) * pageSize + 1}-${Math.min(page * pageSize, total)} / ${total}件` : "0件"}</span>
          <div class="cmp-pager">
            <button class="cmp-pg-btn" data-ca-page="${page - 1}" ${page === 1 ? "disabled" : ""}>${icon("chevron")}</button>
            ${Array.from({ length: totalPages }, (_, i) => i + 1).slice(Math.max(0, page - 3), Math.max(0, page - 3) + 6).map((n) => `<button class="cmp-pg-btn ${n === page ? "active" : ""}" data-ca-page="${n}">${n}</button>`).join("")}
            <button class="cmp-pg-btn" data-ca-page="${page + 1}" ${page === totalPages ? "disabled" : ""}>${icon("chevron")}</button>
          </div>
        </div>
      </div>`;
  }

  const listPanel = `
    <section class="ca-panel ca-list-panel">
      <div class="cpi-panel-head">${'<span class="cpi-badge">1</span>'}<h3>投稿一覧 <span class="cpi-sub">（${total}件）</span></h3><button class="ca-list-icon" data-ca-listmode="1" title="全件を一覧表示">${icon("segments")}</button></div>
      <div class="ca-filters">
        <label>フィルター</label>
        <div class="ca-filter-row">
          <select data-ca-filter="company">${companyOpts.map((o) => `<option value="${escapeHtml(o.value)}" ${caCompanyFilter === o.value ? "selected" : ""}>${escapeHtml(o.label)}</option>`).join("")}</select>
          <select data-ca-filter="sns"><option value="">すべてのSNS</option>${snsList.map((s) => `<option value="${escapeHtml(s)}" ${caSnsFilter === s ? "selected" : ""}>${escapeHtml(s)}</option>`).join("")}</select>
          <select data-ca-filter="theme"><option value="">すべてのテーマ</option>${themeList.map((t) => `<option value="${escapeHtml(t)}" ${caThemeFilter === t ? "selected" : ""}>${escapeHtml(t)}</option>`).join("")}</select>
        </div>
        <label class="ca-search">${icon("search")}<input type="search" placeholder="投稿を検索（キーワード、CTAなど）" value="${escapeHtml(caSearch)}" data-ca-search></label>
        <div class="ca-sort">並び替え：<select data-ca-sort><option value="new" ${caSort === "new" ? "selected" : ""}>投稿日（新しい順）</option><option value="old" ${caSort === "old" ? "selected" : ""}>投稿日（古い順）</option><option value="likes" ${caSort === "likes" ? "selected" : ""}>いいね数（多い順）</option></select></div>
      </div>
      <div class="ca-cards">${pagePosts.map(card).join("") || `<p class="panel-note ca-empty">該当する投稿がありません</p>`}</div>
      <div class="ca-list-foot">
        <span class="ca-pageno">${page} / ${totalPages}</span>
        <div class="ca-pager">
          <button class="cmp-pg-btn" data-ca-page="${page - 1}" ${page === 1 ? "disabled" : ""}>${icon("chevron")}</button>
          <button class="cmp-pg-btn" data-ca-page="${page + 1}" ${page === totalPages ? "disabled" : ""}>${icon("chevron")}</button>
        </div>
      </div>
    </section>`;

  if (!selected) {
    return `<div class="ca-grid"><div>${listPanel}</div><section class="ca-panel"><p class="panel-note">競合投稿がまだありません。競合投稿入力から登録してください。</p></section><div></div></div>`;
  }

  const p = selected;
  const idx = state.competitorPosts.indexOf(p);
  const comp = findById(state.competitors, p.competitorId);
  const shots = p.screenshots || [];
  const slide = Math.min(caSlide, Math.max(0, shots.length - 1));

  // 分析結果カード（編集可能）
  const analysisCard = (field, title, emoji, tone) => {
    const val = p[field] || "";
    const lines = val.split("\n").map((l) => l.trim()).filter(Boolean);
    const editing = caEditField === field;
    return `
      <div class="ca-analysis-card ${tone}">
        <div class="ca-analysis-head"><h4>${escapeHtml(title)} <span class="ca-emoji">${emoji}</span></h4>
          ${editing ? "" : `<button class="ca-edit-btn" data-ca-edit="${field}">${icon("pencil")}</button>`}
        </div>
        ${editing ? `
          <textarea class="ca-analysis-ta" data-path="competitorPosts.${idx}.${field}" maxlength="500" rows="5" placeholder="1行に1項目で入力">${escapeHtml(val)}</textarea>
          <div class="ca-analysis-foot"><span class="cpi-count">${val.length} / 500</span><button class="ca-save-btn" data-ca-edit-save="1">${icon("check")}保存</button></div>
        ` : `
          <ul class="ca-analysis-list">${lines.length ? lines.map((l) => `<li>${escapeHtml(l)}</li>`).join("") : `<li class="muted">未記入</li>`}</ul>
          <span class="ca-analysis-count">${val.length} / 500</span>
        `}
      </div>`;
  };

  const detailPanel = `
    <section class="ca-panel ca-detail-panel">
      <div class="cpi-panel-head">${'<span class="cpi-badge">2</span>'}<h3>投稿詳細 <span class="cpi-sub">（編集可能）</span></h3></div>
      <div class="ca-detail-co">
        <span class="ca-detail-logo">${companyLogo(comp || { name: "?" })}</span>
        <strong>${escapeHtml(comp ? comp.name : "—")}</strong>
        ${caSnsIcon(p.channel) ? `<img class="ca-detail-sns" src="${caSnsIcon(p.channel)}" alt="">` : ""}
        <span class="ca-detail-fol">フォロワー ${numberValue(p.followers).toLocaleString()}人</span>
        <button class="cmp-btn-ghost ca-profile-btn" data-ca-company-profile>企業プロフィールへ</button>
      </div>
      <div class="ca-detail-daterow"><span>${caFmtDateTime(p.postDate)}</span>${p.url ? `<a href="${escapeHtml(p.url)}" target="_blank" rel="noopener" class="ca-open">投稿を開く ${icon("external")}</a>` : ""}</div>
      ${shots.length ? `
        <div class="ca-preview"><img src="${escapeHtml(shots[slide])}" alt=""><span class="ca-slide-no">${slide + 1}/${shots.length}</span></div>
        <div class="ca-thumbs">${shots.map((s, si) => `<button class="ca-thumb ${si === slide ? "on" : ""}" data-ca-slide="${si}"><img src="${escapeHtml(s)}" alt=""><span>${si + 1}</span></button>`).join("")}</div>
      ` : `
        <div class="ca-preview ca-preview-ph"><div class="ca-preview-inner"><span class="ca-preview-tag">${escapeHtml(comp ? comp.name : "")}</span><p class="ca-preview-hook">${escapeHtml(p.hook || "（無題）")}</p><span class="ca-preview-note">${icon("palette")}スクリーンショット未登録</span></div></div>
      `}
      <div class="ca-field">
        <div class="ca-field-head"><label>キャプション <span class="cpi-hint">（編集可能）</span></label>${caEditField === "caption" ? "" : `<button class="ca-edit-btn" data-ca-edit="caption">${icon("pencil")}</button>`}</div>
        ${caEditField === "caption"
          ? `<div class="cpi-ta-wrap"><textarea data-path="competitorPosts.${idx}.caption" maxlength="2200" rows="4">${escapeHtml(p.caption)}</textarea><span class="cpi-count">${(p.caption || "").length} / 2200</span></div><div class="ca-analysis-foot"><span></span><button class="ca-save-btn" data-ca-edit-save="1">${icon("check")}保存</button></div>`
          : `<p class="ca-caption">${p.caption ? escapeHtml(p.caption).replace(/\n/g, "<br>") : "<span class='muted'>未記入</span>"}</p><span class="ca-analysis-count">${(p.caption || "").length} / 2200</span>`}
      </div>
      <div class="ca-field">
        <div class="ca-field-head"><label>ハッシュタグ <span class="cpi-hint">（編集可能）</span></label></div>
        <div class="cpi-tags ca-hashtags">
          ${(p.tags || []).map((t, ti) => `<span class="cpi-tag">#${escapeHtml(t)}<button type="button" data-ca-tag-remove="${idx}:${ti}">${icon("close")}</button></span>`).join("")}
          <input type="text" class="cpi-tag-input" placeholder="＋ 追加" data-ca-tag-input="${idx}">
        </div>
        <span class="ca-analysis-count">${(p.tags || []).length} / 30</span>
      </div>
      <div class="ca-field">
        <div class="ca-field-head"><label>投稿タイプ <span class="cpi-hint">（編集可能）</span></label></div>
        ${select(`competitorPosts.${idx}.format`, p.format, [{ value: "", label: "未設定" }, ...competitorFormatOptions.map((f) => ({ value: f, label: f }))])}
        <span class="ca-format-desc">${escapeHtml(CA_FORMAT_DESC[p.format] || "")}</span>
      </div>
      <div class="ca-field">
        <div class="ca-field-head"><label>公開されている数値 <span class="cpi-hint">（この画面では編集できません）</span></label></div>
        <div class="ca-stats">
          <div class="ca-stat"><span class="ca-stat-ico red">${icon("heart")}</span><small>いいね数</small><strong>${numberValue(p.likes).toLocaleString()}</strong></div>
          <div class="ca-stat"><span class="ca-stat-ico blue">${icon("message")}</span><small>コメント数</small><strong>${numberValue(p.comments).toLocaleString()}</strong></div>
          <div class="ca-stat"><span class="ca-stat-ico green">${icon("send")}</span><small>シェア数</small><strong>${numberValue(p.shares).toLocaleString()}</strong></div>
          <div class="ca-stat"><span class="ca-stat-ico violet">${icon("eye")}</span><small>再生数・表示数</small><strong>${numberValue(p.plays).toLocaleString()}</strong></div>
          <div class="ca-stat"><span class="ca-stat-ico orange">${icon("users")}</span><small>フォロワー数</small><strong>${numberValue(p.followers).toLocaleString()}</strong></div>
        </div>
      </div>
    </section>`;

  const actionBtns = [
    { act: "review", ico: "doc", tone: "green", label: "改善管理へ追加", desc: "改善タスクとして登録し、進捗を管理する" },
    { act: "strategy", ico: "segments", tone: "blue", label: "投稿戦略へ反映", desc: "テーマ・CTA・構成などを戦略に反映する" },
    { act: "design", ico: "palette", tone: "violet", label: "デザイン管理へ反映", desc: "レイアウト・配色・フォントを参考にする" },
    { act: "ideas", ico: "lightbulb", tone: "orange", label: "投稿案へ追加", desc: "この投稿をヒントに新しい投稿案を作成する" },
  ];

  const analysisPanel = `
    <section class="ca-panel ca-analysis-panel">
      <div class="cpi-panel-head">${'<span class="cpi-badge">3</span>'}<h3>分析結果 <span class="cpi-sub">（手動分析メモ・編集可能）</span></h3><button class="cmp-btn-ghost ca-tpl-btn" data-ca-template>${icon("copy")}<span>テンプレートを使用</span></button></div>
      ${analysisCard("successFactor", "成功要因", "👍", "green")}
      ${analysisCard("weakness", "改善点・弱み", "👎", "blue")}
      ${analysisCard("imitatePoint", "真似したい点", "🙌", "violet")}
      ${analysisCard("avoidPoint", "避けたい点", "⚠️", "amber")}
    </section>
    <section class="ca-panel ca-action-panel">
      <div class="cpi-panel-head">${'<span class="cpi-badge">4</span>'}<h3>改善アクション <span class="cpi-sub">（この投稿から得た学びを、自社の改善に活かす）</span></h3></div>
      <div class="ca-actions">
        ${actionBtns.map((b) => `<button class="ca-action ${b.tone}" data-ca-action="${b.act}"><span class="ca-action-ico">${icon(b.ico)}</span><strong>${escapeHtml(b.label)}</strong><small>${escapeHtml(b.desc)}</small></button>`).join("")}
      </div>
      <div class="ca-field ca-memo-field">
        <label>メモ <span class="cpi-hint">（任意）</span></label>
        <div class="cpi-ta-wrap"><textarea data-path="competitorPosts.${idx}.actionMemo" maxlength="500" rows="3" placeholder="この投稿から得た気づきや、自社への活用アイデアを自由にメモしてください。">${escapeHtml(p.actionMemo)}</textarea><span class="cpi-count">${(p.actionMemo || "").length} / 500</span></div>
      </div>
      <p class="ca-action-note">※ アクションは後からでも追加・変更できます。</p>
    </section>`;

  return `
    <div class="ca-grid">
      <div class="ca-col">${listPanel}</div>
      <div class="ca-col">${detailPanel}</div>
      <div class="ca-col">${analysisPanel}</div>
    </div>`;
}

/** 分析結果カードに雛形を流し込む（空欄のみ）。 */
function caApplyAnalysisTemplate() {
  const p = state.competitorPosts.find((x) => x.id === caSelectedId);
  if (!p) return;
  collectFormValues();
  const tpl = {
    successFactor: "冒頭で悩み・課題を提示して共感を得ている\n具体的な数値・実例で説得力を高めている\n読みやすいデザインと余白設計",
    weakness: "CTAが弱く次の行動が不明確\nハッシュタグの差別化が弱い\n成果の具体性が不足",
    imitatePoint: "共感を生むストーリー構成\n1枚目で興味を引くフック\n最後まで読ませる情報の小出し",
    avoidPoint: "抽象的なCTA\n誇張された表現・根拠の薄い主張",
  };
  Object.keys(tpl).forEach((k) => { if (!(p[k] || "").trim()) p[k] = tpl[k]; });
  caEditField = null; persist(); showSaved("分析テンプレートを適用しました"); render();
}

/** 改善アクション：選択中の競合投稿から、他タブ（改善管理・投稿戦略・デザイン・投稿案）へ連携する。 */
function caRunAction(act) {
  collectFormValues();
  const p = state.competitorPosts.find((x) => x.id === caSelectedId);
  if (!p) { showSaved("投稿を選択してください"); return; }
  const comp = findById(state.competitors, p.competitorId);
  const cname = comp ? comp.name : "競合";
  if (act === "review") {
    addRow("review", {
      title: `競合分析：${cname}「${(p.hook || "投稿").slice(0, 18)}」の改善`,
      source: "競合分析",
      relatedSns: p.channel ? [p.channel] : [],
      reflect: [],
      nextAction: (p.improveIdea || p.actionMemo || (p.weakness || "").split("\n")[0] || "").trim(),
      relatedPosts: p.hook || "",
    });
    showSaved("改善管理（目標・改善）に追加しました");
    return;
  }
  if (act === "ideas") {
    addRow("idea", {
      title: p.hook || `${cname}の投稿を参考にした案`,
      source: `競合分析：${cname}`,
      theme: p.relatedOwnTheme || "",
      memo: (p.imitatePoint || "").split("\n")[0] || "",
    });
    activeTab = "ideas";
    showSaved("投稿案に追加しました");
    render();
    return;
  }
  if (act === "strategy") { activeTab = "strategy"; showSaved("投稿戦略タブへ移動しました"); render(); return; }
  if (act === "design") { activeTab = "design"; showSaved("デザイン管理タブへ移動しました"); render(); return; }
}

// ---- ベンチマーク集計 ----
const BM_POINTS = [
  { key: "theme-success", label: "テーマに成功事例を増やす", pri: "高" },
  { key: "reel-ratio", label: "リールの投稿比率を上げる", pri: "高" },
  { key: "time", label: "投稿時間帯を最適化する", pri: "中" },
  { key: "cta", label: "CTAの強化（無料相談）", pri: "高" },
  { key: "design", label: "デザインのインパクト強化", pri: "中" },
  { key: "icon", label: "図解・アイコンの活用強化", pri: "高" },
  { key: "hashtag", label: "ハッシュタグ数を増やす", pri: "中" },
  { key: "campaign", label: "キャンペーンを増やす", pri: "低" },
  { key: "text", label: "文字量を増やす", pri: "低" },
];
const BM_QUAL_POOL = [
  { design: "シンプル・ミニマル", colors: ["#1e2b5e", "#4c6ef5", "#7c8db5", "#c9b48f"], comp: "人物中心・余白多め" },
  { design: "高コントラスト・インパクト重視", colors: ["#5b2a86", "#7c5cff", "#ff6b6b", "#f59f00"], comp: "テキスト＋人物の構成が多い" },
  { design: "教育・信頼感重視", colors: ["#2f5bd8", "#3aa675", "#f5a623", "#e06b2a"], comp: "図解・テキスト中心" },
  { design: "親しみやすい・カジュアル", colors: ["#2f5bd8", "#3aa675", "#ff8fa3", "#e5484d"], comp: "人物中心・アイコン活用" },
  { design: "信頼感・医療系トーン", colors: ["#1e2b5e", "#5b7cc4", "#8aa0c8", "#c3ccdd"], comp: "図解・グラフが多い" },
  { design: "シンプル・ポップ", colors: ["#2aa6a0", "#ff8fa3", "#8f7cff", "#f59f00"], comp: "テキスト中心" },
];
const BM_DESIGN_OPTS = ["シンプル・ミニマル", "高コントラスト・インパクト重視", "教育・信頼感重視", "親しみやすい・カジュアル", "信頼感・医療系トーン", "シンプル・ポップ", "スタイリッシュ・モダン", "その他"];
const BM_COMP_OPTS = ["人物中心・余白多め", "テキスト＋人物の構成が多い", "図解・テキスト中心", "人物中心・アイコン活用", "図解・グラフが多い", "テキスト中心", "写真中心", "その他"];
function bmFormatCat(fmt) {
  fmt = String(fmt || "");
  if (/カルーセル/.test(fmt)) return "カルーセル";
  if (/リール|ショート|Shorts|reel/i.test(fmt)) return "リール";
  if (/画像|image/i.test(fmt)) return "画像";
  if (/動画|video|ライブ|ストーリー/i.test(fmt)) return "動画";
  return "画像";
}
/** ベンチマーク集計期間のウィンドウ。全期間なら null。 */
function bmPeriodWindow() {
  if (bmPeriod === "全期間") return null;
  const r = cmpPeriodRange(bmPeriod);
  return { start: r.start.getTime(), end: r.end.getTime(), label: r.label };
}
function bmInWindow(iso) {
  const w = bmPeriodWindow();
  if (!w) return true;
  const t = Date.parse(iso);
  return !Number.isNaN(t) && t >= w.start && t <= w.end;
}
function bmAccountList(kind, id) {
  if (kind === "own") {
    return state.posts.map((p) => ({
      postDate: p.publishAt || p.due || "",
      theme: themeShortLabels[p.theme] || p.theme,
      format: p.format,
      cta: classifyCta(p.cta),
      textLen: (p.hook || "").length + (p.body || "").length,
      tagCount: (() => { const hs = findById(state.hashtagSets, p.hashtagSetId); return hs && Array.isArray(hs.tags) ? hs.tags.length : 0; })(),
      campaign: p.campaignId || "",
      followers: numberValue(p.followersAtPost),
    })).filter((x) => bmInWindow(x.postDate));
  }
  let list = state.competitorPosts.filter((pp) => pp.competitorId === id);
  const bySns = list.filter((pp) => pp.channel === bmSns);
  if (bmSns && bySns.length >= 3) list = bySns; // データが十分ならSNS別、少なければ全件
  return list.map((p) => ({
    postDate: p.postDate,
    theme: competitorThemeShort[p.theme] || p.theme,
    format: p.format,
    cta: p.cta,
    textLen: (p.caption || p.hook || "").length,
    tagCount: (p.tags || []).length,
    campaign: p.campaign || "",
    followers: numberValue(p.followers),
  })).filter((x) => bmInWindow(x.postDate));
}
function bmStats(list) {
  const n = list.length;
  const dates = list.map((x) => Date.parse(x.postDate)).filter((t) => !Number.isNaN(t));
  const spanDays = dates.length ? Math.max(7, (Math.max(...dates) - Math.min(...dates)) / 864e5) : 7;
  const freq = n ? Math.round(n / (spanDays / 7) * 10) / 10 : 0;
  const distPct = (arr) => { const c = {}; arr.forEach((v) => { if (v) c[v] = (c[v] || 0) + 1; }); const tot = Object.values(c).reduce((a, b) => a + b, 0) || 1; return Object.entries(c).sort((a, b) => b[1] - a[1]).map(([k, v]) => ({ name: k, pct: Math.round(v / tot * 100) })); };
  const themeTop = distPct(list.map((x) => x.theme));
  const fmt = distPct(list.map((x) => bmFormatCat(x.format)));
  const fmtPct = (name) => (fmt.find((f) => f.name === name) || { pct: 0 }).pct;
  const cta = distPct(list.map((x) => x.cta));
  const wd = ["日", "月", "火", "水", "木", "金", "土"];
  const dh = {};
  list.forEach((x) => { const t = Date.parse(x.postDate); if (Number.isNaN(t)) return; const d = new Date(t); const k = `${wd[d.getDay()]}|${d.getHours()}`; dh[k] = (dh[k] || 0) + 1; });
  const topSlots = Object.entries(dh).sort((a, b) => b[1] - a[1]).slice(0, 2).map(([k]) => { const [dy, h] = k.split("|"); return { day: dy, hour: `${h}時台` }; });
  const textAvg = n ? Math.round(list.reduce((s, x) => s + (x.textLen || 0), 0) / n) : 0;
  const hashtagAvg = n ? Math.round(list.reduce((s, x) => s + (x.tagCount || 0), 0) / n * 10) / 10 : 0;
  const months = dates.length ? Math.max(1, (Math.max(...dates) - Math.min(...dates)) / 864e5 / 30) : 1;
  const campaignFreq = Math.round(list.filter((x) => x.campaign).length / months * 10) / 10;
  const followers = list.reduce((m, x) => Math.max(m, x.followers || 0), 0);
  return { n, freq, themeTop, fmt, fmtPct, cta, topSlots, textAvg, videoRatio: fmtPct("リール") + fmtPct("動画"), carouselRatio: fmtPct("カルーセル"), hashtagAvg, campaignFreq, followers };
}

function competitorBenchmarkSubView() {
  const benchDefault = state.competitors.filter((c) => c.benchmark).map((c) => c.id);
  if (!bmCompetitorIds) bmCompetitorIds = (benchDefault.length ? benchDefault : state.competitors.map((c) => c.id)).slice(0, 5);
  const compIds = bmCompetitorIds.filter((id) => state.competitors.find((c) => c.id === id)).slice(0, 5);

  const ownName = (state.accounts.find((a) => a.channel === bmSns) || {}).handle || "自社公式";
  const accounts = [{ kind: "own", id: "own", name: `自社\n${ownName}`, comp: state.competitors[0], stats: bmStats(bmAccountList("own")), qual: BM_QUAL_POOL[0] }];
  compIds.forEach((id, i) => {
    const c = state.competitors.find((x) => x.id === id);
    accounts.push({ kind: "comp", id, name: c ? c.name : "—", comp: c, stats: bmStats(bmAccountList("comp", id)), qual: BM_QUAL_POOL[(i + 1) % BM_QUAL_POOL.length] });
  });
  // 傾向（デザイン/色/構図）は state.benchmarkQual にアカウント別で永続化。無ければプール既定値。
  state.benchmarkQual = state.benchmarkQual || {};
  accounts.forEach((a, i) => {
    const def = BM_QUAL_POOL[i % BM_QUAL_POOL.length];
    const cur = state.benchmarkQual[a.id] || {};
    state.benchmarkQual[a.id] = {
      design: cur.design || def.design,
      comp: cur.comp || def.comp,
      colors: (Array.isArray(cur.colors) && cur.colors.length) ? cur.colors : def.colors.slice(),
      textAvg: cur.textAvg ?? "", videoRatio: cur.videoRatio ?? "", carouselRatio: cur.carouselRatio ?? "", hashtagAvg: cur.hashtagAvg ?? "", campaignFreq: cur.campaignFreq ?? "",
    };
    a.qual = state.benchmarkQual[a.id];
  });
  // 数値行：手動上書き（benchmarkQual）があればそれを、無ければ自動集計値を使う（連携＋任意編集）
  const bmVal = (a, field) => { const o = a.qual[field]; return (o !== "" && o !== undefined && o !== null) ? numberValue(o) : a.stats[field]; };

  const own = accounts[0].stats;
  const cls = (compVal, ownVal, higherBetter = true) => {
    if (!ownVal && !compVal) return "";
    const rel = Math.abs(compVal - ownVal) / (Math.abs(ownVal) || 1);
    if (rel < 0.1) return "bm-eq";
    const better = higherBetter ? compVal > ownVal : compVal < ownVal;
    return better ? "bm-comp" : "bm-own";
  };
  const num = (v) => (Math.round(v * 10) / 10).toLocaleString();

  // ---- 自社との比較インサイト（自社 vs 競合平均を実データで判定→具体アドバイスを自動生成。行別に手動上書きも可） ----
  const compAccts = accounts.slice(1);
  const cavg = (fn) => compAccts.length ? compAccts.reduce((s, a) => s + (fn(a) || 0), 0) / compAccts.length : 0;
  const successShare = (st) => st.themeTop.filter((t) => /成功|実績|事例/.test(t.name)).reduce((s, t) => s + t.pct, 0);
  const ctaShare = (st, name) => (st.cta.find((x) => x.name === name) || { pct: 0 }).pct;
  // 数値比較→{state, gap}。state: behind(自社が劣る=赤)/ahead(自社が優れる=緑)/neutral(同水準=灰)
  const gj = (ownV, compV, unit = "") => {
    if (!ownV && !compV) return { s: "neutral", diff: 0, unit };
    const rel = (compV - ownV) / (Math.abs(compV) || 1);
    if (Math.abs(rel) < 0.12) return { s: "neutral", diff: 0, unit };
    return { s: compV > ownV ? "behind" : "ahead", diff: Math.round(Math.abs(compV - ownV) * 10) / 10, unit };
  };
  // 具体アドバイス文（差分の大きさ・方向・打ち手を織り込む）
  const advise = (r, texts) => {
    const gapTxt = r.diff ? `（競合平均と約${r.diff}${r.unit}差）` : "";
    return { cls: r.s === "behind" ? "bm-comp" : r.s === "ahead" ? "bm-own" : "", text: texts[r.s] + gapTxt };
  };
  const bmAutoInsight = (no) => {
    const ownFor = (f) => bmVal(accounts[0], f);
    switch (no) {
      case 1: return advise(gj(own.freq, cavg((a) => a.stats.freq), "件"), { behind: "投稿頻度を上げる余地あり", ahead: "投稿頻度は競合以上", neutral: "投稿頻度は同水準" });
      case 2: return advise(gj(successShare(own), cavg((a) => successShare(a.stats)), "%"), { behind: "成功事例テーマを増やす", ahead: "成功事例テーマが豊富", neutral: "テーマ構成は同水準" });
      case 3: return advise(gj(own.fmtPct("リール"), cavg((a) => a.stats.fmtPct("リール")), "%"), { behind: "リール投稿を増やす", ahead: "リール活用が進んでいる", neutral: "形式構成は同水準" });
      case 4: return advise(gj(ctaShare(own, "無料相談"), cavg((a) => ctaShare(a.stats, "無料相談")), "%"), { behind: "無料相談CTAを強化", ahead: "CTA誘導が強い", neutral: "CTA傾向は同水準" });
      case 5: return { cls: "", text: own.topSlots[0] ? `自社ピークは${own.topSlots.map((s) => s.day + s.hour).join("・")}。競合の集中帯と比較を` : "投稿時間帯の傾向を要確認" };
      case 6: return { cls: "", text: "競合の高インパクト系に対し視認性を強化" };
      case 7: return { cls: "", text: "ブランドカラーの統一感を確認" };
      case 8: return { cls: "", text: "図解・アイコンの活用を強化" };
      case 9: return advise(gj(ownFor("textAvg"), cavg((a) => bmVal(a, "textAvg")), "文字"), { behind: "1投稿の文字量を増やす", ahead: "文字量は十分", neutral: "文字量は同水準" });
      case 10: return advise(gj(ownFor("videoRatio"), cavg((a) => bmVal(a, "videoRatio")), "%"), { behind: "動画・リール比率を上げる", ahead: "動画活用が進んでいる", neutral: "動画比率は同水準" });
      case 11: return advise(gj(ownFor("carouselRatio"), cavg((a) => bmVal(a, "carouselRatio")), "%"), { behind: "カルーセルを強化", ahead: "カルーセルが強み", neutral: "カルーセル比率は同水準" });
      case 12: return advise(gj(ownFor("hashtagAvg"), cavg((a) => bmVal(a, "hashtagAvg")), "個"), { behind: "ハッシュタグ数を増やす", ahead: "ハッシュタグは十分", neutral: "ハッシュタグ数は同水準" });
      case 13: return advise(gj(ownFor("campaignFreq"), cavg((a) => bmVal(a, "campaignFreq")), "件"), { behind: "キャンペーンを増やす", ahead: "キャンペーン活用が活発", neutral: "キャンペーン頻度は同水準" });
      default: return { cls: "", text: "" };
    }
  };
  // 表示は手動上書き（benchmarkNotes.rows）があればそれを優先、無ければ自動アドバイス
  const bmRowInsight = (no) => {
    const ov = (state.benchmarkNotes.rows || {})[no];
    if (ov !== undefined && ov !== "") return { cls: "", text: ov, manual: true };
    return bmAutoInsight(no);
  };

  // ---- 各行の描画 ----
  const barMini = (v, max, color) => { const w = max ? Math.round(v / max * 100) : 0; return `<span class="bm-bar"><i style="width:${w}%;background:${color}"></i></span>`; };
  const donut = (drows) => {
    const pal = ["#4c6ef5", "#c3c9d4", "#f5a623", "#e6eaf3", "#7c5cff"];
    const segs = drows.slice(0, 4).map((r, i) => ({ pct: r.pct, color: pal[i] || "#e6eaf3" }));
    const sum = segs.reduce((s, x) => s + x.pct, 0); if (sum < 100) segs.push({ pct: 100 - sum, color: "#eef1f7" });
    return `<span class="bm-donut" style="background:${conicGradient(segs)}"></span>`;
  };
  const selCell = (a, field, opts) => select(`benchmarkQual.${a.id}.${field}`, a.qual[field], opts);
  const rowColors = (a) => (bmColorEdit === a.id
    ? `<div class="bm-colors editing">${a.qual.colors.map((c, ci) => `<input type="color" value="${escapeHtml(c)}" data-bm-color="${a.id}:${ci}">`).join("")}<button class="bm-color-done" data-bm-color-done title="完了">${icon("check")}</button></div>`
    : `<div class="bm-colors">${a.qual.colors.map((c) => `<i style="background:${escapeHtml(c)}"></i>`).join("")}<button class="ca-edit-btn" data-bm-color-edit="${a.id}">${icon("pencil")}</button></div>`);

  const rowFreq = (a) => `<div class="bm-freq"><strong class="${a.kind === "comp" ? cls(a.stats.freq, own.freq) : ""}">${num(a.stats.freq)}</strong><small>件/週</small>${barMini(a.stats.freq, 8, a.kind === "comp" ? "#e5484d" : "#4c6ef5")}</div>`;
  const rowTheme = (a) => `<div class="bm-theme">${donut(a.stats.themeTop)}<ul>${(a.stats.themeTop.slice(0, 4)).map((r) => `<li><span>${escapeHtml(r.name)}</span><b>${r.pct}%</b></li>`).join("") || "<li class='muted'>データなし</li>"}</ul></div>`;
  const rowFormat = (a) => `<ul class="bm-format">${["カルーセル", "リール", "画像", "動画"].map((f) => { const pct = a.stats.fmtPct(f); const c = a.kind === "comp" ? cls(pct, own.fmtPct(f)) : ""; return `<li><span>${f}</span>${barMini(pct, 60, "#8aa0d8")}<b class="${c}">${pct}%</b></li>`; }).join("")}</ul>`;
  const rowCta = (a) => `<ul class="bm-cta">${["保存", "プロフィール", "無料相談", "DM", "コメント"].map((k) => { const pct = (a.stats.cta.find((x) => x.name === k) || { pct: 0 }).pct; const ownPct = (own.cta.find((x) => x.name === k) || { pct: 0 }).pct; return `<li><span>${k}</span><b class="${a.kind === "comp" ? cls(pct, ownPct) : ""}">${pct}%</b></li>`; }).join("")}</ul>`;
  const rowTime = (a) => `<div class="bm-time">${icon("reset")}<div>${(a.stats.topSlots.length ? a.stats.topSlots : [{ day: "-", hour: "-" }]).map((s) => `<span>${escapeHtml(s.day)} ${escapeHtml(s.hour)}</span>`).join("")}</div></div>`;
  // 数値セル：自動値を表示。鉛筆で手動上書き（overrideがあれば●印）。
  const editCell = (a, field, unit) => {
    const key = `${a.id}:${field}`;
    const overridden = a.qual[field] !== "" && a.qual[field] !== undefined && a.qual[field] !== null;
    if (bmNumEdit === key) {
      return `<div class="bm-edit editing"><input type="number" step="0.1" data-path="benchmarkQual.${a.id}.${field}" value="${escapeHtml(String(a.qual[field] === "" ? bmVal(a, field) : a.qual[field]))}"><small>${escapeHtml(unit)}</small><button class="bm-color-done" data-bm-num-done title="完了">${icon("check")}</button></div>`;
    }
    return `<div class="bm-edit"><strong class="${overridden ? "bm-ovr" : ""}">${escapeHtml(String(bmVal(a, field)))}</strong><small>${escapeHtml(unit)}</small><button class="ca-edit-btn" data-bm-num-edit="${key}">${icon("pencil")}</button></div>`;
  };

  const rows = [
    { no: 1, label: "投稿頻度（週平均）", cell: rowFreq },
    { no: 2, label: "テーマ構成TOP（%）", cell: rowTheme },
    { no: 3, label: "投稿形式の割合（%）", cell: rowFormat },
    { no: 4, label: "CTAの傾向（%）", cell: rowCta },
    { no: 5, label: "投稿時間帯（主な時間帯）", cell: rowTime },
    { no: 6, label: "デザインの傾向", cell: (a) => selCell(a, "design", BM_DESIGN_OPTS) },
    { no: 7, label: "色の傾向", cell: rowColors },
    { no: 8, label: "構図の傾向", cell: (a) => selCell(a, "comp", BM_COMP_OPTS) },
    { no: 9, label: "文字量（1投稿あたり平均）", cell: (a) => editCell(a, "textAvg", "文字") },
    { no: 10, label: "動画（リール・動画）比率", cell: (a) => editCell(a, "videoRatio", "%") },
    { no: 11, label: "カルーセル比率", cell: (a) => editCell(a, "carouselRatio", "%") },
    { no: 12, label: "ハッシュタグ数（平均）", cell: (a) => editCell(a, "hashtagAvg", "個") },
    { no: 13, label: "キャンペーン活用頻度", cell: (a) => editCell(a, "campaignFreq", "件/月") },
  ];

  const headCell = (a) => `
    <th class="bm-acc ${a.kind}">
      ${a.kind === "own" ? "" : `<span class="bm-acc-logo">${companyLogo(a.comp || { name: a.name })}</span>`}
      <span class="bm-acc-name">${escapeHtml(a.name).replace(/\n/g, "<br>")}</span>
      <span class="bm-acc-fol">フォロワー：${a.stats.followers ? a.stats.followers.toLocaleString() : "—"}</span>
    </th>`;

  const table = `
    <div class="bm-table-wrap">
      <table class="bm-table">
        <thead><tr>
          <th class="bm-metric-h">比較項目<button class="bm-edit-mini">編集</button></th>
          ${accounts.map(headCell).join("")}
          <th class="bm-insight-h">自社との<br>比較インサイト</th>
        </tr></thead>
        <tbody>
          ${rows.map((r) => `
            <tr>
              <td class="bm-metric"><span class="bm-no">${r.no}</span>${escapeHtml(r.label)}</td>
              ${accounts.map((a) => `<td>${r.cell(a)}</td>`).join("")}
              ${(() => {
    const bi = bmRowInsight(r.no);
    if (bmInsightEdit === r.no) {
      return `<td class="bm-insight editing"><textarea data-path="benchmarkNotes.rows.${r.no}" rows="3" placeholder="自動アドバイスを上書き">${escapeHtml((state.benchmarkNotes.rows || {})[r.no] || bi.text || "")}</textarea><button class="bm-color-done" data-bm-insight-done title="完了">${icon("check")}</button></td>`;
    }
    return `<td class="bm-insight ${bi.cls}"><span>${escapeHtml(bi.text || "")}</span><button class="ca-edit-btn bm-insight-edit" data-bm-insight-edit="${r.no}" title="このアドバイスを編集">${icon("pencil")}</button></td>`;
  })()}
            </tr>`).join("")}
        </tbody>
      </table>
    </div>`;

  const compChips = compIds.map((id) => { const c = state.competitors.find((x) => x.id === id); return `<span class="bm-chip">${escapeHtml(c ? c.name : "—")}<button data-bm-remove="${id}">${icon("close")}</button></span>`; }).join("");
  const addable = state.competitors.filter((c) => !compIds.includes(c.id));

  const setup = `
    <section class="cpi-panel bm-setup">
      <div class="cpi-panel-head">${'<span class="cpi-badge" style="background:#5168f6">≒</span>'}<h3>比較設定</h3></div>
      <div class="bm-setup-grid">
        <label class="bm-fld"><span>比較SNS</span><select data-bm-sns>${activeChannelNames().map((c) => `<option ${bmSns === c ? "selected" : ""}>${escapeHtml(c)}</option>`).join("")}</select></label>
        <label class="bm-fld"><span>自社アカウント</span><select disabled><option>${escapeHtml(ownName)}</option></select></label>
        <label class="bm-fld bm-fld-wide"><span>競合企業（最大5社まで）</span><div class="bm-chips">${compChips}${addable.length && compIds.length < 5 ? `<select data-bm-add><option value="">＋ 追加</option>${addable.map((c) => `<option value="${c.id}">${escapeHtml(c.name)}</option>`).join("")}</select>` : ""}</div></label>
        <label class="bm-fld"><span>集計方法</span><select data-bm-agg><option ${bmAgg === "平均値" ? "selected" : ""}>平均値</option><option ${bmAgg === "中央値" ? "selected" : ""}>中央値</option><option ${bmAgg === "合計" ? "selected" : ""}>合計</option></select></label>
      </div>
    </section>`;

  const bn = state.benchmarkNotes;
  const hintLines = (bn.hint || "").split("\n").filter(Boolean);
  const sidebar = `
    <aside class="bm-side">
      <section class="cpi-panel">
        <h3 class="bm-side-h">優先的に改善すべきポイント</h3>
        <p class="panel-note">改善の優先度が高い項目を選択してください（最大5つ）</p>
        <ul class="bm-points">
          ${BM_POINTS.map((pt) => `<li><label class="bm-point"><input type="checkbox" data-bm-point="${pt.key}" ${bmPriority.includes(pt.key) ? "checked" : ""}><span>${escapeHtml(pt.label)}</span></label><span class="bm-pri bm-pri-${pt.pri === "高" ? "hi" : pt.pri === "中" ? "mid" : "lo"}">${pt.pri}</span></li>`).join("")}
        </ul>
      </section>
      <section class="cpi-panel">
        <div class="bm-side-head"><h3 class="bm-side-h">インサイト（総合）</h3>${bmNoteEdit === "insight" ? "" : `<button class="ca-edit-btn" data-bm-note-edit="insight" title="編集">${icon("pencil")}</button>`}</div>
        ${bmNoteEdit === "insight"
          ? `<div class="cpi-ta-wrap"><textarea data-path="benchmarkNotes.insight" maxlength="500" rows="5" placeholder="自社と競合の総合的な所見">${escapeHtml(bn.insight)}</textarea><span class="cpi-count">${(bn.insight || "").length} / 500</span></div><div class="bm-note-foot"><button class="cmp-btn-primary bm-note-save" data-bm-note-save>${icon("check")}<span>保存して更新</span></button></div>`
          : `<p class="bm-note-text">${bn.insight ? escapeHtml(bn.insight) : "<span class='muted'>未記入</span>"}</p>`}
      </section>
      <section class="cpi-panel">
        <div class="bm-side-head"><h3 class="bm-side-h">改善ヒント（総合）</h3>${bmNoteEdit === "hint" ? "" : `<button class="ca-edit-btn" data-bm-note-edit="hint" title="編集">${icon("pencil")}</button>`}</div>
        ${bmNoteEdit === "hint"
          ? `<div class="cpi-ta-wrap"><textarea data-path="benchmarkNotes.hint" maxlength="500" rows="5" placeholder="1行に1つの改善ヒント">${escapeHtml(bn.hint)}</textarea><span class="cpi-count">${(bn.hint || "").length} / 500</span></div><div class="bm-note-foot"><button class="cmp-btn-primary bm-note-save" data-bm-note-save>${icon("check")}<span>保存して更新</span></button></div>`
          : `<ul class="bm-hints">${hintLines.map((l) => `<li>${escapeHtml(l)}</li>`).join("") || "<li class='muted'>未記入</li>"}</ul>`}
      </section>
      <section class="cpi-panel bm-action-cta">
        <h3 class="bm-side-h">改善アクションへ</h3>
        <p class="panel-note">選択した改善ポイントから、改善タスクを自動で作成します。</p>
        <button class="cmp-btn-primary bm-create-btn" data-bm-create>${icon("plus")}<span>改善アクションを作成</span></button>
      </section>
    </aside>`;

  return `
    <div class="bm">
      <div class="bm-main">
        ${setup}
        ${table}
        <p class="bm-legend"><span class="bm-lg bm-comp">■</span>赤：自社より優れている項目　<span class="bm-lg bm-own">■</span>緑：自社が優れている項目　<span class="bm-lg bm-eq">■</span>青：同水準</p>
      </div>
      ${sidebar}
    </div>`;
}

/** ベンチマーク：選択中の改善ポイントから改善タスク（reviewItems, source="競合分析"）を一括作成。 */
function bmCreateActions() {
  if (!bmPriority.length) { showSaved("改善ポイントを選択してください"); return; }
  const map = {
    "theme-success": { title: "テーマに成功事例を増やす", kpi: ["保存率"], reflect: ["投稿戦略", "投稿案"] },
    "reel-ratio": { title: "リールの投稿比率を上げる", kpi: ["リーチ"], reflect: ["投稿戦略", "デザイン管理"] },
    "time": { title: "投稿時間帯を最適化する", kpi: ["リーチ"], reflect: ["投稿管理"] },
    "cta": { title: "CTAを強化（無料相談への誘導）", kpi: ["CV"], reflect: ["投稿戦略", "デザイン管理"] },
    "design": { title: "デザインのインパクトを強化", kpi: ["エンゲージメント"], reflect: ["デザイン管理"] },
    "icon": { title: "図解・アイコンの活用を強化", kpi: ["保存率"], reflect: ["デザイン管理"] },
    "hashtag": { title: "ハッシュタグ数を増やす", kpi: ["リーチ"], reflect: ["投稿管理"] },
    "campaign": { title: "キャンペーンを増やす", kpi: ["CV"], reflect: ["キャンペーン"] },
    "text": { title: "文字量を増やす", kpi: ["エンゲージメント"], reflect: ["投稿案"] },
  };
  let added = 0;
  bmPriority.forEach((k) => {
    const m = map[k]; if (!m) return;
    const pri = BM_POINTS.find((p) => p.key === k);
    state.reviewItems.push({
      id: generateId("rv"), title: `ベンチマーク：${m.title}`, kpi: m.kpi,
      priority: pri && pri.pri === "高" ? "P1" : pri && pri.pri === "中" ? "P2" : "P3",
      owner: "", due: "", status: "未着手", relatedSns: [bmSns], relatedPosts: "",
      source: "競合分析", reflect: m.reflect, reviewDate: "", completedAt: "", nextAction: "",
    });
    added += 1;
  });
  persist();
  activeTab = "analytics";
  activeAnalyticsTab = "goals";
  showSaved(`${added}件の改善アクションを改善管理に追加しました`);
  render();
}

function competitorPlaceholderSubView(id) {
  const meta = {
    companies: { title: "競合企業管理", note: "競合企業のマスタ（会社名・業界・各SNS・優先度・担当・監視ON/OFF）を登録します。ここで登録した企業を「競合投稿入力」で選びます。" },
    input: { title: "競合投稿入力", note: "競合の投稿を1件ずつ登録し、公開数値とコンテンツ分析（目的／フック／CTA／成功要因／真似したい点／改善アイデア等）を蓄積します。ダッシュボード・競合分析・ベンチマークの集計元です。" },
    analysis: { title: "競合分析", note: "蓄積した投稿を一覧・詳細で分析し、改善アクションを「目標・改善（改善管理）」へ追加します。" },
    benchmark: { title: "ベンチマーク", note: "自社 vs 競合を、テーマ・形式・CTA・投稿時間などの構成比で比較します。" },
  }[id] || { title: "", note: "" };
  return `
    <section class="cmp-placeholder panel pad">
      <div class="cmp-ph-badge">${icon("settings")}</div>
      <h3>${escapeHtml(meta.title)}</h3>
      <p class="panel-note">${escapeHtml(meta.note)}</p>
      <p class="cmp-ph-tag">この画面は次のステップで実装します（現在はダッシュボードのデータ元として内部データが稼働中）。</p>
    </section>
  `;
}

function competitorDashboardSubView() {
  const posts = state.competitorPosts;
  const analyzedPosts = posts.filter((p) => p.analyzed);
  const unanalyzedPosts = posts.filter((p) => !p.analyzed);
  const improvePosts = posts.filter((p) => (p.improveIdea || "").trim());
  const companies = state.competitors;
  const benchCompanies = companies.filter((c) => c.benchmark);

  const kThisWeek = cmpAddedThisWeek(posts, "createdAt");
  const kPrevWeek = cmpAddedPrevWeek(posts, "createdAt");
  const kAnalyzedNew = cmpAddedThisWeek(analyzedPosts, "analyzedAt");
  const kUnanalyzedNew = cmpAddedThisWeek(unanalyzedPosts, "createdAt");

  const kpis = [
    { icon: "building", tone: "blue", label: "管理競合企業", value: companies.length, unit: "社", delta: cmpAddedThisWeek(companies, "createdAt"), du: "社" },
    { icon: "doc", tone: "green", label: "分析済み投稿", value: analyzedPosts.length, unit: "件", delta: kAnalyzedNew, du: "件" },
    { icon: "plus", tone: "orange", label: "今週追加", value: kThisWeek, unit: "件", delta: kThisWeek - kPrevWeek, du: "件" },
    { icon: "target", tone: "violet", label: "ベンチマーク企業", value: benchCompanies.length, unit: "社", delta: cmpAddedThisWeek(benchCompanies, "createdAt"), du: "社" },
    { icon: "clipboard", tone: "amber", label: "未分析投稿", value: unanalyzedPosts.length, unit: "件", delta: kUnanalyzedNew - kAnalyzedNew, du: "件" },
    { icon: "lightbulb", tone: "red", label: "改善候補", value: improvePosts.length, unit: "件", delta: cmpAddedThisWeek(improvePosts, "createdAt"), du: "件" },
  ];

  const deltaHtml = (d, unit) => {
    const cls = d > 0 ? "up" : d < 0 ? "down" : "flat";
    const sign = d > 0 ? "+" : d < 0 ? "-" : "±";
    const arrow = d > 0 ? " ↑" : d < 0 ? " ↓" : "";
    return `<span class="cmp-kpi-delta"><em>前週比</em> <b class="${cls}">${sign}${Math.abs(d)} ${unit}${arrow}</b></span>`;
  };

  const kpiCards = kpis.map((k) => `
    <article class="cmp-kpi">
      <div class="cmp-kpi-top">
        <span class="cmp-kpi-ico ${k.tone}">${icon(k.icon)}</span>
        <span class="cmp-kpi-label">${escapeHtml(k.label)}</span>
      </div>
      <div class="cmp-kpi-value"><strong>${k.value.toLocaleString()}</strong><small>${k.unit}</small></div>
      ${deltaHtml(k.delta, k.du)}
    </article>
  `).join("");

  const donut = (title, field, jumpLabel, shortMap = null) => {
    const bd = cmpBreakdown(field, shortMap);
    const segs = bd.rows.map((r) => ({ pct: r.pct, color: r.color }));
    const sum = segs.reduce((s, x) => s + x.pct, 0);
    if (sum < 99.5) segs.push({ pct: 100 - sum, color: "#eef1f7" });
    return `
      <article class="cmp-donut-card">
        <h3>${escapeHtml(title)}</h3>
        ${bd.total ? `
          <div class="cmp-donut-body">
            <div class="cmp-donut" style="background:${conicGradient(segs)}">
              <div><small>合計</small><strong>${bd.total.toLocaleString()}件</strong></div>
            </div>
            <ul class="cmp-legend">
              ${bd.rows.map((r) => `
                <li>
                  <span class="cmp-lg-name"><i style="background:${r.color}"></i>${escapeHtml(r.name)}</span>
                  <span class="cmp-lg-pct">${r.pct.toFixed(1)}%</span>
                  <span class="cmp-lg-cnt">(${r.count.toLocaleString()}件)</span>
                </li>`).join("")}
            </ul>
          </div>
          <button class="cmp-donut-more" data-competitor-tab="input">${escapeHtml(jumpLabel)} ${icon("chevron")}</button>
        ` : `<p class="panel-note cmp-donut-empty">競合投稿を登録すると集計されます</p>`}
      </article>
    `;
  };

  const hm = cmpHeatmap();
  let best = { d: 0, h: 0, v: 0 };
  hm.grid.forEach((row, di) => row.forEach((v, hi) => { if (v > best.v) best = { d: di, h: hi, v }; }));
  const heatCaption = hm.max
    ? `${hm.days[best.d]}曜の${best.h}〜${Math.min(best.h + 3, 23)}時が特に活発です。競合投稿の多い曜日・時間帯を意識して自社の投稿時間を調整しましょう。`
    : "競合投稿を登録すると、投稿が多い曜日・時間帯が可視化されます。";
  const hourTicks = [0, 3, 6, 9, 12, 15, 18, 21];
  const heatCells = hm.days.map((dLabel, di) => `
    <div class="cmp-heat-row">
      <span class="cmp-heat-day">${dLabel}</span>
      <div class="cmp-heat-cells">
        ${hm.grid[di].map((v) => {
          const a = hm.max ? v / hm.max : 0;
          const bg = v ? `rgba(76,110,245,${(0.14 + 0.86 * a).toFixed(3)})` : "#eef1f7";
          return `<span class="cmp-heat-cell" style="background:${bg}" title="${dLabel}曜 ${v}件"></span>`;
        }).join("")}
      </div>
    </div>`).join("");

  const insightRows = state.competitorInsights.map((ins, i) => (
    cmpInsightEdit === i ? `
      <li class="cmp-insight editing">
        ${textarea(`competitorInsights.${i}.text`, ins.text, 2)}
        <div class="cmp-insight-actions">
          <button class="cmp-insight-btn danger" data-cmp-insight-delete="${i}">${icon("close")}</button>
          <button class="cmp-insight-btn save" data-cmp-insight-save="${i}">${icon("check")}<span>保存</span></button>
        </div>
      </li>`
    : `
      <li class="cmp-insight">
        <p>${escapeHtml(ins.text)}</p>
        <button class="cmp-insight-edit" data-cmp-insight-edit="${i}" aria-label="編集">${icon("pencil")}</button>
      </li>`
  )).join("");

  return `
    <div class="cmp-dash">
      <div class="cmp-kpi-row">${kpiCards}</div>

      <div class="cmp-donut-row">
        ${donut("よく使われるテーマ TOP5", "theme", "すべてのテーマを見る", competitorThemeShort)}
        ${donut("よく使われる形式 TOP5", "format", "すべての形式を見る")}
        ${donut("よく使われるCTA TOP5", "cta", "すべてのCTAを見る")}
      </div>

      <div class="cmp-bottom">
        <section class="cmp-heat-card">
          <div class="cmp-heat-head">
            <h3>投稿時間ヒートマップ <span>（曜日 × 時間帯）</span></h3>
            <div class="cmp-heat-legend"><small>投稿数</small><div class="cmp-heat-scalebar"><em>多</em><span></span><em>少</em></div></div>
          </div>
          <div class="cmp-heat-grid">
            ${heatCells}
            <div class="cmp-heat-axis">
              <span class="cmp-heat-day"></span>
              <div class="cmp-heat-ticks">${hourTicks.map((h) => `<span>${h}時</span>`).join("")}</div>
            </div>
          </div>
          <p class="cmp-heat-caption">${icon("target")}${escapeHtml(heatCaption)}</p>
        </section>

        <section class="cmp-insight-card">
          <div class="cmp-insight-head"><h3>競合インサイト <span>（手動メモ）</span></h3></div>
          <ul class="cmp-insight-list">${insightRows}</ul>
          <button class="cmp-insight-add" data-action="cmp-add-insight">${icon("plus")}新しいインサイトを追加</button>
        </section>
      </div>

      <div class="cmp-datasource">データソース：<strong>競合投稿入力</strong><span>競合投稿入力で登録されたデータをもとに自動集計しています。数値は登録済みデータの集計値です。</span></div>
    </div>
  `;
}

/* ============================================================
   キャンペーンタブ（campaignOps）
   id-based の state.campaigns を正とし、投稿(投稿管理)・実績(分析)・
   コメント・競合ベンチマーク・改善メモと相互連携する統合ダッシュボード。
   ============================================================ */

const CO_STATUS_OPTIONS = ["進行中", "予定", "終了", "企画中", "完了"];
const CO_PURPOSE_OPTIONS = ["認知拡大・新規集客", "CV獲得", "リード獲得", "信頼形成・認知拡大", "認知拡大", "認知拡大・CV獲得", "ファン化・エンゲージメント"];
const CO_ROAS_VALUE_PER_CV = 30000; // 推定ROASの前提：1CV(無料相談→契約)あたりの想定価値（円）。ツールチップで明示
const coChannelColors = {
  Instagram: "#e1306c", X: "#111827", Facebook: "#1877f2", LinkedIn: "#0a66c2",
  Threads: "#111827", TikTok: "#111827", "YouTube Shorts": "#ff0000", Note: "#41c9b4", LINE: "#06c755",
};
function coChannelColor(channel) { return coChannelColors[channel] || "#94a3b8"; }
function coPad(n) { return String(n).padStart(2, "0"); }
function coPct(cur, tgt) { return tgt > 0 ? Math.round((numberValue(cur) / numberValue(tgt)) * 100) : 0; }

/** 選択中キャンペーン（未選択なら先頭）。 */
function coActiveCampaign() {
  const list = state.campaigns || [];
  if (!list.length) return null;
  return list.find((c) => c.id === activeCampaignId) || list[0];
}
function coCampaignIndex(id) { return (state.campaigns || []).findIndex((c) => c.id === id); }
/** キャンペーンに紐づく投稿（投稿管理から取得）。 */
function coCampaignPosts(c) {
  if (!c) return [];
  return state.posts.filter((p) => p.campaignId === c.id);
}
/** キャンペーンの実績集計（分析・レポート＞データ入力の metrics から自動集計）。 */
function coCampaignMetrics(c) {
  const ids = new Set(coCampaignPosts(c).map((p) => p.id));
  const rows = state.metrics.filter((m) => m.postId && ids.has(m.postId));
  const sum = (key) => rows.reduce((acc, r) => acc + numberValue(r[key]), 0);
  const engagement = rows.reduce((acc, r) => acc + numberValue(r.likes) + numberValue(r.commentsCount) + numberValue(r.saves) + numberValue(r.shares), 0);
  return {
    rows, reach: sum("reach"), engagement, saves: sum("saves"), clicks: sum("clicks"),
    profileAccess: sum("profileAccess"), conversions: sum("conversions"), contracts: sum("contracts"),
  };
}
/** キャンペーンKPI（目標＝キャンペーン設定、現在＝metrics自動集計、達成率）。 */
function coKpiRows(c) {
  const m = coCampaignMetrics(c);
  const t = c.kpiTargets || {};
  return [
    { key: "reach", icon: "send", label: "Reach（表示）", target: t.reach, current: m.reach },
    { key: "engagement", icon: "heart", label: "Engagement（反応）", target: t.engagement, current: m.engagement },
    { key: "saves", icon: "bookmark", label: "保存", target: t.saves, current: m.saves },
    { key: "clicks", icon: "cursor", label: "クリック", target: t.clicks, current: m.clicks },
    { key: "profileAccess", icon: "users", label: "プロフィール遷移", target: t.profileAccess, current: m.profileAccess },
    { key: "conversions", icon: "target", label: "無料相談（CV）", target: t.conversions, current: m.conversions },
    { key: "contracts", icon: "check", label: "契約", target: t.contracts, current: m.contracts },
  ];
}
/** 達成率（各KPIを100%上限で平均）。一覧・KPIカードで共通利用。 */
function coAchievement(c) {
  const rows = coKpiRows(c);
  const valid = rows.filter((r) => numberValue(r.target) > 0);
  if (!valid.length) return 0;
  const total = valid.reduce((acc, r) => acc + Math.min(100, coPct(r.current, r.target)), 0);
  return Math.round(total / valid.length);
}
/** キャンペーンに紐づくコメント（campaignId 直結＋投稿経由）を状況別に集計。 */
function coCampaignComments(c) {
  const ids = new Set(coCampaignPosts(c).map((p) => p.id));
  const list = (state.comments || []).filter((cm) => !cm.archived && (cm.campaignId === c.id || (cm.postId && ids.has(cm.postId))));
  const by = (stage) => list.filter((cm) => commentStage(cm) === stage).length;
  return { total: list.length, unresolved: by("未対応"), doing: by("対応中"), done: by("対応済み") };
}
function coBar(pct) {
  const w = Math.max(0, Math.min(100, pct));
  return `<span class="co-bar"><span class="co-bar-fill" style="width:${w}%"></span></span>`;
}
function coStatusPill(status) {
  const tone = status === "進行中" ? "green" : status === "終了" || status === "完了" ? "gray" : status === "予定" ? "blue" : "amber";
  return `<span class="co-pill co-pill-${tone}">${escapeHtml(status || "—")}</span>`;
}
function coPeriodLabel(c) {
  const fmt = (d) => (d ? d.replace(/-/g, "/") : "—");
  return `${fmt(c.startDate)}<br>〜${fmt(c.endDate)}`;
}
function coMoney(v) { return numberValue(v).toLocaleString("ja-JP"); }
/** 投稿日を「MM/DD HH:MM」に簡潔化（投稿一覧テーブルで列幅を抑える）。 */
function coPostDate(p) {
  const raw = String(p.publishAt || "").trim();
  if (!raw) return "未設定";
  const m = raw.match(/(\d{4})-(\d{2})-(\d{2})(?:T(\d{1,2}):(\d{2}))?/);
  if (!m) return raw;
  return `${m[2]}/${m[3]}${m[4] ? ` ${m[4].padStart(2, "0")}:${m[5]}` : ""}`;
}

function campaignOpsView() {
  const active = coActiveCampaign();
  return `
    <section class="section co-section ${activeTab === "campaignOps" ? "active" : ""}" data-section="campaignOps">
      ${coHeader()}
      ${coKpiCards()}
      <div class="co-grid">
        <div class="co-col co-col-left">${coListPanel()}</div>
        <div class="co-col co-col-center">${active ? coDetailPanel(active) : coEmpty("キャンペーンがありません。「＋ キャンペーンを作成」から追加してください。")}</div>
        <div class="co-col co-col-right">${active ? coRightColumn(active) : ""}</div>
      </div>
      ${coActionBar(active)}
    </section>
  `;
}

function coEmpty(msg) { return `<div class="co-card co-empty">${escapeHtml(msg)}</div>`; }

/** ヘッダー期間フィルタの窓。全期間は null（＝絞り込みなし）。一覧の期間重なり判定に使う。 */
function coPeriodWindow(preset = coPeriodPreset) {
  const now = new Date();
  const startOf = (d) => { const x = new Date(d); x.setHours(0, 0, 0, 0); return x; };
  const endOf = (d) => { const x = new Date(d); x.setHours(23, 59, 59, 999); return x; };
  const fmt = (d) => `${d.getFullYear()}/${coPad(d.getMonth() + 1)}/${coPad(d.getDate())}`;
  let start; let end;
  if (preset === "今月") { start = startOf(new Date(now.getFullYear(), now.getMonth(), 1)); end = endOf(new Date(now.getFullYear(), now.getMonth() + 1, 0)); }
  else if (preset === "先月") { start = startOf(new Date(now.getFullYear(), now.getMonth() - 1, 1)); end = endOf(new Date(now.getFullYear(), now.getMonth(), 0)); }
  else if (preset === "過去30日") { start = startOf(new Date(now.getFullYear(), now.getMonth(), now.getDate() - 29)); end = endOf(now); }
  else if (preset === "今四半期") { const q = Math.floor(now.getMonth() / 3); start = startOf(new Date(now.getFullYear(), q * 3, 1)); end = endOf(new Date(now.getFullYear(), q * 3 + 3, 0)); }
  else return null; // 全期間
  return { start, end, label: `${fmt(start)} 〜 ${fmt(end)}` };
}
/** キャンペーンの期間が窓と重なるか（どちらか未設定なら通す）。 */
function coInPeriod(c, win) {
  if (!win) return true;
  const s = c.startDate ? Date.parse(c.startDate + "T00:00:00") : null;
  const e = c.endDate ? Date.parse(c.endDate + "T23:59:59") : null;
  if (s === null && e === null) return true;
  const cs = s ?? e; const ce = e ?? s;
  return ce >= win.start.getTime() && cs <= win.end.getTime();
}

function coHeader() {
  const list = state.campaigns || [];
  const win = coPeriodWindow();
  let rangeLabel;
  if (win) rangeLabel = win.label;
  else {
    const starts = list.map((c) => c.startDate).filter(Boolean).sort();
    const ends = list.map((c) => c.endDate).filter(Boolean).sort();
    rangeLabel = starts.length ? `${starts[0].replace(/-/g, "/")} 〜 ${(ends[ends.length - 1] || starts[starts.length - 1]).replace(/-/g, "/")}` : "全期間";
  }
  const presets = ["全期間", "今四半期", "今月", "先月", "過去30日"];
  return `
    <div class="co-head">
      <div class="co-head-left">
        <div class="co-title"><h2>キャンペーン</h2><span class="co-info" title="キャンペーンを一元管理し、投稿・実績・コメント・競合・改善と連携します">${icon("info")}</span></div>
        <p class="co-sub">キャンペーンを一元管理し、成果の最大化を目指しましょう。</p>
      </div>
      <div class="co-head-right">
        <label class="co-period" title="期間で一覧を絞り込みます">${icon("calendar")}<span>期間：</span><select data-co-period-preset>${presets.map((p) => `<option ${coPeriodPreset === p ? "selected" : ""}>${p}</option>`).join("")}</select><strong>${rangeLabel}</strong></label>
        <button class="co-btn-ghost" data-action="co-export">${icon("download")}<span>エクスポート</span></button>
        <button class="co-btn-primary" data-action="co-add-campaign">${icon("plus")}<span>キャンペーンを作成</span></button>
      </div>
    </div>
  `;
}

function coKpiCards() {
  const list = state.campaigns || [];
  const mk = monthKey(new Date());
  const prevDate = new Date(); prevDate.setMonth(prevDate.getMonth() - 1);
  const pmk = monthKey(prevDate);
  const monthOf = (d) => (d || "").slice(0, 7);
  const active = list.filter((c) => c.status === "進行中");
  const startsThis = list.filter((c) => monthOf(c.startDate) === mk).length;
  const startsPrev = list.filter((c) => monthOf(c.startDate) === pmk).length;
  const endsThis = list.filter((c) => monthOf(c.endDate) === mk).length;
  const endsPrev = list.filter((c) => monthOf(c.endDate) === pmk).length;
  const avgAch = active.length ? Math.round(active.reduce((a, c) => a + coAchievement(c), 0) / active.length) : 0;
  // 今月公開の投稿数・CV（分析metricsと連携）
  const postMonth = (p) => publishDateKey(p).slice(0, 7);
  const postsThis = state.posts.filter((p) => postMonth(p) === mk);
  const postsPrev = state.posts.filter((p) => postMonth(p) === pmk);
  const cvOf = (posts) => { const ids = new Set(posts.map((p) => p.id)); return state.metrics.filter((m) => ids.has(m.postId)).reduce((a, m) => a + numberValue(m.conversions), 0); };
  const cvThis = cvOf(postsThis); const cvPrev = cvOf(postsPrev);
  // 推定ROAS（前提を明示）：総CV×想定単価 ÷ 総予算
  const totalBudget = list.reduce((a, c) => a + numberValue(c.budget), 0);
  const totalCv = list.reduce((a, c) => a + coCampaignMetrics(c).conversions, 0);
  const roas = totalBudget > 0 ? Math.round((totalCv * CO_ROAS_VALUE_PER_CV) / totalBudget * 100) : 0;
  const delta = (n) => (n > 0 ? `先月比 +${n}` : n < 0 ? `先月比 ${n}` : "先月比 ±0");
  const cards = [
    { icon: "flag", tone: "indigo", label: "進行中キャンペーン", value: active.length, sub: `すべて ${list.length} 件` },
    { icon: "calendar", tone: "green", label: "今月開始", value: startsThis, sub: delta(startsThis - startsPrev) },
    { icon: "calendar", tone: "orange", label: "今月終了", value: endsThis, sub: delta(endsThis - endsPrev) },
    { icon: "target", tone: "violet", label: "平均達成率", value: `${avgAch}%`, sub: "目標 75%" },
    { icon: "send", tone: "blue", label: "今月の投稿数", value: postsThis.length, sub: delta(postsThis.length - postsPrev.length) },
    { icon: "users", tone: "teal", label: "コンバージョン", value: cvThis, sub: delta(cvThis - cvPrev) },
    { icon: "chart", tone: "amber", label: "ROAS（推定）", value: `${roas}%`, sub: `想定単価 ¥${CO_ROAS_VALUE_PER_CV.toLocaleString("ja-JP")}/CV`, title: "推定ROAS = 総CV × 想定単価 ÷ 総予算。想定単価は仮値です（設定で調整可）" },
  ];
  return `
    <div class="co-kpi-row">
      ${cards.map((c) => `
        <div class="co-kpi-card"${c.title ? ` title="${escapeHtml(c.title)}"` : ""}>
          <span class="co-kpi-ic co-ic-${c.tone}">${icon(c.icon)}</span>
          <div class="co-kpi-body">
            <span class="co-kpi-label">${escapeHtml(c.label)}</span>
            <strong class="co-kpi-value">${escapeHtml(String(c.value))}</strong>
            <span class="co-kpi-sub">${escapeHtml(c.sub)}</span>
          </div>
        </div>
      `).join("")}
    </div>
  `;
}

/* ① キャンペーン一覧 */
function coListPanel() {
  const kw = coSearch.trim().toLowerCase();
  const win = coPeriodWindow();
  const all = (state.campaigns || []).map((c, index) => ({ c, index }))
    .filter(({ c }) => (!kw || (c.name || "").toLowerCase().includes(kw)))
    .filter(({ c }) => (!coStatusFilter || c.status === coStatusFilter))
    .filter(({ c }) => coInPeriod(c, win));
  const pageSize = 6;
  const pages = Math.max(1, Math.ceil(all.length / pageSize));
  if (coPage > pages) coPage = pages;
  const start = (coPage - 1) * pageSize;
  const rows = all.slice(start, start + pageSize);
  const activeId = coActiveCampaign() ? coActiveCampaign().id : null;
  return `
    <div class="co-card co-list">
      ${coSectionHead("1", "キャンペーン一覧")}
      <div class="co-list-tools">
        <label class="co-search">${icon("search")}<input type="text" placeholder="キャンペーン名で検索" value="${escapeHtml(coSearch)}" data-co-search></label>
        <label class="co-select-wrap"><select data-co-status><option value="">すべてのステータス</option>${CO_STATUS_OPTIONS.map((s) => `<option ${coStatusFilter === s ? "selected" : ""}>${s}</option>`).join("")}</select></label>
      </div>
      <div class="co-list-table-wrap">
        <table class="co-list-table">
          <thead><tr><th>キャンペーン名</th><th>期間</th><th>SNS</th><th>目的</th><th>ステータス</th><th class="ta-c">投稿数</th><th class="ta-c">CV</th><th>達成率</th></tr></thead>
          <tbody>
            ${rows.length ? rows.map(({ c }) => {
              const m = coCampaignMetrics(c);
              const posts = coCampaignPosts(c).length;
              const ach = coAchievement(c);
              const on = c.id === activeId;
              return `
                <tr class="co-list-row ${on ? "is-active" : ""}" data-co-select="${escapeHtml(c.id)}">
                  <td class="co-list-name"><div class="co-list-name-in"><span class="co-radio ${on ? "on" : ""}"></span><div class="co-list-name-txt"><strong>${escapeHtml(c.name || "(名称未設定)")}</strong><small>${escapeHtml(c.hashtag || "")}</small></div></div></td>
                  <td class="co-list-period">${coPeriodLabel(c)}</td>
                  <td><span class="co-sns-mini">${(c.channels || []).slice(0, 3).map((ch) => `<img src="${socialIcon(ch)}" alt="${escapeHtml(ch)}" title="${escapeHtml(ch)}">`).join("")}${(c.channels || []).length > 3 ? `<em>+${c.channels.length - 3}</em>` : ""}</span></td>
                  <td class="co-list-goal">${escapeHtml(c.goal || "—")}</td>
                  <td>${coStatusPill(c.status)}</td>
                  <td class="ta-c">${posts}</td>
                  <td class="ta-c">${m.conversions}</td>
                  <td class="co-list-ach"><span>${ach}%</span>${coBar(ach)}</td>
                </tr>`;
            }).join("") : `<tr><td colspan="8" class="co-list-none">該当するキャンペーンがありません</td></tr>`}
          </tbody>
        </table>
      </div>
      ${pages > 1 ? `<div class="co-pager"><span>${coPage}/${pages}</span><button class="co-pg" data-co-page="prev" ${coPage <= 1 ? "disabled" : ""}>${icon("chevron")}</button><button class="co-pg co-pg-next" data-co-page="next" ${coPage >= pages ? "disabled" : ""}>${icon("chevron")}</button></div>` : ""}
    </div>
  `;
}

function coSectionHead(no, title, extra = "") {
  return `<div class="co-sec-head"><span class="co-sec-no">${no}</span><h3>${escapeHtml(title)}</h3>${extra}</div>`;
}

/* 汎用チップ（複数選択）。data-co-add / data-co-remove で編集 */
const CO_CHIP_NEW_VALUE = "__co_chip_new__";
function coChips(idx, field, values, options, emptyLabel, newKind = "") {
  const selected = values || [];
  const remaining = options.filter((o) => !selected.includes(o.value));
  const newOpt = newKind ? `<option value="${CO_CHIP_NEW_VALUE}">＋ 新規作成…</option>` : "";
  return `
    <div class="co-chips">
      ${selected.length ? selected.map((v) => {
        const opt = options.find((o) => o.value === v);
        return `<span class="co-chip">${escapeHtml(opt ? opt.label : v)}<button class="co-chip-x" data-co-remove="${field}" data-co-idx="${idx}" data-co-val="${escapeHtml(v)}" title="削除">${icon("close")}</button></span>`;
      }).join("") : `<span class="co-chip-empty">${escapeHtml(emptyLabel || "未設定")}</span>`}
      ${(remaining.length || newKind) ? `<span class="co-chip-add">${icon("plus")}<select data-co-add="${field}" data-co-idx="${idx}" data-co-new="${escapeHtml(newKind)}"><option value="">追加</option>${remaining.map((o) => `<option value="${escapeHtml(o.value)}">${escapeHtml(o.label)}</option>`).join("")}${newOpt}</select></span>` : ""}
    </div>
  `;
}

/* ② キャンペーン詳細 */
function coDetailPanel(c) {
  const idx = coCampaignIndex(c.id);
  const kpiRows = coKpiRows(c);
  const overview = c.overview || "";
  const ctaOptions = [...new Set([...(c.ctaTags || []), ...state.posts.map((p) => p.cta).filter(Boolean)])].map((v) => ({ value: v, label: v }));
  const themeOpts = [...new Set([...(c.themeNames || []), ...themeOptions])].map((v) => ({ value: v, label: v }));
  const tplOpts = state.templates.filter((t) => t.status !== "アーカイブ").map((t) => ({ value: t.id, label: t.name || "(名称未設定)" }));
  const hashOpts = state.hashtagSets.map((h) => ({ value: h.id, label: h.name || "(名称未設定)" }));
  const channelRemaining = activeChannelNames().filter((ch) => !(c.channels || []).includes(ch));
  return `
    <div class="co-card co-detail">
      ${coSectionHead("2", "キャンペーン詳細")}
      <div class="co-detail-scroll">
        <h4 class="co-block-title">基本情報</h4>
        <label class="co-field"><span>キャンペーン名</span>${input(`campaigns.${idx}.name`, c.name)}</label>
        <label class="co-field"><span>期間</span><span class="co-date-range">${icon("calendar")}${input(`campaigns.${idx}.startDate`, c.startDate, "date")}<em>〜</em>${input(`campaigns.${idx}.endDate`, c.endDate, "date")}</span></label>
        <label class="co-field"><span>SNS</span>
          <span class="co-sns-edit">
            ${(c.channels || []).map((ch) => `<span class="co-sns-tag"><img src="${socialIcon(ch)}" alt="${escapeHtml(ch)}" title="${escapeHtml(ch)}"><button class="co-chip-x" data-co-remove="channels" data-co-idx="${idx}" data-co-val="${escapeHtml(ch)}" title="削除">${icon("close")}</button></span>`).join("")}
            ${channelRemaining.length ? `<span class="co-chip-add co-sns-add">${icon("plus")}<select data-co-add="channels" data-co-idx="${idx}"><option value="">SNSを追加</option>${channelRemaining.map((ch) => `<option value="${escapeHtml(ch)}">${escapeHtml(ch)}</option>`).join("")}</select></span>` : ""}
          </span>
        </label>
        <div class="co-field-row">
          <label class="co-field"><span>目的</span>${select(`campaigns.${idx}.goal`, c.goal, [...new Set([c.goal, ...CO_PURPOSE_OPTIONS])].filter(Boolean))}</label>
          <label class="co-field"><span>ターゲット</span>${input(`campaigns.${idx}.audience`, c.audience)}</label>
        </div>
        <div class="co-field-row">
          <label class="co-field"><span>担当者</span>${select(`campaigns.${idx}.owner`, c.owner, [{ value: "", label: "未割り当て" }, ...memberNames().map((n) => ({ value: n, label: n }))])}</label>
          <label class="co-field"><span>予算 <em>(任意)</em></span><span class="co-inline-suffix">${input(`campaigns.${idx}.budget`, c.budget, "number")}<i>円</i></span></label>
          <label class="co-field"><span>ステータス</span>${select(`campaigns.${idx}.status`, c.status, CO_STATUS_OPTIONS)}</label>
        </div>

        <h4 class="co-block-title">KPI <span class="co-auto">（自動反映：分析・レポート＞データ入力）</span></h4>
        <div class="co-kpi-table">
          <div class="co-kpi-thead"><span>指標</span><span class="ta-r">目標</span><span class="ta-r">現在</span><span>達成率</span></div>
          ${kpiRows.map((r) => {
            const pct = coPct(r.current, r.target);
            return `<div class="co-kpi-line">
              <span class="co-kpi-metric">${icon(r.icon)}${escapeHtml(r.label)}</span>
              <span class="ta-r">${numberValue(r.target).toLocaleString("ja-JP")}</span>
              <span class="ta-r co-strong">${numberValue(r.current).toLocaleString("ja-JP")}</span>
              <span class="co-kpi-prog">${coBar(pct)}<em>${pct}%</em></span>
            </div>`;
          }).join("")}
        </div>
        <p class="co-note">${icon("info")} データは分析・レポートの「データ入力」から自動取得しています。</p>

        <h4 class="co-block-title">キャンペーン概要</h4>
        <div class="co-overview">${textarea(`campaigns.${idx}.overview`, overview, 3, "キャンペーンの狙い・背景を記入")}<span class="co-count">${(overview || "").length} / 500</span></div>

        <div class="co-field-row co-tags-row">
          <div class="co-field"><span>CTA <em>(投稿戦略＞CTA管理)</em></span>${coChips(idx, "ctaTags", c.ctaTags, ctaOptions, "未設定", "cta")}</div>
          <div class="co-field"><span>使用テーマ <em>(複数選択・新規可)</em></span>${coChips(idx, "themeNames", c.themeNames, themeOpts, "未設定", "theme")}</div>
        </div>
        <div class="co-field-row co-tags-row">
          <div class="co-field"><span>使用テンプレート <em>(デザイン管理から選択)</em></span>${coChips(idx, "templateIds", c.templateIds, tplOpts, "未設定")}</div>
          <div class="co-field"><span>使用ハッシュタグ <em>(デザイン管理から選択)</em></span>${coChips(idx, "hashtagSetIds", c.hashtagSetIds, hashOpts, "未設定")}</div>
        </div>
      </div>
    </div>
  `;
}

/* ③〜⑧ 右カラム */
function coRightColumn(c) {
  return `
    ${coPostsPanel(c)}
    <div class="co-right-grid">
      ${coCalendarPanel(c)}
      ${coTrendPanel(c)}
    </div>
    <div class="co-right-grid">
      ${coCommentsPanel(c)}
      ${coBenchmarkPanel(c)}
    </div>
    ${coKaizenPanel(c)}
  `;
}

/* ③ 投稿一覧（このキャンペーンの投稿） */
function coPostsPanel(c) {
  const posts = coCampaignPosts(c).slice().sort((a, b) => String(b.publishAt).localeCompare(String(a.publishAt)));
  const metricByPost = Object.fromEntries(state.metrics.map((m) => [m.postId, m]));
  return `
    <div class="co-card co-posts">
      ${coSectionHead("3", "投稿一覧", `<span class="co-sec-note">（このキャンペーンの投稿）</span><button class="co-jump" data-co-goto-posts="${escapeHtml(c.id)}" title="このキャンペーンで絞り込んで投稿管理を開く">投稿管理へ ${icon("chevron")}</button>`)}
      <div class="co-posts-table-wrap">
        <table class="co-posts-table">
          <thead><tr><th>サムネイル</th><th>投稿日</th><th>SNS</th><th>タイプ</th><th>ステータス</th><th>担当</th><th>KPI</th></tr></thead>
          <tbody>
            ${posts.length ? posts.slice(0, 6).map((p) => {
              const thumb = thumbnailSrc(p.thumbnail);
              const m = metricByPost[p.id] || {};
              const dateLabel = coPostDate(p);
              const kpiPrimary = p.channel === "YouTube Shorts" || p.channel === "TikTok" ? { l: "再生", v: numberValue(m.reach) } : p.channel === "Note" ? { l: "PV", v: numberValue(m.reach) } : { l: "保存", v: numberValue(m.saves) };
              return `
                <tr>
                  <td><span class="co-thumb ${thumb ? "" : "empty"}">${thumb ? `<img src="${escapeHtml(thumb)}" alt="" onerror="this.closest('.co-thumb').classList.add('empty')">` : icon("palette")}</span></td>
                  <td class="co-post-date">${escapeHtml(dateLabel)}</td>
                  <td><img class="co-sns-ic" src="${socialIcon(p.channel)}" alt="${escapeHtml(p.channel)}" title="${escapeHtml(p.channel)}"></td>
                  <td title="${escapeHtml(p.format || "")}">${escapeHtml((formatShortLabels && formatShortLabels[p.format]) || p.format || "—")}</td>
                  <td>${coStatusPill(p.status)}</td>
                  <td>${ownerAvatar(p.owner)}</td>
                  <td class="co-post-kpi"><span>${kpiPrimary.l} ${kpiPrimary.v.toLocaleString("ja-JP")}</span><span>CV ${numberValue(m.conversions)}</span></td>
                </tr>`;
            }).join("") : `<tr><td colspan="7" class="co-list-none">このキャンペーンに紐づく投稿はまだありません（投稿管理でキャンペーンを設定）</td></tr>`}
          </tbody>
        </table>
      </div>
    </div>
  `;
}

/* ④ カレンダー（キャンペーン期間の投稿スケジュール、編集不可） */
function coCalendarPanel(c) {
  const baseStr = coCalMonth || (c.startDate && c.startDate.slice(0, 7)) || monthKey(new Date());
  const [y, mo] = baseStr.split("-").map(Number);
  const year = y || new Date().getFullYear();
  const month = (mo || 1) - 1;
  const first = new Date(year, month, 1);
  const startWeekday = first.getDay();
  const daysInMonth = new Date(year, month + 1, 0).getDate();
  const prevDays = new Date(year, month, 0).getDate();
  const todayKeyStr = ymdKey(new Date());
  // このキャンペーンの投稿を公開日ごとに（過去・未来ともに）ドット表示
  const byDay = {};
  coCampaignPosts(c).forEach((p) => { const k = publishDateKey(p); if (k !== "未設定") (byDay[k] = byDay[k] || []).push(p.channel); });
  const cells = [];
  for (let i = 0; i < startWeekday; i += 1) cells.push({ day: prevDays - startWeekday + 1 + i, out: true });
  for (let d = 1; d <= daysInMonth; d += 1) cells.push({ day: d, key: `${year}-${coPad(month + 1)}-${coPad(d)}` });
  let nd = 1;
  while (cells.length < 42) cells.push({ day: nd++, out: true });
  const weekdays = ["日", "月", "火", "水", "木", "金", "土"];
  const totalInMonth = cells.filter((cell) => cell.key && byDay[cell.key]).reduce((a, cell) => a + byDay[cell.key].length, 0);
  const nav = `<span class="co-cal-nav"><button class="co-cal-arrow" data-co-cal="prev" title="前の月">${icon("chevron")}</button><strong>${year}年${month + 1}月</strong><button class="co-cal-arrow co-cal-next" data-co-cal="next" title="次の月">${icon("chevron")}</button></span>`;
  return `
    <div class="co-card co-cal">
      ${coSectionHead("4", "カレンダー", `${nav}`)}
      <p class="co-cal-sub">${icon("send")}この月の投稿 ${totalInMonth}件${coCalMonth ? ` ・ <button class="co-cal-reset" data-co-cal="reset">今月へ戻す</button>` : ""}</p>
      <div class="co-cal-grid">
        ${weekdays.map((w) => `<span class="co-cal-wd">${w}</span>`).join("")}
        ${cells.map((cell) => {
          const dots = (cell.key && byDay[cell.key]) || [];
          const isToday = cell.key === todayKeyStr;
          return `<span class="co-cal-day ${cell.out ? "out" : ""} ${isToday ? "today" : ""}" ${dots.length ? `title="投稿 ${dots.length}件"` : ""}>${cell.day}${dots.length ? `<span class="co-cal-dots">${dots.slice(0, 3).map((ch) => `<i style="background:${coChannelColor(ch)}"></i>`).join("")}</span>` : ""}</span>`;
        }).join("")}
      </div>
    </div>
  `;
}

/* ⑤ KPI進捗（投稿ごとの実績推移、自動反映） */
function coTrendPanel(c) {
  const posts = coCampaignPosts(c)
    .map((p) => ({ p, m: state.metrics.find((x) => x.postId === p.id) }))
    .filter((x) => x.m)
    .sort((a, b) => String(a.p.publishAt).localeCompare(String(b.p.publishAt)));
  const series = [
    { key: "reach", label: "Reach", color: "#2f6bff", get: (m) => numberValue(m.reach) },
    { key: "engagement", label: "Engagement", color: "#22c3a6", get: (m) => numberValue(m.likes) + numberValue(m.commentsCount) + numberValue(m.saves) + numberValue(m.shares) },
    { key: "saves", label: "保存", color: "#f5a623", get: (m) => numberValue(m.saves) },
    { key: "clicks", label: "クリック", color: "#7c5cff", get: (m) => numberValue(m.clicks) },
    { key: "cv", label: "CV", color: "#e0245e", get: (m) => numberValue(m.conversions) },
  ];
  const W = 260; const H = 120; const pad = 6;
  const n = posts.length;
  const chart = n >= 2 ? series.map((s) => {
    const vals = posts.map((x) => s.get(x.m));
    const max = Math.max(1, ...vals);
    const pts = vals.map((v, i) => {
      const x = pad + (i / (n - 1)) * (W - pad * 2);
      const yy = H - pad - (v / max) * (H - pad * 2);
      return `${x.toFixed(1)},${yy.toFixed(1)}`;
    }).join(" ");
    return `<polyline points="${pts}" fill="none" stroke="${s.color}" stroke-width="2" stroke-linejoin="round" stroke-linecap="round"/>`;
  }).join("") : "";
  return `
    <div class="co-card co-trend">
      ${coSectionHead("5", "KPI進捗", `<span class="co-sec-note">（自動反映）</span><button class="co-jump" data-jump="analytics">分析・レポートへ ${icon("chevron")}</button>`)}
      <div class="co-trend-body">
        <div class="co-legend">${series.map((s) => `<span><i style="background:${s.color}"></i>${escapeHtml(s.label)}</span>`).join("")}</div>
        ${n >= 2 ? `<svg class="co-trend-svg" viewBox="0 0 ${W} ${H}" preserveAspectRatio="none">${chart}</svg>` : `<div class="co-trend-empty">推移を表示するには公開済み投稿が2件以上必要です</div>`}
      </div>
    </div>
  `;
}

