/* ⑦ 競合参考（競合分析＞ベンチマークからの示唆） */
function coBenchmarkPanel(c) {
  // 競合分析タブのデータから示唆を集める：①ベンチマーク改善候補（reviewItems source=競合分析）
  // ②競合インサイト（競合投稿入力から蓄積した観察）。競合企業名も添えて「どこ発か」を明示する。
  const benchCompanies = (state.competitors || []).filter((x) => x.benchmark).map((x) => x.name).filter(Boolean);
  const fromReview = (state.reviewItems || []).filter((r) => r.source === "競合分析")
    .map((r) => ({ title: r.title, desc: r.nextAction || (r.kpi || []).join("・"), src: "改善候補" }));
  const fromInsights = (state.competitorInsights || []).map((i) => ({ title: "競合の傾向", desc: i.text, src: "競合インサイト" }));
  const items = [...fromReview, ...fromInsights].slice(0, 3);
  const srcNote = benchCompanies.length ? `ベンチマーク対象：${benchCompanies.slice(0, 3).join("・")}${benchCompanies.length > 3 ? " ほか" : ""}` : "競合分析でベンチマーク企業を設定すると精度が上がります";
  return `
    <div class="co-card co-bench">
      ${coSectionHead("7", "競合参考", `<span class="co-sec-note">（競合分析＞ベンチマーク発）</span>`)}
      <p class="co-bench-source">${icon("building")}${escapeHtml(srcNote)}</p>
      <div class="co-bench-list">
        ${items.length ? items.map((it) => `<div class="co-bench-item"><span class="co-bench-ic">${icon("compare")}</span><div><strong>${escapeHtml(it.title)}</strong><p>${escapeHtml(it.desc || "")}</p><span class="co-bench-tag">${escapeHtml(it.src)}</span></div></div>`).join("") : `<div class="co-list-none">競合分析＞競合投稿入力で競合データを登録すると、ここに示唆が表示されます</div>`}
      </div>
      <button class="co-panel-jump" data-co-goto-benchmark>競合分析（ベンチマーク）へ ${icon("chevron")}</button>
    </div>
  `;
}

