/* ============ 招待管理：データモデル ============ */
// ※ INV_STATUSES / INV_STATUS_TONE はファイル冒頭で定義済み（normalizeInvites が初期ロード時に参照するため）
function seedInvites() {
  const mk = (id, name, email, department, position, systemRole, sns, inviter, invitedAt, expiresAt, status, history, extra = {}) =>
    ({ id, name, email, department, position, systemRole, sns, inviter, invitedAt, expiresAt, status, memo: "", inviteUrl: `https://socialflow.jp/invite/${id.replace("inv-", "")}`, history, ...extra });
  return [
    mk("inv-abc123", "佐藤 花子", "sato2@theacademy.jp", "マーケティング部", "部長", "マネージャー", ["Instagram", "X", "Facebook"], "山田 太郎", "2026-08-04T10:30", "2026-08-11", "未承認",
      [{ at: "2026-08-04T10:30", label: "招待メールを送信" }, { at: "2026-08-04T10:31", label: "メールを開封" }]),
    mk("inv-bcd234", "鈴木 健一", "suzuki2@theacademy.jp", "デザイン部", "デザイナー", "編集者", ["Instagram", "X"], "田中 美咲", "2026-08-03T15:20", "2026-08-10", "未承認",
      [{ at: "2026-08-03T15:20", label: "招待メールを送信" }]),
    mk("inv-cde345", "小林 裕也", "kobayashi2@theacademy.jp", "マーケティング部", "アナリスト", "閲覧者", ["X"], "山田 太郎", "2026-07-10T09:15", "2026-07-17", "期限切れ",
      [{ at: "2026-07-10T09:15", label: "招待メールを送信" }, { at: "2026-07-17T00:00", label: "有効期限切れ" }]),
    mk("inv-def456", "髙橋 奈々", "takahashi2@theacademy.jp", "営業部", "営業担当", "編集者", ["Instagram", "X"], "佐藤 花子", "2026-07-05T11:40", "2026-07-12", "取消済み",
      [{ at: "2026-07-05T11:40", label: "招待メールを送信" }, { at: "2026-07-06T09:00", label: "招待を取消" }]),
    mk("inv-efg567", "伊藤 翔", "ito2@theacademy.jp", "マーケティング部", "マネージャー", "マネージャー", ["Instagram", "X", "LinkedIn"], "田中 美咲", "2026-08-01T14:00", "2026-08-08", "承認済み",
      [{ at: "2026-08-01T14:00", label: "招待メールを送信" }, { at: "2026-08-01T14:20", label: "メールを開封" }, { at: "2026-08-02T09:12", label: "招待リンクをクリック" }, { at: "2026-08-02T09:15", label: "招待を承認" }], { approvedAt: "2026-08-02T09:15" }),
    mk("inv-fgh678", "山本 将也", "yamamoto@theacademy.jp", "デザイン部", "デザイナー", "編集者", ["Instagram"], "佐藤 花子", "2026-07-28T16:30", "2026-08-04", "承認済み",
      [{ at: "2026-07-28T16:30", label: "招待メールを送信" }, { at: "2026-07-29T10:02", label: "招待を承認" }], { approvedAt: "2026-07-29T10:02" }),
    mk("inv-ghi789", "渡辺 翔太", "watanabe@theacademy.jp", "マーケティング部", "コンテンツ担当", "編集者", ["X"], "山田 太郎", "2026-06-20T13:50", "2026-06-27", "期限切れ",
      [{ at: "2026-06-20T13:50", label: "招待メールを送信" }, { at: "2026-06-27T00:00", label: "有効期限切れ" }]),
    mk("inv-hij890", "中村 美咲", "nakamura@theacademy.jp", "マーケティング部", "アナリスト", "閲覧者", ["Instagram"], "田中 美咲", "2026-06-15T10:10", "2026-06-22", "期限切れ",
      [{ at: "2026-06-15T10:10", label: "招待メールを送信" }, { at: "2026-06-22T00:00", label: "有効期限切れ" }]),
  ];
}
function normalizeInvites(nextInvites, baseInvites) {
  const seed = baseInvites || seedInvites();
  // 旧既定シード（inv-1〜inv-5・氏名なし）のまま未編集なら、新しいデモデータへ移行する
  const isLegacyDefault = Array.isArray(nextInvites) && nextInvites.length > 0
    && nextInvites.every((v) => /^inv-\d+$/.test(String(v.id || "")) && !v.name);
  const list = (Array.isArray(nextInvites) && nextInvites.length && !isLegacyDefault) ? nextInvites : seed;
  return list.map((v) => {
    const id = v.id || generateId("inv");
    return {
      id,
      name: v.name || "",
      email: v.email || "",
      department: v.department || "",
      position: v.position || "",
      systemRole: v.systemRole || "編集者",
      sns: Array.isArray(v.sns) ? v.sns : [],
      inviter: v.inviter || "",
      invitedAt: v.invitedAt || "",
      expiresAt: v.expiresAt || "",
      status: INV_STATUSES.includes(v.status) ? v.status : "未承認",
      memo: v.memo || "",
      inviteUrl: v.inviteUrl || `https://socialflow.jp/invite/${String(id).replace("inv-", "")}`,
      approvedAt: v.approvedAt || "",
      history: Array.isArray(v.history) ? v.history : [],
    };
  });
}
/** 招待メールが未開封のまま残っている＝再送が必要、と判定する。 */
function invNeedsResend(v) { return v.status === "未承認" && !(v.history || []).some((h) => /開封|クリック/.test(h.label)); }
function invKpi() {
  const list = state.invites || [];
  const thisMonth = monthKey();
  return {
    pending: list.filter((v) => v.status === "未承認").length,
    approvedThisMonth: list.filter((v) => v.status === "承認済み" && v.approvedAt && v.approvedAt.slice(0, 7) === thisMonth).length,
    expired: list.filter((v) => v.status === "期限切れ").length,
    resend: list.filter(invNeedsResend).length,
  };
}

/* ============ 権限ゲート（ロール・権限で設定した内容を実際に効かせる） ============ */
/** ログイン中ユーザーの systemRole に対応するロール定義。見つからなければ null（＝制限しない）。 */
function permCurrentRole() {
  const me = teamCurrentMember();
  if (!me) return null;
  return (state.roles || []).find((r) => r.name === me.systemRole) || null;
}
/** タブ×権限の判定。ロール未設定・対応表に無いタブ・ゲート無効時は許可（アプリを締め出さない）。 */
function can(tabId, permName) {
  if (!permGateEnabled) return true;
  const role = permCurrentRole();
  if (!role) return true;
  if (role.status && role.status !== "有効") return true;
  const label = PERM_TAB_LABEL[tabId];
  if (!label) return true;
  const col = RP_PERMS.indexOf(permName);
  if (col < 0) return true;
  const row = (role.perms && role.perms[label]) || null;
  if (!row) return true;
  return !!row[col];
}
function canView(tabId) { return can(tabId, "閲覧"); }
function canEdit(tabId) { return can(tabId, "編集") || can(tabId, "管理"); }
function canCreate(tabId) { return can(tabId, "作成") || can(tabId, "管理"); }
function canDelete(tabId) { return can(tabId, "削除") || can(tabId, "管理"); }
function canApprove(tabId) { return can(tabId, "承認") || can(tabId, "管理"); }
function canExport(tabId) { return can(tabId, "エクスポート") || can(tabId, "管理"); }

/** 既存の「承認者」をフェーズ1では意思決定者として扱う。未設定・旧役割名は承認権限で補完する。 */
function canDecidePost(post) {
  if (!canApprove("pipeline")) return false;
  const me = teamCurrentMember();
  const label = String(post?.approver || "").trim();
  if (!label || !me) return true;
  const assigned = teamResolveMember(label);
  if (assigned) return assigned.id === me.id;
  return teamNormName(label) === teamNormName(me.name) || /責任者|承認者|管理者/.test(label);
}

function defaultDecisionMakerName() {
  const me = teamCurrentMember();
  if (me && canApprove("pipeline")) return me.name;
  const candidate = (state.members || []).find((member) => {
    const role = (state.roles || []).find((row) => row.name === member.systemRole);
    const perms = role?.perms?.[PERM_TAB_LABEL.pipeline];
    return !perms || perms[RP_PERMS.indexOf("承認")] || perms[RP_PERMS.indexOf("管理")];
  });
  return candidate?.name || "";
}
/** 閲覧できるタブだけに絞る。全部落ちる事故を避けるため、0件なら制限しない。 */
function permVisibleTabs() {
  const list = tabs.filter(([id]) => canView(id));
  return list.length ? list : tabs;
}
/** ナビゲーション・絞り込み用の操作かどうか（読み取り専用でも触れてよいもの）。 */
const PERM_SAFE_ATTRS = [
  "data-tab", "data-jump", "data-jump-idea", "data-strategy-tab", "data-design-tab", "data-pipeline-tab",
  "data-analytics-tab", "data-competitor-tab", "data-acc-subtab", "data-set-subtab", "data-comment-tab",
  "data-schedule-mode", "data-cal-nav", "data-cal-goto", "data-sns-select", "data-sns-page", "data-use-open",
  "data-use-close", "data-use-page", "data-al-cat", "data-al-pick", "data-inv-open", "data-inv-close",
  "data-rp-select", "data-rp-expand", "data-team-jump", "data-open-post", "data-close", "data-modal-close",
  "data-acc-jump-users", "data-toggle-sync", "data-open-stop-feedback", "data-feedback-filter",
];
// data-action は追加・削除など書き込み系にも使われるので一括では通さず、UI操作だけを明示的に許可する
const PERM_SAFE_ACTIONS = ["toggle-sync", "save-current-user", "close", "cancel"];
function permIsSafeControl(el) {
  if (el.closest("[data-perm-allow]")) return true;
  if (el.hasAttribute("data-action")) return PERM_SAFE_ACTIONS.includes(el.getAttribute("data-action"));
  if (/filter|search|sort|subtab|-tab$|page|nav|close|jump|expand|toggle-view/i.test(Array.from(el.attributes).map((a) => a.name).join(" "))) return true;
  return PERM_SAFE_ATTRS.some((a) => el.hasAttribute(a));
}
/** 描画後に、閲覧のみのタブを実際に読み取り専用へ落とす。
 *  個別ボタンを1つずつ書き換えるのは漏れるので、描画後の一括処理で担保する。 */
function applyPermissionGate() {
  const section = document.querySelector(`[data-section="${activeTab}"]`) || document.querySelector(".section.active");
  if (!section) return;
  const editable = canEdit(activeTab) || canCreate(activeTab);
  if (editable) return;
  section.classList.add("perm-readonly");
  section.querySelectorAll("input, select, textarea").forEach((el) => {
    if (permIsSafeControl(el)) return;
    el.setAttribute("disabled", "disabled");
  });
  section.querySelectorAll("button").forEach((el) => {
    if (permIsSafeControl(el)) return;
    el.setAttribute("disabled", "disabled");
    el.classList.add("perm-locked");
  });
  section.querySelectorAll("[contenteditable]").forEach((el) => el.removeAttribute("contenteditable"));
}
/** 閲覧のみのときに画面上部へ出す帯。なぜ操作できないのかを明示する。 */
function permBanner() {
  if (!permGateEnabled) return "";
  const role = permCurrentRole();
  if (!role) return "";
  if (canEdit(activeTab) || canCreate(activeTab)) return "";
  const label = PERM_TAB_LABEL[activeTab] || "";
  return `<div class="perm-banner">${icon("info")}<span>あなたのシステムロール「<b>${escapeHtml(role.name)}</b>」では、${escapeHtml(label)}は<b>閲覧のみ</b>です。編集するには管理者に権限の変更を依頼してください。</span>
    <button class="perm-banner-link" data-jump="reports" data-perm-allow>ロール・権限を見る</button></div>`;
}

/* ============ SNSアカウントマスタを「選択元」にする共通処理 ============ */
/** 運用対象として登録されているSNSだけを返す。停止中は除外。未登録なら定数にフォールバック。
 *  ルール・テンプレ・フィルターなど「SNS種別」を選ぶ場所はこれを使い、未運用のSNSを出さない。 */
function activeChannelNames() {
  const list = (state.accounts || []).filter((a) => a.status !== "停止中").map((a) => a.channel);
  const uniq = channelNames.filter((c) => list.includes(c));
  return uniq.length ? uniq : channelNames;
}
/** 運用対象のアカウント（停止中を除く）。同一SNSに複数アカウントがあり得るのでidで識別する。 */
function activeAccounts() { return (state.accounts || []).filter((a) => a.status !== "停止中"); }
function accountById(id) { return (state.accounts || []).find((a) => a.id === id); }
/** channel名から既定のアカウントを推定（旧データの補完用。同一SNSでは先頭＝主アカウント）。 */
function defaultAccountIdFor(channel) {
  const a = (state.accounts || []).find((x) => x.channel === channel && x.status !== "停止中")
        || (state.accounts || []).find((x) => x.channel === channel);
  return a ? a.id : "";
}
/** 「どのアカウントで投稿/対応するか」を選ぶセレクト。表示は 表示名（@handle）、値は accountId。 */
function accountSelect(path, value, channelFallback = "") {
  const opts = activeAccounts().map((a) => ({ value: a.id, label: `${a.displayName || a.channel}（${a.handle || a.channel}）` }));
  const resolved = value || defaultAccountIdFor(channelFallback);
  if (!opts.length) return `<span class="acct-none">SNSアカウント未登録</span>`;
  if (resolved && !opts.some((o) => o.value === resolved)) {
    const a = accountById(resolved);
    opts.unshift({ value: resolved, label: a ? `${a.displayName}（${a.handle}）※停止中` : `${channelFallback}（未登録）` });
  }
  return select(path, resolved, opts);
}
/** accountId が正。channel は集計・フィルターが使うので常に accountId から同期させる。
 *  旧データ（accountIdなし）は channel から推定して補完する。描画のたびに軽く走らせる。 */
function syncAccountLinks() {
  const accounts = state.accounts || [];
  if (!accounts.length) return;
  [["posts", state.posts], ["comments", state.comments], ["ideaBacklog", state.ideaBacklog]].forEach(([, list]) => {
    if (!Array.isArray(list)) return;
    list.forEach((r) => {
      if (!r) return;
      if (!r.accountId) { const id = defaultAccountIdFor(r.channel); if (id) r.accountId = id; return; }
      const a = accountById(r.accountId);
      if (a && a.channel && r.channel !== a.channel) r.channel = a.channel; // アカウント変更にchannelを追従
    });
  });
}

