function normalizeAccounts(nextAccounts, baseAccounts) {
  const seed = baseAccounts || seedAccounts();
  // 旧既定シード（idなし・表示名なし）のまま未編集なら新しいマスタへ移行する
  const isLegacy = Array.isArray(nextAccounts) && nextAccounts.length > 0 && nextAccounts.every((a) => !a.id && !a.displayName);
  const list = (Array.isArray(nextAccounts) && nextAccounts.length && !isLegacy) ? nextAccounts : seed;
  return list.map((a, i) => {
    const channel = a.channel || "Instagram";
    return {
      id: a.id || `acc-${i + 1}`,
      channel,
      displayName: a.displayName || a.handle || channel,
      handle: a.handle || "",
      accountType: a.accountType || (SNS_ACCOUNT_TYPES[channel] || ["個人"])[0],
      purpose: a.purpose || a.role || "",
      role: a.role || "",
      openedAt: a.openedAt || "", startedAt: a.startedAt || "",
      status: accountStatusOptions.includes(a.status) ? a.status : "準備中",
      profileUrl: a.profileUrl || "",
      owner: a.owner || "", subOwner: a.subOwner || "", manager: a.manager || "", approver: a.approver || "",
      commentOwner: a.commentOwner || "", analyticsOwner: a.analyticsOwner || "", emergencyContact: a.emergencyContact || a.manager || "",
      loginId: a.loginId || "",
      passwordVault: a.passwordVault || "1Password（SocialFlow保管庫）",
      vaultUrl: a.vaultUrl || "",
      recoveryEmail: a.recoveryEmail || "", recoveryPhone: a.recoveryPhone || "",
      twoFactor: SNS_2FA_OPTIONS.includes(a.twoFactor) ? a.twoFactor : "未設定",
      twoFactorMethod: a.twoFactorMethod || "未設定",
      twoFactorAdmin: a.twoFactorAdmin || a.manager || "",
      backupCodes: a.backupCodes || "",
      lastAuthUpdate: a.lastAuthUpdate || "", nextCheckAt: a.nextCheckAt || "",
      memo: a.memo || "", riskRule: a.riskRule || "",
      notes: { caution: "", checklist: "", prohibited: "", emergency: "", inquiries: "", restrictions: "", handover: "", ...(a.notes || {}) },
      changeLog: Array.isArray(a.changeLog) ? a.changeLog : [],
    };
  });
}
/** 「要確認」は保存値ではなく派生。二段階認証・担当者・次回確認日から判定する。 */
function snsNeedsAttention(a) {
  if (!a) return false;
  const today = new Date().toISOString().slice(0, 10);
  return a.twoFactor !== "有効" || !a.owner || (a.nextCheckAt && a.nextCheckAt < today);
}
function snsDisplayStatus(a) { return (a.status !== "停止中" && snsNeedsAttention(a)) ? "要確認" : a.status; }
function snsKpi() {
  const list = state.accounts || [];
  return {
    total: list.length,
    active: list.filter((a) => a.status === "運用中").length,
    prep: list.filter((a) => a.status === "準備中").length,
    attention: list.filter(snsNeedsAttention).length,
    stopped: list.filter((a) => a.status === "停止中").length,
  };
}
/** 各タブでこのアカウント（＝チャネル）がどう使われているかを集計する。 */
function snsUsage(a) {
  const ch = a.channel;
  // 同一SNSに複数アカウントがあるため accountId 一致を優先。旧データ（accountIdなし）は channel で拾う。
  const hit = (r) => (r.accountId ? r.accountId === a.id : r.channel === ch);
  const posts = (state.posts || []).filter(hit);
  const mkey = monthKey();
  const upcoming = posts.filter((p) => p.publishAt && p.publishAt >= new Date().toISOString().slice(0, 16)).sort((x, y) => String(x.publishAt).localeCompare(String(y.publishAt)));
  const comments = (state.comments || []).filter((c) => hit(c) && !c.archived);
  const camps = (state.campaigns || []).filter((c) => (c.channels || []).includes(ch));
  const metricPostIds = new Set((state.metrics || []).filter((m) => m.channel === ch && m.postId).map((m) => m.postId));
  // 実績に日付欄が無いため「最終分析日」は実績が入っている投稿の最新公開日で代用する
  const lastMetric = posts.filter((p) => metricPostIds.has(p.id)).map((p) => p.publishAt).filter(Boolean).sort().pop();
  return {
    posts: posts.length,
    drafts: posts.filter((p) => ["企画", "制作"].includes(postWorkflowStage(p))).length,
    pending: posts.filter((p) => postWorkflowStage(p) === "確認").length,
    nextPublish: upcoming.length ? upcoming[0].publishAt : "",
    monthPlanned: posts.filter((p) => postMonthKey(p) === mkey).length,
    undated: posts.filter((p) => !p.publishAt).length,
    unreplied: comments.filter((c) => c.status === "未対応").length,
    needAction: comments.filter((c) => c.status !== "対応済み").length,
    lastComment: comments.map((c) => c.receivedAt).filter(Boolean).sort().pop() || "",
    campActive: camps.filter((c) => c.status === "進行中").length,
    campPlanned: camps.filter((c) => c.status === "企画中" || c.status === "準備中").length,
    metricsFilled: posts.filter((p) => metricPostIds.has(p.id)).length,
    metricsMissing: posts.filter((p) => postIsPublished(p) && !metricPostIds.has(p.id)).length,
    lastAnalysis: lastMetric || "",
  };
}
