/* ============ 設定 ＞ レポート設定 ============ */
/** 次回の配信予定日時を、曜日／日付指定から実際に計算する。 */
function rsNextRun(kind) {
  const rs = state.reportSettings || {};
  const r = rs[kind] || {};
  if (!r.enabled) return null;
  const [hh, mm] = String(r.time || "09:00").split(":").map(Number);
  const now = new Date();
  const d = new Date(now.getFullYear(), now.getMonth(), now.getDate(), hh || 9, mm || 0, 0);
  if (kind === "weekly") {
    const target = RS_WEEK_DAYS.indexOf(r.day);
    const want = target < 0 ? 1 : (target + 1) % 7; // RS_WEEK_DAYS[0]=月曜 → JSでは1
    let diff = (want - d.getDay() + 7) % 7;
    if (diff === 0 && d <= now) diff = 7;
    d.setDate(d.getDate() + diff);
  } else {
    if (r.day === "毎月月末") { d.setMonth(d.getMonth() + 1, 0); if (d <= now) { d.setMonth(d.getMonth() + 2, 0); } }
    else {
      const day = r.day === "毎月15日" ? 15 : 1;
      d.setDate(day);
      if (d <= now) d.setMonth(d.getMonth() + 1);
    }
  }
  return d;
}
function rsFmtNext(d) {
  if (!d) return "—";
  const w = ["日", "月", "火", "水", "木", "金", "土"][d.getDay()];
  return `${d.getFullYear()}/${String(d.getMonth() + 1).padStart(2, "0")}/${String(d.getDate()).padStart(2, "0")}（${w}）${String(d.getHours()).padStart(2, "0")}:${String(d.getMinutes()).padStart(2, "0")}`;
}
function setReportView() {
  const rs = state.reportSettings || {};
  const w = rs.weekly || {}, m = rs.monthly || {}, c = rs.common || {};
  const contents = rs.contents || [];
  const enabledCount = (w.enabled ? 1 : 0) + (m.enabled ? 1 : 0);
  const nextW = rsNextRun("weekly"), nextM = rsNextRun("monthly");
  const next = [nextW, nextM].filter(Boolean).sort((a, b) => a - b)[0];
  const nextKind = next && nextW && next.getTime() === nextW.getTime() ? "週次" : "月次";
  const allTo = new Set([...(w.to || []), ...(m.to || [])]);
  const allCc = new Set([...(w.cc || []), ...(m.cc || [])]);
  const allFormats = RS_FORMATS.filter(([n]) => (w.formats || []).includes(n) || (m.formats || []).includes(n)).map(([n]) => n);
  const toggle = (on, attr) => `<button class="set-toggle ${on ? "on" : ""}" ${attr}><span></span></button>`;
  const chips = (list, kind, field) => `<div class="rs-chips">${(list || []).map((n) => `<span class="rs-chip">${escapeHtml(n)}<button data-rs-chip-del="${kind}|${field}|${escapeHtml(n)}" title="外す">${icon("close")}</button></span>`).join("")}<button class="rs-chip-add" data-rs-chip-add="${kind}|${field}">${icon("plus")}</button></div>`;

  const block = (kind, r, label, sec, periodOpts, dayOpts, dayLabel) => `
    <div class="card tm-card rs-card">
      <div class="rs-card-h">
        <h3><span class="ws-sec">${sec}</span>${label}</h3>
        ${toggle(r.enabled, `data-rs-toggle="${kind}|enabled"`)}<em class="rs-en">${r.enabled ? "有効" : "無効"}</em>
      </div>
      <div class="rs-grid2">
        <label class="rs-field"><span>対象期間</span>${select(`reportSettings.${kind}.period`, r.period, periodOpts)}</label>
        <label class="rs-field"><span>${dayLabel}</span>${select(`reportSettings.${kind}.day`, r.day, dayOpts)}</label>
        <label class="rs-field"><span>配信時刻</span>${input(`reportSettings.${kind}.time`, r.time, "time")}</label>
      </div>
      <div class="rs-field">
        <span>出力形式</span>
        <div class="rs-formats">${RS_FORMATS.map(([n]) => `<label class="rs-check"><input type="checkbox" ${(r.formats || []).includes(n) ? "checked" : ""} data-rs-format="${kind}|${n}"><b>${n}</b></label>`).join("")}</div>
      </div>
      <div class="rs-field"><span>配信先（To）</span>${chips(r.to, kind, "to")}</div>
      <div class="rs-field"><span>CC</span>${chips(r.cc, kind, "cc")}</div>
      <div class="rs-switches">
        <span class="rs-sw"><em>自動生成</em>${toggle(r.autoGen, `data-rs-toggle="${kind}|autoGen"`)}</span>
        <span class="rs-sw"><em>自動送信</em>${toggle(r.autoSend, `data-rs-toggle="${kind}|autoSend"`)}</span>
      </div>
    </div>`;

  return `
    <div class="rs-wrap">
      <div class="card tm-card rs-summary">
        <h3 class="rs-sum-title">レポート設定サマリー</h3>
        <div class="rs-sum-row">
          <div class="rs-sum"><span class="rs-sum-ic rs-sum-ic--green">${icon("check")}</span><div><small>有効なレポート</small><strong>${enabledCount}<i>件</i></strong><em>週次：${w.enabled ? "有効" : "無効"} / 月次：${m.enabled ? "有効" : "無効"}</em></div></div>
          <div class="rs-sum"><span class="rs-sum-ic rs-sum-ic--blue">${icon("calendar")}</span><div><small>次回配信予定</small><strong class="rs-sum-sm">${nextKind}レポート</strong><em>${rsFmtNext(next)}</em></div></div>
          <div class="rs-sum"><span class="rs-sum-ic rs-sum-ic--violet">${icon("send")}</span><div><small>配信先（合計）</small><strong>${allTo.size}<i>件</i></strong><em>To：${allTo.size}件 / CC：${allCc.size}件</em></div></div>
          <div class="rs-sum"><span class="rs-sum-ic rs-sum-ic--amber">${icon("doc")}</span><div><small>出力形式</small><strong class="rs-sum-sm">${allFormats.join(" / ") || "—"}</strong><em>&nbsp;</em></div></div>
          <div class="rs-sum"><span class="rs-sum-ic rs-sum-ic--gray">${icon("reset")}</span><div><small>最終テスト送信</small><strong class="rs-sum-sm">${accFmtDateTime(rs.lastSentAt)}</strong><em>送信元：${escapeHtml(rs.lastSentBy || "—")}</em></div></div>
        </div>
      </div>

      <div class="rs-3col">
        ${block("weekly", w, "週次レポート", "A.", RS_WEEK_PERIODS, RS_WEEK_DAYS, "配信曜日")}
        ${block("monthly", m, "月次レポート", "B.", RS_MONTH_PERIODS, RS_MONTH_DAYS, "配信日")}

        <div class="card tm-card rs-card">
          <div class="rs-card-h"><h3><span class="ws-sec">C.</span>配信先・出力形式の共通設定</h3></div>
          <div class="rs-field"><span>出力形式の役割</span>
            <div class="rs-roles">${RS_FORMATS.map(([n, d]) => `<div class="rs-role"><b class="rs-role-tag rs-role-tag--${n.toLowerCase()}">${n}</b><small>${escapeHtml(d)}</small></div>`).join("")}</div>
          </div>
          <div class="rs-field"><span>共通配信設定</span>
            <div class="rs-grid2">
              <label class="rs-field"><span>デフォルト送信元</span>${input(`reportSettings.common.defaultTo`, c.defaultTo || "")}</label>
              <label class="rs-field"><span>エンコード</span>${select(`reportSettings.common.encoding`, c.encoding || "UTF-8", RS_ENCODINGS)}</label>
            </div>
          </div>
          <label class="rs-check rs-check--row"><input type="checkbox" ${c.notifyOnDeliver ? "checked" : ""} data-rs-common="notifyOnDeliver"><span>配信結果をアプリ内通知に表示する</span></label>
          <label class="rs-check rs-check--row"><input type="checkbox" ${c.useGas ? "checked" : ""} data-rs-common="useGas"><span>自動配信は Google Apps Script の時間主導トリガーで実行される</span></label>
          <p class="rs-note">${icon("info")} ブラウザを閉じている間の自動送信はHTMLだけでは実行できません。Apps Scriptの時間主導トリガー側で実行してください。配信結果・配信履歴はApps Script側のログで確認してください。</p>
        </div>
      </div>

      <div class="rs-2col">
        <div class="card tm-card">
          <div class="tm-card-h"><h3><span class="ws-sec">D.</span>レポートに含める内容</h3></div>
          <p class="ws-note">レポートに含める項目を選びます。</p>
          <div class="rs-contents">
            ${RS_CONTENTS.map(([name, source, tab, sub]) => {
              const on = contents.includes(name);
              return `<button class="rs-content ${on ? "on" : ""}" data-rs-content="${escapeHtml(name)}">
                <span class="rs-content-cb">${on ? icon("check") : ""}</span>
                <strong>${escapeHtml(name)}</strong>
                <small>${escapeHtml(source)}</small>
              </button>`;
            }).join("")}
          </div>
        </div>

        <div class="card tm-card">
          <div class="tm-card-h"><h3><span class="ws-sec">E.</span>データ連携（項目とデータ元）</h3></div>
          <div class="tm-table-wrap">
            <table class="tm-table rs-table">
              <thead><tr><th>レポート項目</th><th>データ元</th><th></th></tr></thead>
              <tbody>${RS_CONTENTS.map(([name, source, tab, sub]) => `
                <tr class="${contents.includes(name) ? "" : "is-off"}">
                  <td class="rs-t-name">${escapeHtml(name)}</td>
                  <td class="rs-t-src">${escapeHtml(source)}</td>
                  <td><button class="tm-icobtn" data-jump="${tab}" ${sub && tab === "analytics" ? `data-jump-analytics="${sub}"` : ""} title="データ元を開く">${icon("external")}</button></td>
                </tr>`).join("")}
              </tbody>
            </table>
          </div>
        </div>
      </div>
    </div>
  `;
}

/* ============ 設定 ＞ データ管理 ============ */
let dmExportPick = DM_EXPORT_TARGETS.map(([k]) => k);   // エクスポート対象の選択
let dmDeletePick = [];                                   // 対象別削除の選択
let dmConfirmName = "";                                  // 全削除時に入力するワークスペース名
let dmBackupBeforeDelete = true;
let dmImportPreview = null;                              // インポートのプレビュー結果

function dmBackups() { const b = safeParse(safeStorage.getItem(backupStoreKey)); return Array.isArray(b) ? b : []; }
function dmBytes(n) {
  if (!Number.isFinite(n) || n <= 0) return "0 B";
  if (n < 1024) return `${n} B`;
  if (n < 1024 * 1024) return `${(n / 1024).toFixed(1)} KB`;
  return `${(n / 1024 / 1024).toFixed(1)} MB`;
}
function dmStateBytes() { try { return new Blob([JSON.stringify(state)]).size; } catch (e) { return JSON.stringify(state).length; } }
function dmStorageBytes() {
  let total = 0;
  try { for (let i = 0; i < localStorage.length; i += 1) { const k = localStorage.key(i); total += (k || "").length + (localStorage.getItem(k) || "").length; } }
  catch (e) { return dmStateBytes(); }
  return total * 2; // UTF-16 換算
}
/** state に含まれる画像（data URI）の数。localStorage を圧迫する主因なので単独で出す。 */
function dmImageCount() {
  let n = 0;
  const walk = (v) => {
    if (typeof v === "string") { if (v.startsWith("data:image")) n += 1; return; }
    if (Array.isArray(v)) { v.forEach(walk); return; }
    if (v && typeof v === "object") Object.values(v).forEach(walk);
  };
  walk(state);
  return n;
}
function dmUsage() {
  const bytes = dmStorageBytes();
  const LIMIT = 5 * 1024 * 1024; // localStorage のおおよその上限
  return {
    posts: (state.posts || []).length,
    images: dmImageCount(),
    comments: (state.comments || []).length,
    metrics: (state.metrics || []).length,
    competitors: (state.competitors || []).length + (state.competitorPosts || []).length,
    storage: bytes,
    sheetRows: Object.values(state).reduce((s, v) => s + (Array.isArray(v) ? v.length : 0), 0),
    total: dmStateBytes(),
    pct: Math.min(100, Math.round((bytes / LIMIT) * 100)),
    limit: LIMIT,
  };
}
function dmSyncLabel() {
  const st = syncStatus.state;
  if (!syncConfig.apiUrl) return { tone: "gray", text: "未接続", note: "Apps Script URLが未設定です" };
  if (st === "offline") return { tone: "red", text: "接続エラー", note: syncStatus.message || "接続できません" };
  if (st === "conflict") return { tone: "amber", text: "競合あり", note: syncStatus.message || "" };
  if (st === "syncing") return { tone: "blue", text: "同期中", note: "" };
  return { tone: "green", text: "接続中", note: "正常に接続されています" };
}
function dmEditSyncUrl() {
  collectFormValues();
  const v = window.prompt("Apps ScriptでデプロイしたWebアプリのURLを貼り付けてください（空にすると接続解除）", syncConfig.apiUrl || "");
  if (v === null) return;
  syncConfig.apiUrl = v.trim();
  try { safeStorage.setItem(syncUrlKey, syncConfig.apiUrl); } catch (e) { /* noop */ }
  render(); showSaved(syncConfig.apiUrl ? "接続先を保存しました" : "接続を解除しました");
}
async function dmTestConnection() {
  if (!syncConfig.apiUrl) { showSaved("先に接続先を設定してください"); return; }
  showSaved("接続テスト中…");
  try {
    const res = await fetch(syncConfig.apiUrl, { method: "GET" });
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    await res.json();
    syncStatus.state = "idle"; syncStatus.message = "";
    render(); showSaved("接続テストに成功しました");
  } catch (e) {
    syncStatus.state = "offline"; syncStatus.message = "接続できません";
    render(); showSaved(`接続テストに失敗：${e.message}`);
  }
}
function dmBackupNow() {
  collectFormValues();
  createLocalBackup(JSON.stringify(state), "手動バックアップ");
  persist(); render(); showSaved("バックアップを作成しました");
}
function dmDownloadBackup(i) {
  const b = dmBackups()[i]; if (!b) return;
  downloadBlob(JSON.stringify(b.data, null, 2), `sns-ops-backup-${String(b.createdAt).slice(0, 10)}.json`);
  showSaved("バックアップをダウンロードしました");
}
function dmRestoreBackup(i) {
  const b = dmBackups()[i]; if (!b) return;
  if (!window.confirm(`${accFmtDateTime(String(b.createdAt).slice(0, 16))} のバックアップで現在のデータを置き換えます。よろしいですか？\n（実行前に現在のデータも自動バックアップします）`)) return;
  createLocalBackup(JSON.stringify(state), "復元前バックアップ");
  state = normalizeState({ ...defaultState(), ...b.data });
  persist(); render(); showSaved("バックアップから復元しました");
}
function dmDeleteBackup(i) {
  const list = dmBackups(); if (!list[i]) return;
  if (!window.confirm("このバックアップを削除しますか？")) return;
  list.splice(i, 1);
  try { safeStorage.setItem(backupStoreKey, JSON.stringify(list)); } catch (e) { /* noop */ }
  render(); showSaved("バックアップを削除しました");
}
/** 選択された対象だけをJSON/CSVで書き出す（各タブのエクスポートは「表示中の一覧」なので役割が違う）。 */
function dmPickedData() {
  const out = {};
  dmExportPick.forEach((k) => {
    if (k === "settings") out.settings = { workspace: state.workspace, reportSettings: state.reportSettings, alarms: state.alarms, roles: state.roles };
    // 改善アクションは campaigns[].kaizen の中にあるので、キャンペーン名を付けて平坦化する
    else if (k === "kaizen") out.kaizen = (state.campaigns || []).flatMap((c) => (c.kaizen || []).map((r) => ({ campaignId: c.id, campaign: c.name, ...r })));
    else out[k] = state[k] || [];
  });
  return out;
}
function dmExportJson() {
  collectFormValues();
  if (!dmExportPick.length) { showSaved("エクスポートする対象を選んでください"); return; }
  downloadBlob(JSON.stringify({ exportedAt: new Date().toISOString(), workspace: (state.workspace || {}).name, data: dmPickedData() }, null, 2),
    `socialflow-export-${new Date().toISOString().slice(0, 10)}.json`);
  showSaved(`${dmExportPick.length}種類のデータをエクスポートしました`);
}
function dmExportCsv() {
  collectFormValues();
  const picked = dmPickedData();
  const parts = [];
  Object.entries(picked).forEach(([key, val]) => {
    const rows = Array.isArray(val) ? val : [val];
    if (!rows.length) return;
    const cols = [...new Set(rows.flatMap((r) => Object.keys(r || {})))];
    parts.push(`# ${key}`);
    parts.push(cols.map((c) => `"${c}"`).join(","));
    rows.forEach((r) => parts.push(cols.map((c) => {
      const v = r ? r[c] : "";
      const s = (v && typeof v === "object") ? JSON.stringify(v) : String(v ?? "");
      return `"${s.replace(/"/g, '""')}"`;
    }).join(",")));
    parts.push("");
  });
  downloadBlob("﻿" + parts.join("\n"), `socialflow-export-${new Date().toISOString().slice(0, 10)}.csv`);
  showSaved("CSVを一括エクスポートしました");
}
/** インポートは即上書きせず、必ずプレビューを挟む。 */
function dmPreviewImport(file) {
  const reader = new FileReader();
  reader.onload = () => {
    const text = String(reader.result || "");
    let parsed = null;
    try { parsed = JSON.parse(text); } catch (e) { parsed = null; }
    if (!parsed) { dmImportPreview = { error: "JSON形式として読み取れませんでした（現在はJSONのみ対応）", file: file.name }; render(); return; }
    const data = parsed.data && typeof parsed.data === "object" ? parsed.data : parsed;
    const rows = Object.entries(data)
      .filter(([, v]) => Array.isArray(v) || (v && typeof v === "object"))
      .map(([k, v]) => {
        const incoming = Array.isArray(v) ? v.length : 1;
        const current = Array.isArray(state[k]) ? state[k].length : (state[k] ? 1 : 0);
        const ids = new Set((Array.isArray(state[k]) ? state[k] : []).map((r) => r && r.id).filter(Boolean));
        const dup = Array.isArray(v) ? v.filter((r) => r && r.id && ids.has(r.id)).length : 0;
        return { key: k, incoming, current, dup };
      });
    dmImportPreview = { file: file.name, size: file.size, rows, raw: data, mode: "merge" };
    render();
  };
  reader.readAsText(file);
}
function dmApplyImport() {
  if (!dmImportPreview || dmImportPreview.error) return;
  const mode = dmImportPreview.mode;
  if (!window.confirm(`「${mode === "overwrite" ? "上書き" : mode === "skip" ? "重複はスキップ" : "追加（マージ）"}」でインポートします。よろしいですか？\n（実行前に現在のデータを自動バックアップします）`)) return;
  createLocalBackup(JSON.stringify(state), "インポート前バックアップ");
  const data = dmImportPreview.raw;
  Object.entries(data).forEach(([k, v]) => {
    if (Array.isArray(v)) {
      if (mode === "overwrite") state[k] = v;
      else {
        const cur = Array.isArray(state[k]) ? state[k] : [];
        const ids = new Set(cur.map((r) => r && r.id).filter(Boolean));
        const add = v.filter((r) => !(r && r.id && ids.has(r.id)));
        state[k] = mode === "skip" ? [...cur, ...add] : [...cur, ...add];
      }
    } else if (v && typeof v === "object" && k === "settings") {
      Object.assign(state, v);
    }
  });
  state = normalizeState({ ...defaultState(), ...state });
  dmImportPreview = null;
  persist(); render(); showSaved("インポートしました");
}
function dmDeleteSelected() {
  collectFormValues();
  if (!wsCanEdit()) { showSaved("データ削除は管理者のみ可能です"); return; }
  if (!dmDeletePick.length) { showSaved("削除する対象を選んでください"); return; }
  const labels = DM_DELETE_TARGETS.filter(([k]) => dmDeletePick.includes(k)).map(([, l]) => l);
  if (!window.confirm(`次のデータを削除します。元に戻せません。\n\n・${labels.join("\n・")}`)) return;
  if (dmBackupBeforeDelete) createLocalBackup(JSON.stringify(state), "削除前バックアップ");
  dmDeletePick.forEach((k) => { if (Array.isArray(state[k])) state[k] = []; });
  dmDeletePick = [];
  persist(); render(); showSaved(`${labels.length}種類のデータを削除しました`);
}
function dmDeleteAll() {
  collectFormValues();
  if (!wsCanEdit()) { showSaved("データ削除は管理者のみ可能です"); return; }
  const wsName = (state.workspace || {}).name || "";
  if (dmConfirmName.trim() !== wsName) { showSaved("ワークスペース名が一致しません"); return; }
  if (!window.confirm(`「${wsName}」のすべてのデータを削除します。元に戻せません。本当によろしいですか？`)) return;
  if (dmBackupBeforeDelete) createLocalBackup(JSON.stringify(state), "全削除前バックアップ");
  try { safeStorage.removeItem(storeKey); } catch (e) { /* noop */ }
  window.location.reload();
}

