  const toggle = (on, attr) => `<button class="set-toggle ${on ? "on" : ""}" ${attr}><span></span></button>`;
  const chDot = (a, key) => `<button class="al-ch ${a.channels[key] ? "on" : ""}" data-al-ch="${a.id}|${key}" title="${alChannelReady(key) ? "" : "未接続"}">${icon((AL_CHANNELS.find(([k]) => k === key) || [])[2])}</button>`;
