function accFmtDateTime(iso) { if (!iso) return "—"; const s = String(iso).replace("T", " "); return s.slice(0, 4) + "/" + s.slice(5, 7) + "/" + s.slice(8, 10) + " " + s.slice(11, 16); }
function accFmtDate(key) { if (!key || !/^\d{4}-\d\d-\d\d/.test(key)) return "—"; return key.slice(5, 7) + "/" + key.slice(8, 10); }
function accFmtFullDate(key) { if (!key || !/^\d{4}-\d\d-\d\d/.test(key)) return "—"; return key.slice(0, 4) + "/" + key.slice(5, 7) + "/" + key.slice(8, 10); }
function accSlug(channel) { return ({ Instagram: "insta", X: "x", Facebook: "fb", LinkedIn: "linkedin", Threads: "threads", TikTok: "tiktok", "YouTube Shorts": "yt", Note: "note", LINE: "line" }[channel] || "sns"); }
function accDeriveLogin(a) { return `${accSlug(a.channel)}@theacademy.jp`; }
function accDeriveUrl(a) { const d = ({ Instagram: "instagram.com", X: "x.com", Facebook: "facebook.com", LinkedIn: "linkedin.com/company", Threads: "threads.net", TikTok: "tiktok.com", "YouTube Shorts": "youtube.com", Note: "note.com", LINE: "line.me" }[a.channel] || "example.com"); return `https://${d}/${(a.handle || "theacademy").replace(/\s/g, "")}`; }
// システムロールのピル表示（色は state.roles の色をそのまま使う＝マスタはロールのみ）
function accRoleByName(name) { return (state.roles || []).find((r) => r.name === name); }
function accRoleById(id) { return (state.roles || []).find((r) => r.id === id); }
function accRolePill(r) { const role = accRoleByName(r); const tone = role ? role.color : "green"; return `<span class="acc-role acc-role--${tone}">${escapeHtml(r || "")}</span>`; }

/* ============ ロール・権限：データモデル ============ */
// ※ RP_TABS / RP_PERMS / RP_SUBTABS はファイル冒頭で定義済み（初期stateのseedより前に必要なため）
function rpEmptyRow() { return [false, false, false, false, false, false, false]; }
function rpRow(...vals) { return RP_PERMS.map((_, i) => Boolean(vals[i])); }
function rpFillAll(row) { const o = {}; RP_TABS.forEach((t) => { o[t] = row.slice(); }); return o; }
function rpRolePerms(role, tab) { return (role && role.perms && role.perms[tab]) || rpEmptyRow(); }
function rpRoleSubPerms(role, tab, sub) {
  if (role && role.subPerms && role.subPerms[tab] && role.subPerms[tab][sub]) return role.subPerms[tab][sub];
  return rpRolePerms(role, tab);
}
function rpRowsEqual(a, b) { return RP_PERMS.every((_, i) => Boolean(a[i]) === Boolean(b[i])); }
function rpRowLabel(row) { const on = RP_PERMS.filter((_, i) => row[i]); return on.length ? on.join("・") : "権限なし"; }

function seedRoles() {
  const createdAt = "2024-01-15T09:30", updatedAt = "2025-07-10T11:25";
  const adminPerms = rpFillAll(rpRow(1, 1, 1, 1, 1, 1, 1));
  const managerPerms = rpFillAll(rpRow(1, 1, 1, 1, 0, 1, 0));
  const editorPerms = rpFillAll(rpRow(1, 1, 1, 0, 0, 0, 0));
  const approverPerms = rpFillAll(rpRow(1, 0, 0, 1, 0, 0, 0));
  const viewerPerms = rpFillAll(rpRow(1, 0, 0, 0, 0, 0, 0));
  const partnerPerms = rpFillAll(rpEmptyRow());
  ["投稿管理", "カレンダー", "コメント管理"].forEach((t) => { partnerPerms[t] = rpRow(1, 0, 0, 0, 0, 0, 0); });
  return [
    { id: "role-admin", name: "管理者", desc: "すべての機能と設定へアクセスできます", standard: true, type: "標準ロール", color: "indigo", icon: "shield", status: "有効", createdAt, updatedAt, perms: adminPerms, subPerms: {} },
    {
      id: "role-manager", name: "マネージャー", desc: "運用・承認・分析・出力が可能です", standard: true, type: "標準ロール", color: "violet", icon: "users", status: "有効", createdAt, updatedAt, perms: managerPerms,
      subPerms: { "分析・レポート": { "ダッシュボード": rpRow(1, 0, 0, 0, 0, 0, 0), "データ入力": rpRow(1, 1, 1, 0, 0, 0, 0), "投稿別分析": rpRow(1, 0, 1, 0, 0, 0, 0), "SNS比較": rpRow(1, 0, 0, 0, 0, 0, 0), "改善管理": rpRow(1, 1, 1, 1, 0, 0, 0) } },
    },
    {
      id: "role-editor", name: "編集者", desc: "投稿やデザインの作成・編集が可能です", standard: true, type: "標準ロール", color: "green", icon: "pencil", status: "有効", createdAt, updatedAt, perms: editorPerms,
      subPerms: { "デザイン管理": { "ブランドガイドライン": rpRow(1, 0, 0, 0, 0, 0, 0), "テンプレート": rpRow(1, 1, 1, 0, 0, 0, 0), "リンク集": rpRow(1, 1, 1, 0, 0, 0, 0), "ハッシュタグ": rpRow(1, 0, 0, 0, 0, 0, 0), "SNS別ルール": rpRow(1, 0, 0, 0, 0, 0, 0) } },
    },
    {
      id: "role-approver", name: "承認者", desc: "閲覧・コメント・承認が中心です", standard: true, type: "標準ロール", color: "blue", icon: "check", status: "有効", createdAt, updatedAt, perms: approverPerms,
      subPerms: { "投稿管理": { "ボード": rpRow(1, 0, 0, 1, 0, 0, 0), "一覧": rpRow(1, 0, 0, 1, 0, 0, 0), "下書き": rpRow(1, 0, 0, 1, 0, 0, 0), "アーカイブ": rpRow(1, 0, 0, 0, 0, 0, 0) } },
    },
    { id: "role-viewer", name: "閲覧者", desc: "すべてのデータを閲覧できます", standard: true, type: "標準ロール", color: "amber", icon: "eye", status: "有効", createdAt, updatedAt, perms: viewerPerms, subPerms: {} },
    { id: "role-partner", name: "外部パートナー", desc: "外部パートナー向けの限定アクセスです", standard: false, type: "カスタムロール", color: "slate", icon: "users", status: "有効", createdAt: "2025-03-02T10:00", updatedAt: "2025-03-02T10:00", perms: partnerPerms, subPerms: {} },
  ];
}
function seedRoleChangeLog() {
  return [
    { id: "rlog-1", at: "2025-07-10T11:25", by: "山田 太郎", roleName: "管理者", target: "アカウント管理", before: "権限なし", after: "閲覧・作成・編集・承認・削除・エクスポート・管理" },
    { id: "rlog-2", at: "2025-06-02T15:10", by: "山田 太郎", roleName: "承認者", target: "投稿管理 > アーカイブ", before: "権限なし", after: "閲覧" },
    { id: "rlog-3", at: "2025-05-20T09:40", by: "小林 大輔", roleName: "マネージャー", target: "分析・レポート > データ入力", before: "閲覧", after: "閲覧・作成・編集" },
  ];
}
function normalizeRoles(nextRoles, baseRoles) {
  const seed = baseRoles || seedRoles();
  const list = Array.isArray(nextRoles) && nextRoles.length ? nextRoles : seed;
  return list.map((r) => {
    const perms = {};
    RP_TABS.forEach((t) => { perms[t] = (r.perms && Array.isArray(r.perms[t])) ? r.perms[t] : rpEmptyRow(); });
    const subPerms = (r.subPerms && typeof r.subPerms === "object") ? r.subPerms : {};
    return { id: r.id || generateId("role"), name: r.name || "", desc: r.desc || "", standard: !!r.standard, type: r.type || (r.standard ? "標準ロール" : "カスタムロール"), color: r.color || "blue", icon: r.icon || "users", status: r.status || "有効", createdAt: r.createdAt || "", updatedAt: r.updatedAt || "", perms, subPerms };
  });
}

/* ---- ロール・権限：編集用の下書き（保存前はここだけを書き換える） ---- */
let rolesDraft = null;
function rpCloneTabMap(map) { const o = {}; Object.keys(map || {}).forEach((k) => { o[k] = (map[k] || rpEmptyRow()).slice(); }); return o; }
function rpCloneSubMap(map) { const o = {}; Object.keys(map || {}).forEach((tab) => { o[tab] = rpCloneTabMap(map[tab]); }); return o; }
function buildRolesDraft() { const d = {}; (state.roles || []).forEach((r) => { d[r.id] = { perms: rpCloneTabMap(r.perms), subPerms: rpCloneSubMap(r.subPerms) }; }); return d; }
function accRoleDraftFor(roleId) {
  if (!rolesDraft) rolesDraft = buildRolesDraft();
  if (!rolesDraft[roleId]) { const role = accRoleById(roleId); rolesDraft[roleId] = { perms: rpCloneTabMap(role && role.perms), subPerms: rpCloneSubMap(role && role.subPerms) }; }
  return rolesDraft[roleId];
}
function rpDraftPerms(roleId, tab) { return accRoleDraftFor(roleId).perms[tab] || rpEmptyRow(); }
function rpDraftSubPerms(roleId, tab, sub) {
  const d = accRoleDraftFor(roleId);
  if (d.subPerms[tab] && d.subPerms[tab][sub]) return d.subPerms[tab][sub];
  return rpDraftPerms(roleId, tab);
}
function accCellChanged(roleId, tab, sub, colIndex) {
  const role = accRoleById(roleId);
  if (!role) return false;
  const before = sub ? rpRoleSubPerms(role, tab, sub) : rpRolePerms(role, tab);
  const after = sub ? rpDraftSubPerms(roleId, tab, sub) : rpDraftPerms(roleId, tab);
  return Boolean(before[colIndex]) !== Boolean(after[colIndex]);
}
function accTogglePermCell(roleId, tab, sub, colIndex) {
  const draft = accRoleDraftFor(roleId);
  let row;
  if (sub) {
    if (!draft.subPerms[tab]) draft.subPerms[tab] = {};
    if (!draft.subPerms[tab][sub]) draft.subPerms[tab][sub] = rpDraftPerms(roleId, tab).slice();
    row = draft.subPerms[tab][sub];
  } else {
    if (!draft.perms[tab]) draft.perms[tab] = rpEmptyRow();
    row = draft.perms[tab];
  }
  const willTurnOn = !row[colIndex];
  row[colIndex] = willTurnOn;
  if (colIndex === 0 && !willTurnOn) { for (let i = 0; i < row.length; i += 1) row[i] = false; }
  else if (colIndex === 6 && willTurnOn) { for (let i = 0; i < row.length; i += 1) row[i] = true; }
  else if (willTurnOn) { row[0] = true; }
  render();
}
function accPermChangeList() {
  const changes = [];
  (state.roles || []).forEach((role) => {
    const draft = rolesDraft ? rolesDraft[role.id] : null;
    if (!draft) return;
    RP_TABS.forEach((tab) => {
      const before = rpRolePerms(role, tab);
      const after = draft.perms[tab] || before;
      if (!rpRowsEqual(before, after)) changes.push({ roleId: role.id, roleName: role.name, tab, sub: "", before, after });
      const subs = RP_SUBTABS[tab];
      if (subs && draft.subPerms[tab]) {
        subs.forEach((sub) => {
          const subAfter = draft.subPerms[tab][sub];
          if (!subAfter) return;
          const subBefore = rpRoleSubPerms(role, tab, sub);
          if (!rpRowsEqual(subBefore, subAfter)) changes.push({ roleId: role.id, roleName: role.name, tab, sub, before: subBefore, after: subAfter });
        });
      }
    });
  });
  return changes;
}
function accSavePermissions() {
  collectFormValues();
  const changes = accPermChangeList();
  if (!changes.length) return;
  const nowIso = new Date().toISOString().slice(0, 19);
  const by = (teamCurrentMember() || {}).name || "";
  if (!Array.isArray(state.roleChangeLog)) state.roleChangeLog = [];
  changes.forEach((c) => {
    state.roleChangeLog.unshift({ id: generateId("rlog"), at: nowIso, by, roleName: c.roleName, target: c.sub ? `${c.tab} > ${c.sub}` : c.tab, before: rpRowLabel(c.before), after: rpRowLabel(c.after) });
    const role = accRoleById(c.roleId);
    if (!role) return;
    if (c.sub) { if (!role.subPerms) role.subPerms = {}; if (!role.subPerms[c.tab]) role.subPerms[c.tab] = {}; role.subPerms[c.tab][c.sub] = c.after.slice(); }
    else { role.perms[c.tab] = c.after.slice(); }
    role.updatedAt = nowIso.slice(0, 16);
  });
  rolesDraft = buildRolesDraft();
  persist();
  showSaved("権限設定を保存しました");
  render();
}
function accRoleAssignedMembers(role) { return (state.members || []).filter((m) => m.systemRole === role.name); }
function accRolesKpi() {
  const roles = state.roles || [], members = state.members || [];
  const standardCount = roles.filter((r) => r.standard).length;
  const customCount = roles.length - standardCount;
  const adminCount = members.filter((m) => m.systemRole === "管理者").length;
  const unassigned = members.filter((m) => !roles.some((r) => r.name === m.systemRole)).length;
  return {
    total: roles.length, standardCount, customCount,
    adminCount, adminPct: members.length ? Math.round((adminCount / members.length) * 100) : 0,
    customPct: roles.length ? Math.round((customCount / roles.length) * 100) : 0,
    unassigned,
  };
}
function accRolePermSummaryDraft(roleId) { return RP_PERMS.map((_, ci) => RP_TABS.filter((t) => rpDraftPerms(roleId, t)[ci]).length); }

const ACC_SUBTABS = [["users", "ユーザー一覧（マスタ）"], ["roles", "ロール・権限"], ["invites", "招待管理"], ["sns", "SNSアカウント情報"], ["login", "利用履歴"]];
let activeAccountTab = "users";
