  document.querySelectorAll("[data-idea-filter-clear]").forEach((el) => el.addEventListener("click", () => { ideaChannelFilter = ""; render(); }));
  // 投稿案の対象ペルソナ（複数選択）。投稿化時に先頭が投稿の personaId に引き継がれる。
  // 編集パネルは editingIdeaId で開いたままなので、クリックしたチップの is-on だけ即時トグルし
  // 再描画しない（カード上部の表示チップは次の描画で追随）。
  document.querySelectorAll("[data-toggle-idea-persona]").forEach((el) => {
    el.addEventListener("click", (event) => {
      event.stopPropagation();
      const idea = state.ideaBacklog[Number(el.dataset.toggleIdeaPersona)];
      if (!idea) return;
      if (!Array.isArray(idea.personaIds)) idea.personaIds = [];
      const pid = el.dataset.persona;
      const pos = idea.personaIds.indexOf(pid);
      if (pos >= 0) idea.personaIds.splice(pos, 1);
      else idea.personaIds.push(pid);
      el.classList.toggle("is-on");
      persist(false);
    });
  });
