    const now = new Date();
    rs.lastSentAt = new Date(now.getTime() - now.getTimezoneOffset() * 60000).toISOString().slice(0, 16);
    rs.lastSentBy = (teamCurrentMember() || {}).name || "";
    persist(); render();
